        Some
          (Wire_fleet.Candle_ready
             {
               issued_milli = "10000";
               burned_milli = "2500";
               circulating_milli = "7500";
             });
      turn_pulses =
        [
          ( "alpha-builder"
          , {
              Wire_fleet.known_since = Float.of_int (wall_slot - 3600);
              slots =
                [
                  {
                    starts_at = wall_slot - 3600;
                    ok = 2;
                    rested = 0;
                    failed = 0;
                    scheduled = 0;
                    reacted = 0;
                    chat = 0;
                    own = 2;
                    unknown = 0;
