let test_pr54465_p2_fixes () =
  let m0 = Model.initial ~cols:140 ~rows:40 ~lang:Say.Lang_en () in
  let t0 = Clock.Mono.of_ns 1_000_000_000L in
  let t1 = Clock.Mono.of_ns 2_000_000_000L in
  let has_cmd pred cmds = List.exists pred (Cmd.flatten cmds) in

  (* P2-1: Browser tabs keyed per client_id — client A failure never leaks to client B *)
  let mk_client cid : Wire_runtime.browser_client_row =
    {
      client_id = cid;
      browser = "Ego Browser";
      version = "131.0";
      engine_version = "131.0";
      transport = "ego";
      space = Some { space_id = 1; space_name = cid };
      ownership = Some "agent";
      presence_state = Some "present";
      presence_reason = None;
      interactions = [];
      last_activities = [];
    }
  in
  let bl : Wire_runtime.browser_lane_status =
    {
      ok = true;
      available = true;
      inventory_complete = true;
      client_count = 2;
      issue_count = 0;
      automatic_browse_ok = true;
      detail = None;
      clients = [ mk_client "ego-a"; mk_client "ego-b" ];
      issues = [];
    }
  in
  let m_bl =
    {
      m0 with
      nav = { m0.nav with workspace = Nav.Runtime; pane_index = 1 };
      runtime =
        Runtime_store.empty
        |> Runtime_store.set_tab Nav.Runtime_addons_browser
        |> Runtime_store.apply_browser_lane ~observed_at:t0 bl;
    }
  in
  let m_bl_err, _ =
    Update.step ~now:t1 m_bl
      (Msg.Http_reply
         {
           epoch = m_bl.epoch;
           reply =
             Msg.Reply_browser_tabs
               {
                 client_id = "ego-a";
                 result =
                   Error
                     (Msg.Http_error
                        { status = 500; body = "ego-a boom"; api_error = None });
               };
         })
  in
  (match Runtime_store.browser_tabs_for ~client_id:"ego-a" m_bl_err.runtime with
  | Observed.Failed _ -> ()
  | _ -> Alcotest.fail "P2-1: expected ego-a browser_tabs slot to be Failed");
  (match Runtime_store.browser_tabs_for ~client_id:"ego-b" m_bl_err.runtime with
  | Observed.Absent -> ()
  | _ -> Alcotest.fail "P2-1: expected ego-b browser_tabs slot to stay Absent");

  (* P2-2: Artifact_dive unmatched target must NOT fall back to selected_artifact *)
  let art_a : Wire_knowledge.artifact_entry =
    {
      id = "art-existing";
      revision = 1;
      title = "Existing Artifact";
      summary = "Real";
      author = "alpha";
      created_at_unix = 1795254000.0;
      body = { sha256 = "sha-existing"; bytes = 64; mime = "text/html" };
    }
  in
  let m_missing_dive =
    {
      m0 with
      nav =
        {
          m0.nav with
          workspace = Nav.Knowledge;
          dive_stack =
            [ Nav.Dive_knowledge (Nav.Artifact_dive "art-nonexistent") ];
        };
      knowledge =
        Knowledge_store.empty
        |> Knowledge_store.apply_artifacts ~observed_at:t0 [ art_a ];
    }
  in
  List.iter
    (fun key ->
      let m_after, cmds =
        Update.step ~now:t1 m_missing_dive (Msg.Key_event (char_key key))
      in
      Alcotest.(check int)
        (Printf.sprintf "P2-2: Artifact_dive [%s] emits 0 cmds on unmatched target"
           key)
        0 (List.length (Cmd.flatten cmds));
      Alcotest.(check bool)
        (Printf.sprintf "P2-2: Artifact_dive [%s] shows warning toast" key)
        true (Option.is_some m_after.toast))
    [ "y"; "o"; "e"; "H" ];

  (* P2-3 & P3-1: Artifact detail failure is target-scoped and non-retryable skips refire *)
  let art_b : Wire_knowledge.artifact_entry =
    {
      art_a with
      id = "art-other";
      title = "Other Artifact";
      body = { sha256 = "sha-other"; bytes = 32; mime = "text/markdown" };
    }
  in
  let k_fail =
    Knowledge_store.empty
    |> Knowledge_store.set_tab Nav.Knowledge_artifacts
    |> Knowledge_store.apply_artifacts ~observed_at:t0 [ art_a; art_b ]
    |> Knowledge_store.mark_artifact_detail_failed ~target:"art-existing" ~at:t1
         ~reason:"HTTP 404: not found" ~retryable:false
  in
  Alcotest.(check bool) "P2-3: failure surfaces for matching artifact" true
    (Option.is_some (Knowledge_store.artifact_detail_failure_for_entry art_a k_fail));
  Alcotest.(check bool) "P2-3: failure does not bleed to other artifact" false
    (Option.is_some (Knowledge_store.artifact_detail_failure_for_entry art_b k_fail));
  let m_fail = { m0 with nav = { m0.nav with workspace = Nav.Knowledge }; knowledge = k_fail } in
  let reqs_no_force = View_fetches.fetches_for_current_view ~force:false m_fail in
  Alcotest.(check bool) "P3-1: non-retryable artifact detail failure does not refire"
    false
    (has_cmd
       (function
         | Cmd.Http_get { req = Cmd.Get_artifact_detail { id = "art-existing"; _ }; _ } ->
             true
         | _ -> false)
       reqs_no_force);
  let reqs_force = View_fetches.fetches_for_current_view ~force:true m_fail in
  Alcotest.(check bool) "P3-1: force refresh DOES refire failed artifact detail"
    true
    (has_cmd
       (function
         | Cmd.Http_get { req = Cmd.Get_artifact_detail { id = "art-existing"; _ }; _ } ->
             true
         | _ -> false)
       reqs_force);

  (* P2-4: Reply_lane_addons 5xx marks lane_addons slot as Observed.Failed(retryable=true) *)
  let m_addons_err, _ =
    Update.step ~now:t1 m_bl
      (Msg.Http_reply
         {
           epoch = m_bl.epoch;
           reply =
             Msg.Reply_lane_addons
               (Error
                  (Msg.Http_error
                     { status = 502; body = "bad gateway"; api_error = None }));
         })
  in
  (match m_addons_err.runtime.lane_addons with
  | Observed.Failed { retryable = true; _ } -> ()
  | _ ->
      Alcotest.fail
        "P2-4: expected Reply_lane_addons 502 to mark lane_addons Failed(retryable=true)");
  Alcotest.(check bool) "P2-4: Reply_lane_addons 502 records HTTP incident" true
    (Incidents.count m_addons_err.incidents > Incidents.count m_bl.incidents)

let test_pr54538_reply_artifacts_dive_target_and_p3_guards () =
  let m0 = Model.initial ~cols:140 ~rows:40 ~lang:Say.Lang_en () in
  let t0 = Clock.Mono.of_ns 1_000_000_000L in
  let t1 = Clock.Mono.of_ns 2_000_000_000L in
  let has_cmd pred cmds = List.exists pred (Cmd.flatten cmds) in
  let art_a : Wire_knowledge.artifact_entry =
    {
      id = "art-alpha";
      revision = 1;
      title = "Alpha";
      summary = "First";
      author = "alpha";
      created_at_unix = 1795254000.0;
      body = { sha256 = "sha-alpha"; bytes = 64; mime = "text/html" };
    }
  in
  let art_b : Wire_knowledge.artifact_entry =
    {
      art_a with
      id = "art-beta";
      revision = 3;
      title = "Beta";
      body = { sha256 = "sha-beta"; bytes = 128; mime = "text/markdown" };
    }
  in
  (* P2 #2a: Artifact_dive target != selected_artifact fetches target, not selected_artifact *)
  let m_dive_b =
    {
      m0 with
      nav =
        {
          m0.nav with
          workspace = Nav.Knowledge;
          dive_stack = [ Nav.Dive_knowledge (Nav.Artifact_dive "art-beta") ];
        };
      knowledge = Knowledge_store.empty;
    }
  in
  let _, cmds_dive_b =
    Update.step ~now:t1 m_dive_b
      (Msg.Http_reply
         {
           epoch = m_dive_b.epoch;
           reply = Msg.Reply_artifacts (Ok [ art_a; art_b ]);
         })
  in
  Alcotest.(check bool)
    "P2 #2: Reply_artifacts in Artifact_dive(art-beta) fetches art-beta" true
    (has_cmd
       (function
         | Cmd.Http_get
             { req = Cmd.Get_artifact_detail { id = "art-beta"; revision = Some 3 }; _ } ->
             true
         | _ -> false)
       cmds_dive_b);
  Alcotest.(check bool)
    "P2 #2: Reply_artifacts in Artifact_dive(art-beta) never fetches selected art-alpha"
    false
    (has_cmd
       (function
         | Cmd.Http_get { req = Cmd.Get_artifact_detail { id = "art-alpha"; _ }; _ } ->
             true
         | _ -> false)
       cmds_dive_b);
  (* P2 #2b: Artifact_dive missing target emits 0 cmds (no silent fallback to selected_artifact) *)
  let m_dive_missing =
    {
      m_dive_b with
      nav =
        {
          m_dive_b.nav with
          dive_stack = [ Nav.Dive_knowledge (Nav.Artifact_dive "art-missing") ];
        };
    }
  in
  let _, cmds_dive_missing =
    Update.step ~now:t1 m_dive_missing
      (Msg.Http_reply
         {
           epoch = m_dive_missing.epoch;
           reply = Msg.Reply_artifacts (Ok [ art_a; art_b ]);
         })
  in
  Alcotest.(check int)
    "P2 #2: Reply_artifacts in Artifact_dive(missing) emits 0 cmds" 0
    (List.length (Cmd.flatten cmds_dive_missing));
  (* P3-1: Reply_artifacts does not refire non-retryable failed artifact detail *)
  let m_non_retry =
    {
      m_dive_b with
      knowledge =
        Knowledge_store.empty
        |> Knowledge_store.mark_artifact_detail_failed ~target:"art-beta" ~at:t0
             ~reason:"HTTP 404: not found" ~retryable:false;
    }
  in
  let _, cmds_non_retry =
    Update.step ~now:t1 m_non_retry
      (Msg.Http_reply
         {
           epoch = m_non_retry.epoch;
           reply = Msg.Reply_artifacts (Ok [ art_a; art_b ]);
         })
  in
  Alcotest.(check int)
    "P3-1: Reply_artifacts skips refire on non-retryable detail failure" 0
    (List.length (Cmd.flatten cmds_non_retry));
  (* P3-2: Moving browser client cursor to client with fresh/non-retryable tabs emits 0 cmds *)
  let mk_client cid : Wire_runtime.browser_client_row =
    {
      client_id = cid;
      browser = "Ego";
      version = "131.0";
      engine_version = "131.0";
      transport = "ego";
      space = None;
      ownership = Some "agent";
      presence_state = Some "present";
      presence_reason = None;
      interactions = [];
      last_activities = [];
    }
  in
  let bl : Wire_runtime.browser_lane_status =
    {
      ok = true;
      available = true;
      inventory_complete = true;
      client_count = 2;
      issue_count = 0;
      automatic_browse_ok = true;
      detail = None;
      clients = [ mk_client "ego-1"; mk_client "ego-2" ];
      issues = [];
    }
  in
  let m_bl_fresh =
    {
      m0 with
      nav = { m0.nav with workspace = Nav.Runtime; pane_index = 1 };
      runtime =
        Runtime_store.empty
        |> Runtime_store.set_tab Nav.Runtime_addons_browser
        |> Runtime_store.apply_browser_lane ~observed_at:t0 bl
        |> Runtime_store.mark_browser_tabs_failed ~at:t0 ~client_id:"ego-2"
             ~reason:"HTTP 403" ~retryable:false;
    }
  in
  let _, cmds_move_bl =
    Update.step ~now:t1 m_bl_fresh (Msg.Key_event (char_key "j"))
  in
  Alcotest.(check int)
    "P3-2: cursor move to client with non-retryable tab error emits 0 cmds" 0
    (List.length (Cmd.flatten cmds_move_bl))

let test_unified_navigation_sidebar_focus_ring_and_mouse () =
  let t0 = Clock.Mono.of_ns 1_000_000_000L in
  let m0 = Model.initial ~cols:140 ~rows:40 ~lang:Say.Lang_ko () in
  let step m msg = Update.step ~now:t0 m msg in
  let press_key m k = step m (Msg.Key_event (key k)) in
  let press_shift_tab m =
    step m
      (Msg.Key_event
         { key = Keymap.Input.Tab; mods = { ctrl = false; alt = false; shift = true } })
  in
  let press_char m c = press_key m (Keymap.Input.Char c) in
  (* 1. Wide docks sidebar automatically; Shift+Tab from pane 0 jumps straight left into Menu *)
  Alcotest.(check bool) "Wide auto-docks left sidebar" true
    (Model.sidebar_docked m0);
  Alcotest.(check bool) "Body owns initial focus" true (Model.body_has_focus m0);
  let m_sb, _ = press_shift_tab m0 in
  Alcotest.(check bool) "Shift+Tab from pane 0 enters sidebar" true
    m_sb.nav.sidebar_focused;
  Alcotest.(check bool) "Body yields focus when sidebar focused" false
    (Model.body_has_focus m_sb);
  (* 2. Down in sidebar moves cursor non-destructively (keeps workspace & dive_stack intact) *)
  let m_goals_cur, cmds_cur = press_key m_sb Keymap.Input.Down in
  Alcotest.(check bool)
    "Arrow browsing in sidebar keeps current Pulse workspace until Enter" true
    (Nav.equal_workspace m_goals_cur.nav.workspace Nav.Pulse);
  Alcotest.(check int) "Arrow Down moves sidebar cursor to Work > Goals"
    (Nav.menu_item_index (Nav.Menu_work Nav.Work_pipeline))
    m_goals_cur.nav.sidebar_cursor;
  Alcotest.(check bool) "Focus remains in sidebar during arrow browsing" true
    m_goals_cur.nav.sidebar_focused;
  Alcotest.(check int) "Arrow browsing emits 0 premature view fetches" 0
    (List.length cmds_cur);
  (* 3. Enter in sidebar commits navigation to Work > Goals and hands focus cleanly into Body pane 0 *)
  let m_body, cmds_goals = press_key m_goals_cur Keymap.Input.Enter in
  Alcotest.(check bool) "Enter switches to Work workspace" true
    (Nav.equal_workspace m_body.nav.workspace Nav.Work);
  Alcotest.(check bool) "Enter lands on Goals tab" true
    (Nav.equal_work_tab m_body.work.active_tab Nav.Work_pipeline);
  Alcotest.(check bool) "Enter issues view fetches" true
    (cmds_goals <> []);
  Alcotest.(check bool) "Enter transfers focus to body" false
    m_body.nav.sidebar_focused;
  Alcotest.(check bool) "Body has focus after Enter" true
    (Model.body_has_focus m_body);
  Alcotest.(check int) "Body enters at pane 0" 0 m_body.nav.pane_index;
  (* 4. System overlay item (Settings) does NOT pop modal on arrow hover; opens on Enter *)
  let settings_idx = Nav.menu_item_index Nav.Menu_settings in
  let m_before_sys =
    {
      m_sb with
      nav = { m_sb.nav with sidebar_cursor = settings_idx - 1 };
    }
  in
  let m_hover_sys, _ = press_key m_before_sys Keymap.Input.Down in
  Alcotest.(check int) "Cursor lands on Settings item" settings_idx
    m_hover_sys.nav.sidebar_cursor;
  Alcotest.(check bool) "Hovering Settings does not pop modal" true
    (Option.is_none m_hover_sys.nav.overlay);
  let m_open_sys, _ = press_key m_hover_sys Keymap.Input.Enter in
  Alcotest.(check bool) "Enter on Settings opens Settings overlay" true
    (match m_open_sys.nav.overlay with Some (Nav.Settings _) -> true | _ -> false);
  (* 5. 'b' focuses docked sidebar, 2nd 'b' collapses it; compact opens floating drawer *)
  let m_b1, _ = press_char m0 "b" in
  Alcotest.(check bool) "First 'b' focuses docked sidebar" true
    m_b1.nav.sidebar_focused;
  let m_b2, _ = press_char m_b1 "b" in
  Alcotest.(check bool) "Second 'b' collapses docked sidebar" false
    (Model.sidebar_visible m_b2);
  let m_narrow = Model.initial ~cols:96 ~rows:28 () in
  Alcotest.(check bool) "Narrow hides sidebar by default" false
    (Model.sidebar_visible m_narrow);
  let m_drawer, _ = press_char m_narrow "b" in
  Alcotest.(check bool) "Narrow 'b' opens floating drawer" true
    (Model.sidebar_drawer_open m_drawer && m_drawer.nav.sidebar_focused);
  let m_esc_drawer, _ = press_key m_drawer Keymap.Input.Escape in
  Alcotest.(check bool) "Esc closes compact floating drawer" false
    (Model.sidebar_drawer_open m_esc_drawer || m_esc_drawer.nav.sidebar_focused);
  (* 6. Ctrl+K Palette indexes all 21 screens including Artifacts and Goals *)
  let m_pal =
    {
      m0 with
      nav = { m0.nav with overlay = Some Nav.Palette };
      palette = { mode = Model.Palette_commands; query = "Artifacts"; selected = 0 };
    }
  in
  let pal_entries = Update_nav.palette_entries m_pal in
  Alcotest.(check bool) "Ctrl+K finds first-class Artifacts route" true
    (List.exists
       (fun (e : Update_nav.palette_entry) ->
         match e.action with
         | Update_nav.Pal_menu_target (Nav.Menu_knowledge Nav.Knowledge_artifacts) -> true
         | _ -> false)
       pal_entries);
  (* 7. Mouse click on Sidebar item navigates directly to Artifacts; clicking right pane focuses pane 1 *)
  let sr = Option.get (Model.sidebar_rect m0) in
  let art_idx = Nav.menu_item_index (Nav.Menu_knowledge Nav.Knowledge_artifacts) in
  let art_vis_row = Model.sidebar_cursor_visual_row ~cursor:art_idx in
  let click_x_1based = sr.x + 3 + 1 in
  let click_y_1based = sr.y + 1 + art_vis_row + 1 in
  let m_clicked_art, cmds_art =
    step m0
      (Msg.Mouse_event
         (Keymap.Input.Left_press { col = click_x_1based; row = click_y_1based }))
  in
  Alcotest.(check bool) "Mouse click on Artifacts opens Knowledge > Artifacts" true
    (Nav.equal_workspace m_clicked_art.nav.workspace Nav.Knowledge
     && Nav.equal_knowledge_tab m_clicked_art.knowledge.active_tab
          Nav.Knowledge_artifacts);
  Alcotest.(check bool) "Mouse click hands focus to body" false
    m_clicked_art.nav.sidebar_focused;
  Alcotest.(check bool) "Mouse click triggers view fetches" true (cmds_art <> []);
  let body_r = Model.body_rect m_clicked_art in
  let right_col_1based = body_r.x + (body_r.w * 3 / 4) + 1 in
  let body_row_1based = body_r.y + 4 + 1 in
  let m_clicked_p1, _ =
    step m_clicked_art
      (Msg.Mouse_event
         (Keymap.Input.Left_press
            { col = right_col_1based; row = body_row_1based }))
  in
  Alcotest.(check int) "Clicking right half of 2-pane body focuses pane 1" 1
    m_clicked_p1.nav.pane_index;
  (* Clicking top-left [b] button toggles/focuses sidebar *)
  let m_clicked_b, _ =
    step m_clicked_p1
      (Msg.Mouse_event (Keymap.Input.Left_press { col = 3; row = 1 }))
  in
  Alcotest.(check bool) "Clicking top-left [b] focuses sidebar" true
    m_clicked_b.nav.sidebar_focused;
  (* Review regression 1: resizing narrower while docked sidebar is focused
     clears sidebar_focused and returns focus to body without trapping keys *)
  let m_shrunk, _ = step m_clicked_b (Msg.Resize { cols = 100; rows = 30 }) in
  Alcotest.(check bool) "Shrink <132 hides auto-docked sidebar" false
    (Model.sidebar_visible m_shrunk);
  Alcotest.(check bool) "Shrink <132 clears sidebar_focused" false
    m_shrunk.nav.sidebar_focused;
  Alcotest.(check bool) "Shrink <132 clears sidebar_has_focus" false
    (Model.sidebar_has_focus m_shrunk);
  Alcotest.(check bool) "Shrink <132 restores body_has_focus" true
    (Model.body_has_focus m_shrunk);
  let m_shrunk_next, _ =
    step m_shrunk (Msg.Key_event (char_key "]"))
  in
  Alcotest.(check bool) "After shrink, ']' cycles Knowledge sub-tab normally" true
    (Nav.equal_knowledge_tab m_shrunk_next.knowledge.active_tab
       Nav.Knowledge_memory);
  (* Review regression 2: Mouse Wheel over unfocused docked sidebar focuses it
     and scrolls cleanly onto System overlay items (Settings) without snapping back *)
  let m_infra_logs, _ =
    Update_nav.navigate_menu_target m0 (Nav.Menu_infra Nav.Infra_activity_logs)
  in
  Alcotest.(check bool) "Unfocused docked sidebar on Infra > Logs" false
    (Model.sidebar_has_focus m_infra_logs);
  let sr_logs =
    match Model.sidebar_rect m_infra_logs with
    | Some r -> r
    | None -> Alcotest.fail "expected docked sidebar rect on 140x40"
  in
  let m_wheel_settings, _ =
    step m_infra_logs
      (Msg.Mouse_event
         (Keymap.Input.Wheel
            {
              dir = Keymap.Input.Wheel_down;
              col = sr_logs.x + 3 + 1;
              row = sr_logs.y + 3 + 1;
            }))
  in
  (* UX-27: Wheel over unfocused sidebar only scrolls sidebar_scroll without
     stealing focus, switching workspace, wiping dive_stack, or popping modals. *)
  Alcotest.(check bool) "Wheel over unfocused sidebar keeps focus in body" false
    (Model.sidebar_has_focus m_wheel_settings);
  Alcotest.(check bool) "Wheel over sidebar stays on Infra workspace" true
    (Nav.equal_workspace m_wheel_settings.nav.workspace Nav.Infra);
  Alcotest.(check bool) "Wheel over sidebar does not auto-pop modal" true
    (Option.is_none m_wheel_settings.nav.overlay);
  (* Review regression 3: Compact Auto_folded_pill click above footer does NOT
     falsely focus composer when Model.composer_rect is None *)
  let m_compact = Model.initial ~cols:85 ~rows:26 ~lang:Say.Lang_ko () in
  Alcotest.(check bool) "Compact Pulse idle has no composer_rect" true
    (Option.is_none (Model.composer_rect m_compact));
  let m_compact_click, _ =
    step m_compact
      (Msg.Mouse_event (Keymap.Input.Left_press { col = 10; row = 24 }))
  in
  Alcotest.(check bool) "Click when composer auto-folded leaves composer unfocused"
    false (Drafts.is_focused m_compact_click.drafts)

(* ---------- Cut reply rebuilt from the operation journal ---------- *)

let unowned text =
  Wire_chat_journal.Text_delta
    { text; owner = Wire_chat_journal.Unobserved_scope None }

let owned ~generation ~scope text =
  Wire_chat_journal.Text_delta
    {
      text;
      owner =
        Wire_chat_journal.Observed_response
          { content_generation = generation; stream_scope = scope };
    }

let journal_page ?next events : Wire_chat_journal.page = { events; next }

let rebuilt events =
  Cut_reply.text (Cut_reply.apply_page (journal_page events) Cut_reply.start)

let from_label = function
  | Wire_chat_journal.From_start -> "start"
  | Wire_chat_journal.After { last_seq; next_offset } ->
      Printf.sprintf "after seq %d at %d" last_seq next_offset

let test_cut_reply_follows_the_connector_fold () =
  let open Wire_chat_journal in
  Alcotest.(check (option string))
    "an attempt boundary drops the earlier attempt and its late bytes"
    (Some "second")
    (rebuilt
       [
         Run_started;
         owned ~generation:1 ~scope:0 "first";
         Runtime_attempt_started;
         owned ~generation:1 ~scope:0 "late";
         owned ~generation:2 ~scope:0 "second";
         Event_error;
       ]);
  Alcotest.(check (option string)) "a new run starts the text over" (Some "b")
    (rebuilt [ Run_started; unowned "a"; Run_started; Other; unowned "b" ]);
  Alcotest.(check (option string))
    "an older response of the admitted generation is dropped" (Some "AC")
    (rebuilt
       [
         owned ~generation:1 ~scope:4 "A";
         owned ~generation:1 ~scope:3 "B";
         owned ~generation:1 ~scope:5 "C";
       ]);
  Alcotest.(check (option string))
    "a bare scope ahead of the admitted response drops older scopes"
    (Some "AUC")
    (rebuilt
       [
         owned ~generation:1 ~scope:4 "A";
         Text_delta { text = "U"; owner = Unobserved_scope (Some 6) };
         owned ~generation:1 ~scope:5 "B";
         owned ~generation:1 ~scope:6 "C";
       ]);
  Alcotest.(check (option string)) "the first terminal event ends the reply"
    (Some "kept")
    (rebuilt [ unowned "kept"; Run_finished; unowned "after" ]);
  Alcotest.(check (option string)) "a cut with no text draws nothing" None
    (rebuilt [ Run_started; Event_error ]);
  let cursor = { last_seq = 2; next_offset = 300 } in
  let first =
    Cut_reply.apply_page
      (journal_page ~next:cursor [ unowned "Hel" ])
      Cut_reply.start
  in
  Alcotest.(check (option string)) "a page with more asks for the next one"
    (Some "after seq 2 at 300")
    (Option.map from_label (Cut_reply.next_page first));
  Alcotest.(check (option string)) "nothing is drawn before the last page" None
    (Cut_reply.text first);
  let last = Cut_reply.apply_page (journal_page [ unowned "lo" ]) first in
  Alcotest.(check (option string)) "the pages join into one reply"
    (Some "Hello") (Cut_reply.text last);
  Alcotest.(check (option string)) "the last page ends reading" None
    (Option.map from_label (Cut_reply.next_page last));
  let ended =
    Cut_reply.apply_page
      (journal_page ~next:cursor [ unowned "x"; Event_error; unowned "y" ])
      Cut_reply.start
  in
  Alcotest.(check (option string))
    "a terminal event ends reading though the server has more" None
    (Option.map from_label (Cut_reply.next_page ended));
  Alcotest.(check (option string)) "a page after the end changes nothing"
    (Some "x")
    (Cut_reply.text (Cut_reply.apply_page (journal_page [ unowned "z" ]) ended));
  Alcotest.(check (option string)) "no journal asks nothing" None
    (Option.map from_label (Cut_reply.next_page Cut_reply.no_journal));
  Alcotest.(check (option string)) "no journal draws nothing" None
    (Cut_reply.text Cut_reply.no_journal)

let chat_row ~id ~role ?provenance content : Wire_fleet.chat_message =
  {
    id;
    role;
    content;
    ts_unix = 1_700_000_000.0;
    turn_ref = None;
    model_used = None;
    tool_call_id = None;
    tool_call_name = None;
    execution_id = None;
    provenance;
    failure_kind = None;
    thinking = None;
    retained_images = [];
  }

let failure_row ~id ~operation_id =
  chat_row ~id ~role:Wire_fleet.Role_request_failure
    ?provenance:(operation_provenance operation_id Settled_failure)
    "Keeper request failed: cancelled"

let journal_gets cmds =
  List.filter_map
    (function
      | Cmd.Http_get
          { req = Cmd.Get_chat_operation_events { operation_id; from; _ }; _ }
        ->
          Some (operation_id, from_label from)
      | _ -> None)
    (Cmd.flatten cmds)

let history_reply ~keeper messages (m : Model.t) =
  Update.step ~now:t1 m
    (Msg.Http_reply
       {
         epoch = m.epoch;
         reply =
           Msg.Reply_chat_history
             {
               keeper;
               result = Ok { messages; has_more = false; next_cursor = None };
             };
       })

let journal_reply ~operation_id ~from result (m : Model.t) =
  Update.step ~now:t2 m
    (Msg.Http_reply
       {
         epoch = m.epoch;
         reply =
           Msg.Reply_chat_operation_events
             { keeper = "alpha"; operation_id; from; result };
       })

let in_alpha_chat (m : Model.t) =
  {
    m with
    nav =
      {
        m.nav with
        dive_stack = [ Nav.Dive_keeper { name = "alpha"; tab = Nav.Keeper_chat } ];
      };
  }

let test_reopen_keeper_queue_and_reconcile () =
  let model = in_alpha_chat (Model.initial ()) in
  let drafts = Drafts.set_active_keeper "alpha" model.drafts in
  let model, cmds = Update.execute_action ~now:t0 { model with drafts } Keymap.Open_queue_context in
  Alcotest.(check bool) "fresh drawer asks for the selected keeper's server queue" true
    (List.exists (function
      | Cmd.Http_get { req = Cmd.Get_chat_queue { keeper = "alpha" }; _ } -> true
      | _ -> false) (Cmd.flatten cmds));
  let op : Wire_fleet.chat_operation = {
    id = Result.get_ok (Keeper_chat_operation.Operation_id.of_string "queued-from-another-session");
    state = Keeper_chat_operation.State_name.Queued;
    sequence = 11L; message = Some "prior input"; failure_detail = None;
    batch_execution_id = None } in
  let receive model ~keeper ~requested_at operations result =
    Update.step ~now:t2 model (Msg.Http_reply { epoch = model.Model.epoch;
       reply = Msg.Reply_chat_queue { keeper; requested_at; operations; running_batch = None; result } }) |> fst in
  let progress = receive model ~keeper:"alpha" ~requested_at:t1 [op] None in
  Alcotest.(check bool) "a partial receipt keeps its active read"
    false (List.exists (function Cmd.Http_get { req = Cmd.Get_chat_queue _; _ } -> true | _ -> false)
             (View_fetches.overlay_fetches progress));
  let loaded = receive progress ~keeper:"alpha" ~requested_at:t1 [op] (Some (Ok ())) in
  let _, reopened = Update_nav.open_overlay loaded (Nav.Queue_context Nav.Drawer_queue) in
  Alcotest.(check bool) "reopening asks again even after a complete read"
    true (List.exists (function Cmd.Http_get { req = Cmd.Get_chat_queue { keeper = "alpha" }; _ } -> true | _ -> false)
            (Cmd.flatten reopened));
  let loaded = receive loaded ~keeper:"alpha" ~requested_at:t0 [] (Some (Ok ())) in
  let loaded = receive loaded ~keeper:"beta" ~requested_at:t2 [] (Some (Ok ())) in
  let queue, local = Model.drawer_queue ~keeper:"alpha" loaded in
  Alcotest.(check (option (list string))) "older or foreign replies leave the queued operation visible"
    (Some ["queued-from-another-session"]) (Option.map (fun () -> List.map (fun (row : Wire_fleet.chat_operation) -> Keeper_chat_operation.Operation_id.to_string row.id) queue.operations) (Observed.to_option queue.read));
  Alcotest.(check int) "server-only row has no local claim" 0 (List.length local);
  let queue_after operations result =
    let model = receive loaded ~keeper:"alpha" ~requested_at:t2 operations (Some result) in
    Fleet_store.chat_queue_for ~keeper:"alpha" model.fleet in
  let reset = queue_after [] (Ok ()) in
  Alcotest.(check bool) "an authoritative empty first page clears the previous inventory" true
    (Observed.to_option reset.read = Some () && reset.operations = []);
  List.iter (fun error ->
    let retained = queue_after [] (Error error) in
    Alcotest.(check bool) "a failed first page shows its error and the last observed operations" true
      (match retained.read with Observed.Failed _ -> retained.operations = [op] | _ -> false))
    [Msg.Transport (Health.Other_io "connection reset");
     Msg.Http_error { status = 503; body = ""; api_error = None };
     Msg.Decode_error "invalid first page"];
  let next_page = { op with id = Result.get_ok (Keeper_chat_operation.Operation_id.of_string "new-queue-id") } in
  let partial_failure = queue_after [next_page] (Error (Msg.Transport (Health.Other_io "second page"))) in
  Alcotest.(check bool) "a new partial page supersedes the earlier read" true
    (partial_failure.operations = [next_page]);
  let denied = receive loaded ~keeper:"alpha" ~requested_at:t2 [op]
      (Some (Error (Msg.Http_error { status = 403; body = ""; api_error = None }))) in
  Alcotest.(check bool) "unreadable queue keeps an explicit failure" true
    (match (Fleet_store.chat_queue_for ~keeper:"alpha" denied.fleet).read with
     | Observed.Failed { retryable = false; _ } -> true | _ -> false);
  Alcotest.(check int) "denial withdraws the earlier page" 0
    (List.length (Fleet_store.chat_queue_for ~keeper:"alpha" denied.fleet).operations);
  let partial = receive loaded ~keeper:"alpha" ~requested_at:t2 [op]
      (Some (Error (Msg.Transport Health.Timeout))) in
  Alcotest.(check int) "a later transport failure keeps the earlier page" 1
    (List.length (Fleet_store.chat_queue_for ~keeper:"alpha" partial.fleet).operations);
  let typed = Drafts.set_current_text "same input" drafts in
  let pending, tx = Option.get (Drafts.enqueue_submission ~now:t0 ~keeper:"alpha"
      ~mode:Drafts.Mode_follow_up typed) in
  let detached = { loaded with drafts = pending } in
  let exact state (model : Model.t) =
    let operation = { op with id = Result.get_ok (Keeper_chat_operation.Operation_id.of_string tx.request_id); state } in
    Update.step ~now:t2 model (Msg.Http_reply { epoch = model.epoch;
      reply = Msg.Reply_chat_status { keeper = "alpha"; operation_id = tx.request_id; requested_at = t2; result = Ok operation } }) |> fst in
  let tx_state model =
    match List.find_opt (fun (row : Drafts.pending_message) -> String.equal row.request_id tx.request_id)
            (Drafts.pending_txs_for_keeper ~keeper:"alpha" model.Model.drafts) with
    | Some row -> row.state | None -> Alcotest.fail "missing transmission" in
  let queued = exact Queued detached in
  Alcotest.(check bool) "an exact queued status accepts detached sending" true (tx_state queued = Drafts.Queued);
  let running = exact Running queued in
  Alcotest.(check bool) "the detached queue starts on the exact running read" true
    (tx_state running = Drafts.Pending_processing &&
     Chat_transcript.equal_live_chat_phase (Chat_transcript.live_chat_phase ~model:running ~keeper:"alpha")
       Chat_transcript.Phase_awaiting_turn);
  Alcotest.(check bool) "running can also be the first observed status of a send" true
    (tx_state (exact Running detached) = Drafts.Pending_processing);
  Alcotest.(check bool) "a delayed queue read cannot rewind processing" true
    (tx_state (exact Queued running) = Drafts.Pending_processing);
  let interrupting =
    { running with drafts = Drafts.set_operation_interrupting ~now:t1 ~keeper:"alpha"
        ~operation_id:tx.request_id ~interrupting:true running.drafts }
  in
  Alcotest.(check bool) "a running or queued read preserves a pending interrupt" true
    (tx_state (exact Queued (exact Running interrupting)) = Drafts.Interrupting);
  let settled = exact Succeeded running in
  Alcotest.(check bool) "nonterminal reads leave the confirmed terminal state intact" true
    (tx_state (exact Queued (exact Running settled)) = Drafts.Delivered);
  let pending = Drafts.mark_confirming ~now:t1 ~request_id:tx.request_id pending in
  let source = Result.get_ok (Keeper_chat_delivery_identity.Request_id.of_string "another-message") in
  let peer = chat_row ~id:"different-row" ~role:Wire_fleet.Role_user
      ~provenance:{ delivery_key = Workspace_message source; transcript_slot = Accepted_user } tx.body in
  let pending, _ = history_reply ~keeper:"alpha" [peer] { loaded with drafts = pending } in
  let local_visible model =
    Chat_transcript.project_transcript ~model ~keeper:"alpha"
    |> List.exists (function
      | Chat_transcript.Section_pending rows ->
          List.exists (fun (row : Chat_transcript.pending_tx_projection) ->
              String.equal tx.request_id row.tx.request_id) rows
      | _ -> false)
  in
  Alcotest.(check bool) "foreign same-body row keeps the session input visible" true
    (local_visible pending);
  let accepted = chat_row ~id:"accepted-row" ~role:Wire_fleet.Role_user
      ?provenance:(operation_provenance tx.request_id Accepted_user) tx.body in
  let model, _ = history_reply ~keeper:"alpha" [accepted] pending in
  let current = Option.get (Drafts.active_tx_for_keeper ~keeper:"alpha" model.drafts) in
  Alcotest.(check bool) "exact visible accepted row substitutes the local row" false (local_visible model);
  Alcotest.(check bool) "accepted input alone keeps the operation open" true
    (current.state = Drafts.Confirming_delivery);
  let model, _ = history_reply ~keeper:"alpha" [] model in
  Alcotest.(check bool) "pending input returns when its receipt leaves the page" true (local_visible model)

let test_exact_operation_absence_recovery () =
  let keeper = "alpha" in
  let initial = in_alpha_chat (Model.initial ()) in
  let send (m : Model.t) now =
    let drafts = Drafts.insert_text "one original input" (Drafts.set_active_keeper keeper m.drafts) in
    let sent, cmds = Update.execute_action ~now { m with drafts } Keymap.Submit_followup in
    match List.filter_map (function
        | Cmd.Http_post_stream { req = Cmd.Stream_keeper_chat { request; is_btw = false }; _ } ->
            Some request.request_id
        | _ -> None) (Cmd.flatten cmds) with
    | [id] -> sent, id
    | _ -> Alcotest.fail "expected one explicit chat POST" in
  let sent, id = send initial t0 in
  let row (m : Model.t) = List.find (fun (tx : Drafts.pending_message) -> String.equal tx.request_id id)
      (Drafts.pending_txs_for_keeper ~keeper m.drafts) in
  let read ?(request_keeper = keeper) ?(request_id = id) ~started ~now result (m : Model.t) =
    let reply = Msg.chat_status_reply ~keeper:request_keeper ~operation_id:request_id ~requested_at:started result in
    Update.step ~now m (Msg.Http_reply { epoch = m.epoch; reply }) |> fst in
  let disconnect ~now (m : Model.t) =
    Update.step ~now m (Msg.Chat_stream_done { epoch = m.epoch; keeper; request_id = id; is_btw = false;
                                             result = Error (Msg.Transport (Health.Other_io "connection closed")) }) in
  let detached, cmds = disconnect ~now:t1 sent in
  Alcotest.(check bool) "a disconnect asks about the original POST id" true
    (List.exists (function Cmd.Http_get { req = Cmd.Get_chat_status { operation_id; _ }; _ } ->
                       String.equal operation_id id | _ -> false) (Cmd.flatten cmds));
  let op_id = Result.get_ok (Keeper_chat_operation.Operation_id.of_string id) in
  let scope = { Keeper_chat_operation_read.keeper_name = keeper; operation_id = op_id } in
  let envelope ?absence () = Keeper_chat_operation_read.public_error_json ?absence
      ~code:Keeper_chat_operation_read.unknown_operation_code ~message:"The operation was not found."
      ~incident_id:"server-incident" () |> Yojson.Safe.to_string in
  let http status body = Error (Msg.Http_error { status; body; api_error = None }) in
  let absent = http 404 (envelope ~absence:scope ()) in
  let later = Clock.Mono.after_s t2 1. in
  List.iter (fun response ->
      let model = read ~started:t1 ~now:t2 response detached in
      Alcotest.(check bool) "unsupported or unreadable responses preserve unconfirmed delivery" true
        ((row model).state = Drafts.Confirming_delivery))
    [http 404 (envelope ()); http 404 "{}"; http 404 "invalid JSON";
     http 404 (envelope ~absence:{scope with keeper_name = "beta"} ());
     http 404 (envelope ~absence:{scope with operation_id = Result.get_ok
                    (Keeper_chat_operation.Operation_id.of_string "another-request")} ());
     http 410 (envelope ~absence:scope ()); http 403 (envelope ~absence:scope ());
     http 503 (envelope ~absence:scope ())];
  let missing = read ~started:t1 ~now:t2 absent detached in
  Alcotest.(check bool) "exact readable absence preserves input and identity without a terminal verdict" true
    (let tx = row missing in tx.state = Drafts.No_operation_record && tx.operation_id = None &&
        tx.body = "one original input" && not (Drafts.has_active_tx_for ~keeper missing.drafts));
  Alcotest.(check bool) "the missing operation leaves automatic status polling" true
    (View_fetches.chat_status_fetches ~keeper missing = []);
  let after_disconnect, cmds = disconnect ~now:later missing in
  Alcotest.(check bool) "a delayed disconnect cannot restart polling the missing operation" true
    ((row after_disconnect).state = Drafts.No_operation_record &&
     not (List.exists (function Cmd.Http_get { req = Cmd.Get_chat_status _; _ } -> true | _ -> false) (Cmd.flatten cmds)));
  let dismissed, _ = Update.execute_action ~now:later missing Keymap.Dismiss_errors in
  Alcotest.(check int) "the original unresolved input can be dismissed with X" 0
    (List.length (Drafts.pending_txs_for_keeper ~keeper dismissed.drafts));
  let _, second_id = send missing later in
  Alcotest.(check bool) "a deliberate second POST gets a fresh request id" false (String.equal second_id id);
  let exact ?batch_execution_id state =
    Ok Wire_fleet.{ id = op_id; sequence = 1L; state; message = None; failure_detail = None; batch_execution_id }
  in
  let execution_id = Result.get_ok (Keeper_chat_operation.Operation_id.of_string "batch-lead") in
  let batched = read ~started:t1 ~now:t2 (exact ~batch_execution_id:execution_id Running) detached in
  Alcotest.(check bool) "exact status retains the batch binding of the submitted operation"
    true (Option.equal Keeper_chat_operation.Operation_id.equal
      (Some execution_id) (row batched).batch_execution_id);
  let accepted = read ~started:t1 ~now:t2 (exact Running) detached in
  let late_absence = read ~started:t1 ~now:later absent accepted in
  Alcotest.(check bool) "an absence lookup started before a later acceptance cannot erase it" true
    ((row late_absence).state = Drafts.Pending_processing);
  let formerly_accepted = read ~started:later ~now:later absent accepted in
  Alcotest.(check bool) "absent now, previously accepted remains distinguishable" true
    ((row formerly_accepted).state = Drafts.No_operation_record && (row formerly_accepted).operation_id = Some id);
  let replay = chat_row ~id:"operator-accepted" ~role:Wire_fleet.Role_user
      ?provenance:(operation_provenance id Accepted_user) "one original input" in
  let old_ack, _ = history_reply ~keeper [replay] formerly_accepted in
  Alcotest.(check bool) "replaying the known accepted row leaves the absence notice in view" true
    ((row old_ack).state = Drafts.No_operation_record &&
     List.exists (function Chat_transcript.Section_pending rows ->
       List.exists (fun (p : Chat_transcript.pending_tx_projection) -> p.notice_only) rows | _ -> false)
       (Chat_transcript.project_transcript ~model:old_ack ~keeper));
  let first_ack, _ = history_reply ~keeper [replay] missing in
  Alcotest.(check bool) "new exact accepted input recovers the previously unknown submission" true
    ((row first_ack).state = Drafts.Pending_processing && (row first_ack).operation_id = Some id);
  let stale_positive = read ~started:t1 ~now:later (exact Queued) missing in
  Alcotest.(check bool) "a stale queue observation cannot reopen a later absence" true
    ((row stale_positive).state = Drafts.No_operation_record);
  let queue (m : Model.t) at =
    let op = Result.get_ok (exact Queued) in
    Update.step ~now:later m (Msg.Http_reply { epoch = m.epoch; reply = Msg.Reply_chat_queue {
        keeper; requested_at = at; operations = [op]; running_batch = None; result = Some (Ok ()) } }) |> fst in
  Alcotest.(check bool) "stale drawer evidence cannot reopen a later absence" true
    ((row (queue missing t1)).state = Drafts.No_operation_record);
  Alcotest.(check bool) "a newly read scoped queue can recover the exact id" true
    ((row (queue missing later)).state = Drafts.Queued);
  let failed = read ~started:later ~now:later (exact Failed) missing in
  Alcotest.(check bool) "only the later failed operation observation establishes failure" true
    (match (row failed).state with Drafts.Failed_retryable _ -> true | _ -> false);
  let started = read ~started:later ~now:later (exact Running) missing in
  Alcotest.(check bool) "subsequent exact running receipt recovers the local submission" true
    ((row started).state = Drafts.Pending_processing);
  let settled = read ~started:later ~now:later (exact Succeeded) formerly_accepted in
  Alcotest.(check bool) "a later exact terminal status settles a previously absent record" true
    ((row settled).state = Drafts.Delivered);
  let after_terminal = read ~started:later ~now:later absent settled in
  Alcotest.(check bool) "absence cannot replace an established terminal result" true
    ((row after_terminal).state = Drafts.Delivered)

let test_cut_reply_reads_the_operation_journal () =
  let m0 = in_alpha_chat (Model.initial ()) in
  let history =
    [
      chat_row ~id:"u-cut" ~role:Wire_fleet.Role_user ?provenance:(operation_provenance "op-cut" Accepted_user)
        "question";
      failure_row ~id:"f-cut" ~operation_id:"op-cut";
      (* The same operation's settled failure: the reply is drawn once. *)
      failure_row ~id:"f-cut-settled" ~operation_id:"op-cut";
      chat_row ~id:"a-done" ~role:Wire_fleet.Role_assistant
        ?provenance:(operation_provenance "op-done" Terminal_result) "delivered reply";
      (* A failure settled after a delivered reply is not a cut. *)
      failure_row ~id:"f-done" ~operation_id:"op-done";
    ]
  in
  let m1, cmds1 = history_reply ~keeper:"alpha" history m0 in
  Alcotest.(check (list (pair string string)))
    "the history reply asks the cut operation's journal from its start"
    [ ("op-cut", "start") ] (journal_gets cmds1);
  Alcotest.(check (list (pair string string)))
    "only the first failure row of the cut operation stands for it"
    [ ("f-cut", "op-cut") ]
    (Fleet_store.cut_reply_rows ~keeper:"alpha" m1.fleet);
  Alcotest.(check string) "the request names the operation and the page size"
    "/api/v1/keepers/alpha/chat/events?operation_id=op-cut&limit=2000"
    (Cmd.get_request_path
       (Cmd.Get_chat_operation_events
          {
            keeper = "alpha";
            operation_id = "op-cut";
            from = Wire_chat_journal.From_start;
          }));
  Alcotest.(check (list (pair string string)))
    "the planner asks the same page while no answer is held"
    [ ("op-cut", "start") ]
    (journal_gets (View_fetches.fetches_for_current_view m1));
  let cursor : Wire_chat_journal.cursor = { last_seq = 1; next_offset = 240 } in
  let m2, cmds2 =
    journal_reply ~operation_id:"op-cut" ~from:Wire_chat_journal.From_start
      (Ok (journal_page ~next:cursor [ unowned "cut " ]))
      m1
  in
  Alcotest.(check (list (pair string string)))
    "a page with more asks for the next page"
    [ ("op-cut", "after seq 1 at 240") ] (journal_gets cmds2);
  Alcotest.(check string) "the next page sends both cursors back"
    "/api/v1/keepers/alpha/chat/events?operation_id=op-cut&since_seq=1&since_offset=240&limit=2000"
    (Cmd.get_request_path
       (Cmd.Get_chat_operation_events
          {
            keeper = "alpha";
            operation_id = "op-cut";
            from = Wire_chat_journal.After cursor;
          }));
  Alcotest.(check (list (pair string string)))
    "nothing is drawn before the last page" []
    (Fleet_store.String_map.bindings
       (Fleet_store.cut_replies_by_row ~keeper:"alpha" m2.fleet));
  let m2_dup, cmds2_dup =
    journal_reply ~operation_id:"op-cut" ~from:Wire_chat_journal.From_start
      (Ok (journal_page ~next:cursor [ unowned "cut " ]))
      m2
  in
  Alcotest.(check (list (pair string string)))
    "a second answer to the first page asks nothing" []
    (journal_gets cmds2_dup);
  let m3, cmds3 =
    journal_reply ~operation_id:"op-cut" ~from:(Wire_chat_journal.After cursor)
      (Ok (journal_page [ unowned "reply"; Wire_chat_journal.Event_error ]))
      m2_dup
  in
  Alcotest.(check (list (pair string string)))
    "the reply is drawn once, under the first failure row"
    [ ("f-cut", "cut reply") ]
    (Fleet_store.String_map.bindings
       (Fleet_store.cut_replies_by_row ~keeper:"alpha" m3.fleet));
  Alcotest.(check (list (pair string string))) "the last page asks nothing more"
    [] (journal_gets cmds3);
  Alcotest.(check (list (pair string string)))
    "a rebuilt reply is not asked again" []
    (journal_gets (View_fetches.fetches_for_current_view m3));
  Alcotest.(check bool) "the answer lands on its own keeper's key" true
    (match Fleet_store.cut_reply_for ~keeper:"beta" ~operation_id:"op-cut" m3.fleet with
    | Observed.Unreported -> true
    | Observed.Value _ | Observed.Loading _ | Observed.Absent | Observed.Failed _ ->
        false);
  (* Not on screen: the Memory tab does not read journals. *)
  let on_memory =
    {
      m0 with
      nav =
        {
          m0.nav with
          dive_stack =
            [ Nav.Dive_keeper { name = "alpha"; tab = Nav.Keeper_memory } ];
        };
    }
  in
  let _, memory_cmds = history_reply ~keeper:"alpha" history on_memory in
  Alcotest.(check (list (pair string string)))
    "a history reply under another tab reads no journal" []
    (journal_gets memory_cmds);
  (* The Keepers split shows the selected keeper's Chat pane. *)
  let base = Model.initial () in
  let with_roster, _ =
    Update.step ~now:t1 base
      (Msg.Http_reply
         {
           epoch = base.epoch;
           reply =
             Msg.Reply_keepers_roster (Ok (roster_of [ sample_keeper "alpha" ]));
         })
  in
  let split =
    {
      with_roster with
      nav = { with_roster.nav with workspace = Nav.Keepers; dive_stack = [] };
      fleet = { with_roster.fleet with keeper_dive_tab = Nav.Keeper_chat };
    }
  in
  let _, split_cmds = history_reply ~keeper:"alpha" history split in
  Alcotest.(check (list (pair string string)))
    "the Keepers split's Chat pane reads the journal too"
    [ ("op-cut", "start") ] (journal_gets split_cmds)

let test_cut_reply_journal_failures () =
  let history =
    [
      failure_row ~id:"f-gone" ~operation_id:"op-gone";
      failure_row ~id:"f-broken" ~operation_id:"op-broken";
    ]
  in
  let m1, _ = history_reply ~keeper:"alpha" history (in_alpha_chat (Model.initial ())) in
  let incidents_before = Incidents.count m1.incidents in
  let gone, _ =
    journal_reply ~operation_id:"op-gone" ~from:Wire_chat_journal.From_start
      (Error (Msg.Http_error { status = 410; body = ""; api_error = None }))
      m1
  in
  Alcotest.(check int) "a pruned journal is not an incident" incidents_before
    (Incidents.count gone.incidents);
  Alcotest.(check (list (pair string string)))
    "a pruned journal is not asked again, only the broken one is"
    [ ("op-broken", "start") ]
    (journal_gets (View_fetches.fetches_for_current_view gone));
  let broken, _ =
    journal_reply ~operation_id:"op-broken" ~from:Wire_chat_journal.From_start
      (Error (Msg.Http_error { status = 503; body = "journal unreadable"; api_error = None }))
      gone
  in
  Alcotest.(check int) "a failed read records an incident"
    (incidents_before + 1)
    (Incidents.count broken.incidents);
  Alcotest.(check bool) "the failure lands on the operation's slot" true
    (match
       Fleet_store.cut_reply_for ~keeper:"alpha" ~operation_id:"op-broken"
         broken.fleet
     with
    | Observed.Failed { retryable = true; _ } -> true
    | Observed.Failed { retryable = false; _ }
    | Observed.Value _ | Observed.Loading _ | Observed.Absent | Observed.Unreported ->
        false);
  Alcotest.(check (list (pair string string)))
    "a retryable failure is asked again from the start"
    [ ("op-broken", "start") ]
    (journal_gets (View_fetches.fetches_for_current_view broken));
  Alcotest.(check (list (pair string string))) "neither draws anything" []
    (Fleet_store.String_map.bindings
       (Fleet_store.cut_replies_by_row ~keeper:"alpha" broken.fleet))

(* The first page of a long journal landed and a later page fails. The partial
   read draws nothing, so the failure replaces it. A stale partial read would
   be asked for the same page again at every trigger. *)
let test_cut_reply_failure_after_the_first_page () =
  let history = [ failure_row ~id:"f-long" ~operation_id:"op-long" ] in
  let m0, _ =
    history_reply ~keeper:"alpha" history (in_alpha_chat (Model.initial ()))
  in
  let cursor : Wire_chat_journal.cursor = { last_seq = 1; next_offset = 240 } in
  let page2 = Wire_chat_journal.After cursor in
  let after_first, _ =
    journal_reply ~operation_id:"op-long" ~from:Wire_chat_journal.From_start
      (Ok (journal_page ~next:cursor [ unowned "cut " ]))
      m0
  in
  let slot_failure (m : Model.t) =
    match
      Fleet_store.cut_reply_for ~keeper:"alpha" ~operation_id:"op-long" m.fleet
    with
    | Observed.Failed { retryable; _ } -> Some retryable
    | Observed.Value _ | Observed.Loading _ | Observed.Absent
    | Observed.Unreported ->
        None
  in
  let not_found =
    Error (Msg.Http_error { status = 404; body = "no such page"; api_error = None })
  in
  let incidents_before = Incidents.count after_first.incidents in
  let gone, gone_cmds =
    journal_reply ~operation_id:"op-long" ~from:page2 not_found after_first
  in
  Alcotest.(check (option bool))
    "a non-retryable failure replaces the partial read" (Some false)
    (slot_failure gone);
  Alcotest.(check int) "the failure records one incident"
    (incidents_before + 1)
    (Incidents.count gone.incidents);
  Alcotest.(check (list (pair string string))) "the failed reply asks nothing"
    [] (journal_gets gone_cmds);
  Alcotest.(check (list (pair string string)))
    "the planner does not ask the failed page again" []
    (journal_gets (View_fetches.fetches_for_current_view gone));
  Alcotest.(check (list (pair string string)))
    "a chat history landing does not ask it again" []
    (journal_gets (snd (history_reply ~keeper:"alpha" history gone)));
  let duplicate, duplicate_cmds =
    journal_reply ~operation_id:"op-long" ~from:page2 not_found gone
  in
  Alcotest.(check int) "a second failure of the same page records nothing"
    (Incidents.count gone.incidents)
    (Incidents.count duplicate.incidents);
  Alcotest.(check (list (pair string string)))
    "a second failure of the same page asks nothing" []
    (journal_gets duplicate_cmds);
  let down, _ =
    journal_reply ~operation_id:"op-long" ~from:page2
      (Error
         (Msg.Http_error
            { status = 503; body = "journal unreadable"; api_error = None }))
      after_first
  in
  Alcotest.(check (option bool)) "a retryable failure replaces the partial read"
    (Some true) (slot_failure down);
  Alcotest.(check (list (pair string string)))
    "a retryable failure asks again from the start"
    [ ("op-long", "start") ]
    (journal_gets (View_fetches.fetches_for_current_view down))

let test_live_chat_runtime_attempt_and_text_ownership () =
  let keeper = "alpha" in
  let req = "req-retry-1" in
  let obs gen scope =
    Wire_chat_journal.Observed_response
      { content_generation = gen; stream_scope = scope }
  in
  let delta ~owner text =
    Wire_fleet.Chunk_text_delta { operation_id = Some req; delta = text; owner }
  in
  let f0 =
    Fleet_store.empty
    |> Fleet_store.start_chat_stream ~keeper ~request_id:req
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (Wire_fleet.Chunk_run_started { operation_id = Some req })
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (Wire_fleet.Chunk_thinking_delta
            { operation_id = Some req; delta = "attempt 1 thought"; owner = None })
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (Wire_fleet.Chunk_tool_start
            {
              operation_id = Some req;
              tool_use_id = "tu-1";
              stream_scope = None;
              tool_name = "read_file";
              args_preview = Some "a.ml";
            })
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (Wire_fleet.Chunk_tool_end
            {
              operation_id = Some req;
              tool_use_id = "tu-1";
              tool_name = Some "read_file";
              ok = Some true;
              output_preview = Some "ok";
            })
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (delta ~owner:(obs 1 0) "Attempt 1 partial ")
  in
  let f1 =
    Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
      (Wire_fleet.Chunk_runtime_attempt_started
         { operation_id = Some req; runtime_id = Some "rt-2"; attempt_index = Some 2 })
      f0
  in
  let buf1 = Fleet_store.String_map.find keeper f1.chat_streams in
  Alcotest.(check string) "attempt boundary discards unfinished text" "" buf1.text;
  Alcotest.(check string) "attempt boundary discards unfinished thinking" ""
    buf1.thinking;
  Alcotest.(check int) "attempt boundary preserves completed tools" 1
    (List.length buf1.tools);
  (* Late delta from retired attempt 1 is dropped; attempt 2 text is accepted. *)
  let f2 =
    f1
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (delta ~owner:(obs 1 0) "STALE_LATE_TEXT")
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (delta ~owner:(obs 2 0) "Attempt 2 ")
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (delta ~owner:(Wire_chat_journal.Unobserved_scope (Some 2)) "scope ")
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (delta ~owner:(obs 2 1) "PRECEDING_SCOPE_DROPPED")
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (delta ~owner:(obs 2 2) "final.")
  in
  let buf2 = Fleet_store.String_map.find keeper f2.chat_streams in
  Alcotest.(check string)
    "stale retired and out-of-scope deltas dropped while attempt 2 accepted"
    "Attempt 2 scope final." buf2.text;
  (* Post-RUN_FINISHED late delta is ignored and does not resurrect buffer. *)
  let f3 =
    f2
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (Wire_fleet.Chunk_turn_done
            { operation_id = Some req; turn_ref = None; reply = None })
    |> Fleet_store.apply_chat_stream_chunk ~keeper ~request_id:req
         (delta ~owner:(obs 3 0) "LATE_AFTER_DONE")
  in
  let buf3 = Fleet_store.String_map.find keeper f3.chat_streams in
  Alcotest.(check string) "late delta after RUN_FINISHED ignored"
    "Attempt 2 scope final." buf3.text;
  Alcotest.(check bool) "buffer stays inactive after late delta" false buf3.active;
  Alcotest.(check bool) "buffer stays ended after late delta" true buf3.ended;
  (* /btw side-query also honors runtime attempt retry and response ownership. *)
  let t0 = Clock.Mono.zero in
  let drafts0, btw_id =
    Drafts.start_btw ~now:t0 ~keeper ~prompt:"status?" Drafts.empty
  in
  let m0 = { (Model.initial ()) with drafts = drafts0 } in
  let feed_btw m chunk =
    fst
      (Update.step ~now:t0 m
         (Msg.Chat_stream_chunk
            { epoch = m.epoch; keeper; request_id = btw_id; is_btw = true; chunk }))
  in
  let m_btw =
    m0
    |> (fun m -> feed_btw m (Wire_fleet.Chunk_run_started { operation_id = Some btw_id }))
    |> (fun m -> feed_btw m (delta ~owner:(obs 1 0) "btw attempt 1"))
    |> (fun m ->
         feed_btw m
           (Wire_fleet.Chunk_runtime_attempt_started
              { operation_id = Some btw_id; runtime_id = None; attempt_index = None }))
    |> (fun m -> feed_btw m (delta ~owner:(obs 1 0) "stale btw"))
    |> (fun m -> feed_btw m (delta ~owner:(obs 2 0) "btw clean"))
    |> (fun m ->
         feed_btw m
           (Wire_fleet.Chunk_turn_done
              { operation_id = Some btw_id; turn_ref = None; reply = None }))
  in
  match m_btw.drafts.btw with
  | Drafts.Btw_answered { reply; _ } ->
      Alcotest.(check string) "/btw retires attempt 1 and keeps attempt 2"
        "btw clean" reply
  | Drafts.Btw_idle | Drafts.Btw_sending _ | Drafts.Btw_streaming _
  | Drafts.Btw_failed _ ->
      Alcotest.fail "expected Btw_answered"

let test_24h_pulse_sparkline_and_sums_use_now_unix () =
  let slot_now = 1_795_251_600 in
  let now_unix = Float.of_int (slot_now + 300) in
  let slot_expired_edge = slot_now - (48 * Wire_fleet.turn_slot_seconds) in
  let slot_oldest_included = slot_now - (47 * Wire_fleet.turn_slot_seconds) in
  let slot_future = slot_now + Wire_fleet.turn_slot_seconds in
  let slot_recent = slot_now - (2 * Wire_fleet.turn_slot_seconds) in
  let mk_slot starts_at ok failed : Wire_fleet.turn_slot =
    {
      starts_at;
      ok;
      rested = 1;
      failed;
      scheduled = ok;
      reacted = failed;
      chat = 0;
      own = 1;
      unknown = 0;
    }
  in
  let stale_pulse : Wire_fleet.turn_pulse =
    {
      known_since = Float.of_int slot_expired_edge;
      slots = [ mk_slot slot_expired_edge 10 2; mk_slot slot_future 7 0 ];
    }
  in
  let recent_pulse : Wire_fleet.turn_pulse =
    {
      known_since = Float.of_int slot_expired_edge;
      slots =
        [
          mk_slot slot_expired_edge 20 0;
          mk_slot slot_oldest_included 1 0;
          mk_slot slot_recent 2 1;
          mk_slot slot_future 9 0;
        ];
    }
  in
  let ks =
    [
      grouped_keeper ~group:"org-a" "stale-keeper";
      grouped_keeper ~group:"org-a" "active-keeper";
      grouped_keeper ~group:"org-b" "no-pulse-keeper";
    ]
  in
  let m0 = Model.initial ~cols:140 ~rows:40 ~wall_unix:now_unix () in
  let shell_stub : Wire_fleet.dashboard_shell =
    {
      generated_at_unix = Some now_unix;
      project = Some "test";
      version = Some "0.1";
      counts =
        {
          agents = 0;
          tasks = 0;
          tasks_done_24h = 0;
          keepers = 3;
          persisted_keepers = Observed.unreported;
          configured_keepers = Observed.unreported;
          total_runtimes = 1;
        };
      scorecard_24h =
        {
          tasks_done_24h = Observed.unreported;
          tasks_done_total = Observed.unreported;
          tasks_in_progress = Observed.unreported;
          tasks_claimed = Observed.unreported;
          tasks_awaiting_verification = Observed.unreported;
          tasks_todo = Observed.unreported;
          tasks_cancelled = Observed.unreported;
          goals_completed_24h = Observed.unreported;
          verifications_passed_24h = Observed.unreported;
          verifications_rejected_24h = Observed.unreported;
          board_posts_24h = Observed.unreported;
          turns_24h = Observed.unreported;
          cost_24h_usd = Observed.unreported;
        };
      groups = [];
    }
  in
  let fleet =
    m0.fleet
    |> Fleet_store.apply_shell ~observed_at:t0 shell_stub
    |> Fleet_store.apply_keepers ~observed_at:t0 ks
    |> Fleet_store.apply_roster_extras
         {
           sandbox_profiles = [];
           candle_balances_milli = [];
           candle_summary = None;
           turn_pulses =
             [ ("stale-keeper", stale_pulse); ("active-keeper", recent_pulse) ];
           diagnostics = [];
           roster_total = None;
           roster_truncated = false;
         }
  in
  (* Stale keeper has only the 48-slots-ago expired boundary slot and a future
     slot: 0 turns in 24h window and 48 zero slots. *)
  Alcotest.(check (option int)) "stale keeper excludes 48-slots-ago and future slots"
    (Some 0)
    (Fleet_store.keeper_turns_24h ~now_unix ~keeper:"stale-keeper" fleet);
  Alcotest.(check bool) "stale keeper sparkline is 48 zeros" true
    (let sp = Fleet_store.sparkline_24h ~now_unix ~keeper:"stale-keeper" fleet in
     List.length sp = 48 && List.for_all (fun v -> Float.equal v 0.0) sp);
  (* Active keeper counts 47-slots-ago boundary (1) + recent slot (2 ok + 1 failed = 3) = 4;
     excludes 48-slots-ago (20), future (9), and rested. *)
  Alcotest.(check (option int))
    "active keeper includes 47-slots-ago & recent, excludes 48-slots-ago & future"
    (Some 4)
    (Fleet_store.keeper_turns_24h ~now_unix ~keeper:"active-keeper" fleet);
  let active_spark =
    Fleet_store.sparkline_24h ~now_unix ~keeper:"active-keeper" fleet
  in
  Alcotest.(check int) "active sparkline length is 48" 48
    (List.length active_spark);
  Alcotest.(check (float 0.01))
    "oldest in-window slot (47 slots ago) lands at sparkline index 0" 1.0
    (List.hd active_spark);
  Alcotest.(check (list (float 0.01)))
    "quiet trailing slots after recent turn appear as zeros"
    [ 3.0; 0.0; 0.0 ]
    (List.filteri (fun i _ -> i >= 45) active_spark);
  (* Keeper without pulse returns None / []. *)
  Alcotest.(check (option int)) "no-pulse keeper returns None" None
    (Fleet_store.keeper_turns_24h ~now_unix ~keeper:"no-pulse-keeper" fleet);
  Alcotest.(check int) "no-pulse keeper sparkline is empty" 0
    (List.length
       (Fleet_store.sparkline_24h ~now_unix ~keeper:"no-pulse-keeper" fleet));
  (* Fleet total_turns_24h and company_groups sum only in-window turns. *)
  Alcotest.(check (option int)) "fleet total_turns_24h sums in-window turns only"
    (Some 4) (Fleet_store.total_turns_24h ~now_unix fleet);
  let org_a =
    List.find
      (fun (g : Wire_fleet.company_group) -> String.equal g.company "org-a")
      (Fleet_store.company_groups ~now_unix fleet)
  in
  Alcotest.(check int) "company turns_24h excludes >24h slots" 4 org_a.turns_24h;
  Alcotest.(check int) "company sparkline has 48 aligned slots" 48
    (List.length org_a.sparkline_24h);
  (* Fleet_pulse_wall sorts active-keeper ahead of stale-keeper even though stale
     keeper has more expired turns in its pulse buffer. *)
  let f_wall = Fleet_store.set_fleet_mode Nav.Fleet_pulse_wall fleet in
  let ordered_names =
    List.map
      (fun (k : Wire_fleet.keeper_summary) -> k.name)
      (Fleet_store.filtered_keepers f_wall)
  in
  Alcotest.(check (list string))
    "Fleet_pulse_wall ranks in-window active keeper first"
    [ "active-keeper"; "no-pulse-keeper"; "stale-keeper" ]
    ordered_names;
  (* Advancing wall clock via Msg.Tick past 24h refreshes BOTH Fleet_store.total_turns_24h
     AND the cached scorecard (m.fleet.shell.scorecard_24h.turns_24h). *)
  let m1 =
    { m0 with fleet = f_wall } |> Model.sync_effective_scorecard ~now:t0
  in
  let scorecard_turns (m : Model.t) =
    match Observed.to_option m.fleet.shell with
    | Some sh -> Observed.to_option sh.scorecard_24h.turns_24h
    | None -> None
  in
  Alcotest.(check (option int))
    "scorecard turns_24h starts at 4 before idle Tick" (Some 4)
    (scorecard_turns m1);
  let future_unix = now_unix +. (25.0 *. 3600.0) in
  let m2, _ = Update.step ~now:t1 m1 (Msg.Tick { wall_unix = future_unix }) in
  Alcotest.(check (option int))
    "Tick advancing >24h drops fleet total_turns_24h to 0" (Some 0)
    (Fleet_store.total_turns_24h ~now_unix:m2.freshness.last_wall_unix m2.fleet);
  Alcotest.(check (option int))
    "Tick advancing >24h refreshes cached scorecard turns_24h to 0" (Some 0)
    (scorecard_turns m2)

let test_media_viewer_follows_artifact_dive_target () =
  let art_list : Wire_knowledge.artifact_entry =
    {
      id = "artifact-list-001";
      revision = 1;
      title = "List Selected";
      summary = "";
      author = "alpha";
      created_at_unix = 1_795_254_000.0;
      body = { sha256 = "sha-list-001"; bytes = 64; mime = "text/markdown" };
    }
  in
  let art_dive : Wire_knowledge.artifact_entry =
    {
      id = "artifact-dive-002";
      revision = 2;
      title = "Dive Target";
      summary = "";
      author = "beta";
      created_at_unix = 1_795_254_100.0;
      body = { sha256 = "sha-dive-002"; bytes = 128; mime = "text/html" };
    }
  in
  let knowledge =
    Knowledge_store.empty
    |> Knowledge_store.apply_artifacts ~observed_at:t0 [ art_list; art_dive ]
  in
  let m0 =
    let base = Model.initial () in
    {
      base with
      knowledge;
      nav =
        {
          base.nav with
          workspace = Nav.Knowledge;
          dive_stack = [ Nav.Dive_knowledge (Nav.Artifact_dive art_dive.id) ];
          overlay = Some (Nav.System_gate Nav.Media_viewer);
        };
    }
  in
  Alcotest.(check (option string))
    "focused_artifact resolves Artifact_dive target instead of list selection"
    (Some art_dive.id)
    (Option.map (fun (a : Wire_knowledge.artifact_entry) -> a.id)
       (Model.focused_artifact m0));
  let step_char ch m =
    Update.step ~now:t1 m
      (Msg.Key_event
         { key = Keymap.Input.Char ch; mods = Keymap.Input.no_mods })
  in
  let _, cmds_h = step_char "H" m0 in
  Alcotest.(check bool) "Media_viewer [H] copies dive artifact SHA-256" true
    (List.exists
       (function
         | Cmd.Copy_clipboard s -> String.equal s art_dive.body.sha256
         | _ -> false)
       (Cmd.flatten cmds_h));
  let _, cmds_e = step_char "e" m0 in
  Alcotest.(check bool) "Media_viewer [e] exports dive artifact" true
    (List.exists
       (function
         | Cmd.Export_artifact { id; open_after = false; _ } ->
             String.equal id art_dive.id
         | _ -> false)
       (Cmd.flatten cmds_e));
  let _, cmds_o = step_char "o" m0 in
  Alcotest.(check bool) "Media_viewer [o] opens dive artifact" true
    (List.exists
       (function
         | Cmd.Export_artifact { id; open_after = true; _ } ->
             String.equal id art_dive.id
         | _ -> false)
       (Cmd.flatten cmds_o));
  let _, cmds_y = step_char "y" m0 in
  Alcotest.(check bool) "Media_viewer [y] fetches/copies dive artifact" true
    (List.exists
       (function
         | Cmd.Fetch_artifact_and_copy { id; _ } -> String.equal id art_dive.id
         | _ -> false)
       (Cmd.flatten cmds_y));
  (* Missing dive target never falls back to the unrelated list selection. *)
  let m_missing =
    {
      m0 with
      nav =
        {
          m0.nav with
          dive_stack = [ Nav.Dive_knowledge (Nav.Artifact_dive "missing-art") ];
        };
    }
  in
  Alcotest.(check bool)
    "missing Artifact_dive target returns None instead of list selection" true
    (Option.is_none (Model.focused_artifact m_missing));
  let m_y_miss, cmds_y_miss = step_char "y" m_missing in
  Alcotest.(check int) "missing dive [y] emits no copy command" 0
    (List.length (Cmd.flatten cmds_y_miss));
  Alcotest.(check bool) "missing dive [y] emits warning toast" true
    (Option.is_some m_y_miss.toast);
  let m_o_miss, cmds_o_miss = step_char "o" m_missing in
  Alcotest.(check int) "missing dive [o] emits no export command" 0
    (List.length (Cmd.flatten cmds_o_miss));
  Alcotest.(check bool) "missing dive [o] emits warning toast" true
    (Option.is_some m_o_miss.toast);
  (* active_artifact_target under Media_viewer:
     (a) list filter hiding selected_artifact still lets [v] and share/copy act on Artifact_dive;
     (b) missing Artifact_dive target never falls back to selected list item. *)
  let ws_id : Wire_common.workspace_identity =
    {
      instance_id = Some "inst-media-test";
      base_path = "/tmp/test-ws";
      masc_root = "/tmp/test-ws/.masc";
      workspace_sha256 = None;
    }
  in
  let dive_detail : Wire_knowledge.published_artifact_detail =
    {
      artifact = art_dive;
      content = "<h1>Dive</h1>";
      revisions = [];
      shared = false;
      share_version = 1;
    }
  in
  let list_detail : Wire_knowledge.published_artifact_detail =
    {
      artifact = art_list;
      content = "# List";
      revisions = [];
      shared = false;
      share_version = 1;
    }
  in
  let m_filtered =
    let k_filtered =
      m0.knowledge
      |> Knowledge_store.apply_artifact_detail ~observed_at:t0 dive_detail
      |> Knowledge_store.set_filter "unmatched-filter-xyz"
    in
    {
      m0 with
      knowledge = k_filtered;
      server_identity = { m0.server_identity with workspace = Some ws_id };
    }
  in
  Alcotest.(check bool) "filtered artifact list has selected_artifact = None" true
    (Option.is_none (Knowledge_store.selected_artifact m_filtered.knowledge));
  let m_v_filt, _ = step_char "v" m_filtered in
  Alcotest.(check bool)
    "Media_viewer [v] toggles view mode for Artifact_dive even when list filter empties selected_artifact"
    true
    (m_v_filt.knowledge.artifact_view_mode = `Raw_source);
  let _, cmds_hash_filt =
    Update_actions.execute_action ~now:t1 m_filtered Keymap.Copy_hash
  in
  Alcotest.(check bool)
    "Copy_hash under Media_viewer + filtered list copies Artifact_dive SHA-256"
    true
    (List.exists
       (function
         | Cmd.Copy_clipboard s -> String.equal s art_dive.body.sha256
         | _ -> false)
       (Cmd.flatten cmds_hash_filt));
  let _, cmds_url_filt =
    Update_actions.execute_action ~now:t1 m_filtered Keymap.Copy_public_url
  in
  Alcotest.(check bool)
    "Copy_public_url under Media_viewer + filtered list copies Artifact_dive URL"
    true
    (List.exists
       (function
         | Cmd.Copy_clipboard s ->
             String.equal s ("/published-artifacts/" ^ art_dive.id)
         | _ -> false)
       (Cmd.flatten cmds_url_filt));
  let _, cmds_share_filt =
    Update_actions.execute_action ~now:t1 m_filtered Keymap.Toggle_artifact_share
  in
  Alcotest.(check bool)
    "Toggle_artifact_share under Media_viewer + filtered list targets Artifact_dive"
    true
    (List.exists
       (function
         | Cmd.Http_post { req = Cmd.Post_artifact_share { id; _ }; _ } ->
             String.equal id art_dive.id
         | _ -> false)
       (Cmd.flatten cmds_share_filt));
  let m_missing_with_list =
    let k_list_detail =
      Knowledge_store.apply_artifact_detail ~observed_at:t0 list_detail
        m_missing.knowledge
    in
    {
      m_missing with
      knowledge = k_list_detail;
      server_identity = { m_missing.server_identity with workspace = Some ws_id };
    }
  in
  Alcotest.(check (option string))
    "unrelated list artifact is selected while Artifact_dive target is missing"
    (Some art_list.id)
    (Option.map (fun (a : Wire_knowledge.artifact_entry) -> a.id)
       (Knowledge_store.selected_artifact m_missing_with_list.knowledge));
  let m_v_miss, cmds_v_miss = step_char "v" m_missing_with_list in
  Alcotest.(check bool)
    "missing Artifact_dive [v] does not toggle artifact_view_mode" true
    (m_v_miss.knowledge.artifact_view_mode = `Document);
  Alcotest.(check int) "missing Artifact_dive [v] emits 0 cmds" 0
    (List.length (Cmd.flatten cmds_v_miss));
  let _, cmds_share_miss =
    Update_actions.execute_action ~now:t1 m_missing_with_list
      Keymap.Toggle_artifact_share
  in
  Alcotest.(check int)
    "missing Artifact_dive Toggle_artifact_share does not touch list artifact" 0
    (List.length (Cmd.flatten cmds_share_miss));
  let _, cmds_hash_miss =
    Update_actions.execute_action ~now:t1 m_missing_with_list Keymap.Copy_hash
  in
  Alcotest.(check int)
    "missing Artifact_dive Copy_hash does not touch list artifact" 0
    (List.length (Cmd.flatten cmds_hash_miss));
  let _, cmds_url_miss =
    Update_actions.execute_action ~now:t1 m_missing_with_list
      Keymap.Copy_public_url
  in
  Alcotest.(check int)
    "missing Artifact_dive Copy_public_url does not touch list artifact" 0
    (List.length (Cmd.flatten cmds_url_miss))

let test_single_slot_dive_error_target_guards () =
  let ws_mismatch_err =
    Msg.Workspace_mismatch
      {
        expected_instance = Some "inst-a";
        observed_instance = Some "inst-b";
        observed_workspace_sha256 = None;
        message = "restarted";
      }
  in
  let err_500 detail =
    Msg.Http_error { status = 500; body = detail; api_error = None }
  in
  let err_403 detail =
    Msg.Http_error { status = 403; body = detail; api_error = None }
  in
  let err_401 detail =
    Msg.Http_error { status = 401; body = detail; api_error = None }
  in
  let is_failed = function
    | Observed.Failed _ -> true
    | Observed.Absent | Observed.Unreported | Observed.Loading _
    | Observed.Value _ ->
        false
  in
  (* (a) Runtime_fusion selected run-B ignores delayed Reply_fusion_run_detail Error for A,
     still routes Workspace_mismatch, and records matching B error. *)
  let mk_fusion_run run_id : Wire_runtime.fusion_run =
    {
      run_id;
      keeper = "alpha";
      preset = "consensus";
      topology = Wire_runtime.Judge_of_judges;
      started_at_unix = 1795253000.0;
      finished_at_unix = None;
      status = Wire_runtime.Fusion_running;
      stage = "panel";
      decision = None;
      summary = None;
    }
  in
  let m_fusion_b =
    let base = Model.initial () in
    let rt =
      base.runtime
      |> Runtime_store.set_tab Nav.Runtime_fusion
      |> Runtime_store.apply_fusion_runs ~observed_at:t0
           [ mk_fusion_run "run-A"; mk_fusion_run "run-B" ]
    in
    {
      base with
      nav =
        {
          base.nav with
          workspace = Nav.Runtime;
          zoomed = true;
          pane_index = 0;
        };
      runtime = { rt with fusion_selected_index = 1 };
    }
  in
  let m_f_stale, cmds_f_stale =
    Update.step ~now:t1 m_fusion_b
      (Msg.Http_reply
         {
           epoch = m_fusion_b.epoch;
           reply =
             Msg.Reply_fusion_run_detail
               { run_id = "run-A"; result = Error (err_500 "stale run-A boom") };
         })
  in
  Alcotest.(check bool)
    "Runtime_fusion run-B ignores stale run-A Error (slot not Failed)" false
    (is_failed m_f_stale.runtime.fusion_detail);
  Alcotest.(check int) "Runtime_fusion run-B ignores stale run-A Error (0 cmds)" 0
    (List.length (Cmd.flatten cmds_f_stale));
  let m_f_ws, cmds_f_ws =
    Update.step ~now:t1 m_fusion_b
      (Msg.Http_reply
         {
           epoch = m_fusion_b.epoch;
           reply =
             Msg.Reply_fusion_run_detail
               { run_id = "run-A"; result = Error ws_mismatch_err };
         })
  in
  Alcotest.(check bool)
    "Runtime_fusion run-B still handles Workspace_mismatch even for run-A" true
    ((not (Epoch.equal m_f_ws.epoch m_fusion_b.epoch))
     && List.exists
          (function
            | Cmd.Http_get { req = Cmd.Get_health; _ } -> true
            | _ -> false)
          (Cmd.flatten cmds_f_ws));
  let m_f_match, _ =
    Update.step ~now:t1 m_fusion_b
      (Msg.Http_reply
         {
           epoch = m_fusion_b.epoch;
           reply =
             Msg.Reply_fusion_run_detail
               { run_id = "run-B"; result = Error (err_500 "run-B boom") };
         })
  in
  Alcotest.(check bool)
    "Runtime_fusion run-B records matching run-B Error on fusion_detail" true
    (is_failed m_f_match.runtime.fusion_detail);
  (* (b) Verification_dive B ignores delayed 401/403/500 Error for A without
     poisoning verification_evidence or verification_evidence_auth_denied,
     still routes Workspace_mismatch, and applies matching B errors. *)
  let m_verif_b =
    let base = Model.initial () in
    {
      base with
      nav =
        {
          base.nav with
          workspace = Nav.Work;
          dive_stack = [ Nav.Dive_work (Nav.Verification_dive "verif-B") ];
        };
    }
  in
  List.iter
    (fun (label, err) ->
      let m_stale, cmds_stale =
        Update.step ~now:t1 m_verif_b
          (Msg.Http_reply
             {
               epoch = m_verif_b.epoch;
               reply =
                 Msg.Reply_verification_evidence
                   { verification_id = "verif-A"; result = Error err };
             })
      in
      Alcotest.(check bool)
        (Printf.sprintf "Verification_dive B ignores stale verif-A %s (slot intact)"
           label)
        false
        (is_failed m_stale.work.verification_evidence);
      Alcotest.(check bool)
        (Printf.sprintf
           "Verification_dive B ignores stale verif-A %s (auth_denied stays false)"
           label)
        false m_stale.work.verification_evidence_auth_denied;
      Alcotest.(check int)
        (Printf.sprintf "Verification_dive B ignores stale verif-A %s (0 cmds)"
           label)
        0
        (List.length (Cmd.flatten cmds_stale)))
    [
      ("403", err_403 "forbidden A");
      ("401", err_401 "unauthorized A");
      ("500", err_500 "server error A");
      ("transport", Msg.Transport (Health.Other_io "timeout A"));
    ];
  let m_v_ws, _ =
    Update.step ~now:t1 m_verif_b
      (Msg.Http_reply
         {
           epoch = m_verif_b.epoch;
           reply =
             Msg.Reply_verification_evidence
               { verification_id = "verif-A"; result = Error ws_mismatch_err };
         })
  in
  Alcotest.(check bool)
    "Verification_dive B still handles Workspace_mismatch even for verif-A" true
    (not (Epoch.equal m_v_ws.epoch m_verif_b.epoch));
  let m_v_denied, _ =
    Update.step ~now:t1 m_verif_b
      (Msg.Http_reply
         {
           epoch = m_verif_b.epoch;
           reply =
             Msg.Reply_verification_evidence
               {
                 verification_id = "verif-B";
                 result = Error (err_403 "forbidden B");
               };
         })
  in
  Alcotest.(check bool)
    "Verification_dive B matching 403 sets verification_evidence_auth_denied"
    true m_v_denied.work.verification_evidence_auth_denied;
  Alcotest.(check bool)
    "Verification_dive B matching 403 marks verification_evidence Failed" true
    (is_failed m_v_denied.work.verification_evidence);
  let m_v_500, _ =
    Update.step ~now:t1 m_verif_b
      (Msg.Http_reply
         {
           epoch = m_verif_b.epoch;
           reply =
             Msg.Reply_verification_evidence
               {
                 verification_id = "verif-B";
                 result = Error (err_500 "server error B");
               };
         })
  in
  Alcotest.(check bool)
    "Verification_dive B matching 500 marks verification_evidence Failed" true
    (is_failed m_v_500.work.verification_evidence);
  Alcotest.(check bool)
    "Verification_dive B matching 500 leaves auth_denied false" false
    m_v_500.work.verification_evidence_auth_denied;
  (* (c) Runtime_trace_dive B ignores delayed Error for A, accepts B. *)
  let m_trace_b =
    let base = Model.initial () in
    {
      base with
      nav =
        {
          base.nav with
          workspace = Nav.Infra;
          dive_stack = [ Nav.Dive_infra (Nav.Runtime_trace_dive "beta") ];
        };
    }
  in
  let m_t_stale, _ =
    Update.step ~now:t1 m_trace_b
      (Msg.Http_reply
         {
           epoch = m_trace_b.epoch;
           reply =
             Msg.Reply_keeper_runtime_trace
               { keeper = "alpha"; result = Error (err_500 "stale alpha") };
         })
  in
  Alcotest.(check bool)
    "Runtime_trace_dive beta ignores stale alpha Error" false
    (is_failed m_t_stale.infra.runtime_trace);
  let m_t_match, _ =
    Update.step ~now:t1 m_trace_b
      (Msg.Http_reply
         {
           epoch = m_trace_b.epoch;
           reply =
             Msg.Reply_keeper_runtime_trace
               { keeper = "beta"; result = Error (err_500 "beta boom") };
         })
  in
  Alcotest.(check bool)
    "Runtime_trace_dive beta records matching beta Error" true
    (is_failed m_t_match.infra.runtime_trace)

let test_ux_batch1_focus_resize_micro_zoom_and_cli_prefs () =
  let t0 = Clock.Mono.of_ns 1_000_000_000L in
  let mk_approval ~id ~keeper ~tool_name : Wire_work.held_tool_approval =
    {
      approval_id = id;
      tool_call_id = "tc-" ^ id;
      keeper;
      tool = tool_name;
      args_preview = "{}";
      question = "Approve " ^ tool_name ^ "?";
      because = None;
      asked_at = 1700000000.0;
      timeout_sec = 60.0;
    }
  in
  (* UX-01: Pulse Attention [Y]/[N]/[J] honors triage_index and clears blocking Inbox filter *)
  let a1 = mk_approval ~id:"apr-1" ~keeper:"alpha" ~tool_name:"shell_exec" in
  let a2 = mk_approval ~id:"apr-2" ~keeper:"beta" ~tool_name:"git_push" in
  let m0 = Model.initial ~cols:140 ~rows:40 ~lang:Say.Lang_en () in
  let attn =
    Attention.rebuild ~asks:[] ~tool_approvals:[ a1; a2 ] ~gate_pending:[]
      ~goals:[] m0.attention
    |> Attention.select_triage_index 1
  in
  let m_pulse = { m0 with attention = attn } in
  (match Model.fast_approval_strip_item m_pulse with
   | Some e ->
       Alcotest.(check bool) "UX-01 Pulse strip matches triage_index=1 (apr-2)"
         true
         (String.ends_with ~suffix:"apr-2" e.id)
   | None -> Alcotest.fail "UX-01 expected fast_approval_strip_item on Pulse");
  let _, cmds_y = Update.execute_action ~now:t0 m_pulse Keymap.Fast_approve_top in
  let approved_id =
    List.find_map
      (function
        | Cmd.Http_post { req = Cmd.Post_tool_approval { approval_id; _ }; _ } ->
            Some approval_id
        | _ -> None)
      cmds_y
  in
  Alcotest.(check (option string))
    "UX-01 Pulse [Y] approves highlighted apr-2, not apr-1" (Some "apr-2")
    approved_id;
  let m_pulse_filtered_inbox =
    { m_pulse with work = Work_store.set_filter "alpha-only" m_pulse.work }
  in
  let m_jumped, _ =
    Update.execute_action ~now:t0 m_pulse_filtered_inbox Keymap.Teleport_blocked
  in
  Alcotest.(check bool) "UX-01 [J] switches to Work_inbox" true
    (Nav.equal_workspace m_jumped.nav.workspace Nav.Work
     && Nav.equal_work_tab m_jumped.work.active_tab Nav.Work_inbox);
  Alcotest.(check string) "UX-01 [J] clears stale Inbox filter hiding target" ""
    m_jumped.work.filter_query;
  Alcotest.(check int) "UX-01 [J] selects target apr-2 in Inbox" 1
    m_jumped.attention.triage_index;

  (* UX-02: Micro (<80x24) blurs hidden Composer/Filter and blocks typing & Enter *)
  let m_comp =
    {
      m0 with
      drafts =
        m0.drafts |> Drafts.set_active_keeper "alpha"
        |> Drafts.insert_text "secret-draft"
        |> Drafts.set_focus true;
      nav = { m0.nav with filter_focused = true };
    }
  in
  let m_micro, _ =
    Update.step ~now:t0 m_comp (Msg.Resize { cols = 70; rows = 20 })
  in
  Alcotest.(check bool) "UX-02 Resize to Micro blurs composer" false
    (Drafts.is_focused m_micro.drafts);
  Alcotest.(check bool) "UX-02 Resize to Micro blurs filter" false
    m_micro.nav.filter_focused;
  Alcotest.(check bool) "UX-02 Micro body_has_focus is false" false
    (Model.body_has_focus m_micro);
  let m_micro_typed, cmds_micro_enter =
    let m1, _ = Update.step ~now:t0 m_micro (Msg.Key_event (char_key "z")) in
    Update.step ~now:t0 m1
      (Msg.Key_event
         {
           Keymap.Input.key = Keymap.Input.Enter;
           mods = { ctrl = false; alt = false; shift = false };
         })
  in
  Alcotest.(check string) "UX-02 Micro blocks typing into hidden draft"
    "secret-draft"
    (Drafts.draft_for ~keeper:"alpha" m_micro_typed.drafts).text;
  Alcotest.(check int) "UX-02 Micro blocks Enter submission" 0
    (List.length cmds_micro_enter);
  let ctrl_q_ev =
    Msg.Key_event
      {
        Keymap.Input.key = Keymap.Input.Char "q";
        mods = { ctrl = true; alt = false; shift = false };
      }
  in
  let m_micro_armed, cmds_micro_arm = Update.step ~now:t0 m_micro_typed ctrl_q_ev in
  Alcotest.(check bool) "UX-02 Micro 1st Ctrl+Q arms quit without exiting" true
    (Option.is_some m_micro_armed.quit_armed_at
     && not (List.exists (function Cmd.Quit _ -> true | _ -> false) cmds_micro_arm));
  let _, cmds_micro_quit = Update.step ~now:t0 m_micro_armed ctrl_q_ev in
  Alcotest.(check bool) "UX-02 Micro 2nd Ctrl+Q still allows Quit" true
    (List.exists (function Cmd.Quit _ -> true | _ -> false) cmds_micro_quit);
  let m_micro_help, _ =
    Update.step ~now:t0 m_micro_typed (Msg.Key_event (char_key "?"))
  in
  Alcotest.(check bool) "UX-02 Micro allows '?' Help overlay" true
    (match m_micro_help.nav.overlay with Some Nav.Help -> true | _ -> false);
  let m_micro_attn =
    let m_ma, _ =
      Update.step ~now:t0 m_pulse (Msg.Resize { cols = 70; rows = 20 })
    in
    m_ma
  in
  let m_micro_j, _ =
    Update.step ~now:t0 m_micro_attn (Msg.Key_event (char_key "J"))
  in
  Alcotest.(check bool) "UX-02 Micro allows 'J' Teleport_blocked (visible Queue overlay)" true
    (Option.equal Nav.equal_overlay m_micro_j.nav.overlay
       (Some (Nav.Queue_context Nav.Drawer_queue)));
  let m_micro_settings =
    let m_s, _ =
      Update.step ~now:t0 m_micro_typed
        (Msg.Key_event
           {
             Keymap.Input.key = Keymap.Input.Char ",";
             mods = { ctrl = true; alt = false; shift = false };
           })
    in
    {
      m_s with
      nav = { m_s.nav with filter_focused = true };
      config =
        {
          m_s.config with
          editing_field_key = Some "tui.theme";
          editing_buffer = "paper";
          editing_cursor = 5;
        };
    }
  in
  let m_micro_settings_resized, _ =
    Update.step ~now:t0 m_micro_settings (Msg.Resize { cols = 72; rows = 21 })
  in
  Alcotest.(check bool)
    "UX-02 Micro resize preserves visible Settings overlay filter_focused" true
    m_micro_settings_resized.nav.filter_focused;
  Alcotest.(check bool)
    "UX-02 Micro resize preserves visible Settings field editing" true
    (Config_store.is_editing_field m_micro_settings_resized.config);
  let m_micro_pasted, _ =
    Update.step ~now:t0
      { m_micro_settings_resized with nav = { m_micro_settings_resized.nav with filter_focused = false } }
      (Msg.Paste_text "_light")
  in
  Alcotest.(check string)
    "UX-02 Micro paste works inside visible Settings field editor" "paper_light"
    m_micro_pasted.config.editing_buffer;

  (* UX-03: Resize clamps pane_index, drops unfocused docked pin, Esc closes unfocused drawer *)
  let m_keepers_p1 =
    let m_k =
      {
        m0 with
        fleet =
          Fleet_store.apply_roster ~observed_at:t0
            (roster_of [ sample_keeper "alpha" ])
            m0.fleet;
        nav =
          {
            m0.nav with
            workspace = Nav.Keepers;
            pane_index = 1;
            sidebar_open = Some true;
            sidebar_focused = false;
          };
      }
    in
    m_k
  in
  let m_shrunk, _ =
    Update.step ~now:t0 m_keepers_p1 (Msg.Resize { cols = 90; rows = 28 })
  in
  Alcotest.(check int) "UX-03 Resize clamps Keepers pane_index 1 -> 0" 0
    m_shrunk.nav.pane_index;
  Alcotest.(check bool)
    "UX-03 Crossing <132 while sidebar unfocused drops floating drawer" false
    (Model.sidebar_drawer_open m_shrunk);
  let m_unfocused_drawer =
    {
      m_shrunk with
      nav = { m_shrunk.nav with sidebar_open = Some true; sidebar_focused = false };
    }
  in
  Alcotest.(check bool) "UX-03 unfocused drawer is open" true
    (Model.sidebar_drawer_open m_unfocused_drawer);
  let m_drawer_esc, _ =
    Update.execute_action ~now:t0 m_unfocused_drawer Keymap.Pop_back_or_close
  in
  Alcotest.(check bool) "UX-03 Esc closes unfocused floating drawer" false
    (Model.sidebar_drawer_open m_drawer_esc);

  (* UX-05: Toggle_zoom keeps truthful ZOOM focus label & restores pane_index on unzoom *)
  let m_zoomed, _ =
    Update.execute_action ~now:t0 m_keepers_p1 Keymap.Toggle_zoom
  in
  Alcotest.(check bool) "UX-05 zoomed = true" true m_zoomed.nav.zoomed;
  Alcotest.(check int) "UX-05 zoomed pane_index clamped to 0" 0
    m_zoomed.nav.pane_index;
  Alcotest.(check bool) "UX-05 zoomed Focus Pill reflects ZOOM" true
    (String.starts_with ~prefix:"ZOOM"
       (Say.resolve Say.Lang_en (Model.active_focus_label m_zoomed)));
  let m_unzoomed, _ =
    Update.execute_action ~now:t0 m_zoomed Keymap.Toggle_zoom
  in
  Alcotest.(check bool) "UX-05 unzoomed = false" false m_unzoomed.nav.zoomed;
  Alcotest.(check int) "UX-05 unzoom restores pane_index = 1" 1
    m_unzoomed.nav.pane_index;

  (* UX-08: Multi-pane Dive Focus Pill & Keepers sidebar sub-tab cursor preservation *)
  let m_tc_dive =
    {
      m0 with
      nav =
        {
          m0.nav with
          workspace = Nav.Keepers;
          dive_stack =
            [ Nav.Dive_keeper { name = "alpha"; tab = Nav.Keeper_tool_calls } ];
          pane_index = 1;
        };
    }
  in
  Alcotest.(check string) "UX-08 Dive_keeper Tool Calls pane 1 Focus Pill"
    "2/2 alpha · Detail"
    (Say.resolve Say.Lang_en (Model.active_focus_label m_tc_dive));
  let with_draft =
    { m_tc_dive with
      drafts =
        m_tc_dive.drafts |> Drafts.set_active_keeper "alpha"
        |> Drafts.insert_text "unfinished" }
  in
  let press m char = Update.step ~now:t0 m (Msg.Key_event (char_key char)) in
  let focused, focus_cmds = press with_draft "z" in
  Alcotest.(check bool) "Keeper detail enters focus without moving panes" true
    (focused.nav.zoomed && Int.equal focused.nav.pane_index 1);
  Alcotest.(check int) "Keeper focus does not send a request" 0
    (List.length focus_cmds);
  let restored, _ = press focused "z" in
  Alcotest.(check bool) "Second z restores the detail and menu preference" true
    ((not restored.nav.zoomed)
     && Int.equal restored.nav.pane_index 1
     && Option.equal Bool.equal restored.nav.sidebar_open with_draft.nav.sidebar_open
     && Option.equal Nav.equal_dive (Model.active_dive restored)
          (Model.active_dive with_draft));
  let menu, _ = press focused "b" in
  Alcotest.(check bool) "b exits Keeper focus and hands input to the menu" true
    ((not menu.nav.zoomed) && Model.sidebar_has_focus menu);
  Alcotest.(check string) "Focus and menu keep the unsent draft" "unfinished"
    (Drafts.draft_for ~keeper:"alpha" menu.drafts).text;
  let m_k_ctx_p0 =
    {
      m_keepers_p1 with
      nav = { m_keepers_p1.nav with pane_index = 0 };
      fleet = Fleet_store.set_keeper_dive_tab Nav.Keeper_context m_keepers_p1.fleet;
    }
  in
  Alcotest.(check bool)
    "UX-08 active_menu_target keeps Keeper_context even on pane 0" true
    (match Model.active_menu_target m_k_ctx_p0 with
     | Nav.Menu_keeper_tab Nav.Keeper_context -> true
     | _ -> false);

  (* UX-09: CLI --lang / --theme override survives boot Reply_tui_preferences *)
  let m_cli =
    Model.initial ~lang:Say.Lang_ko ~theme_preset:Theme.Paper_light
      ~cli_lang_override:true ~cli_theme_override:true ()
  in
  let server_prefs : Wire_config.tui_preferences =
    {
      language = Some Say.Lang_en;
      theme = Some "midnight";
      board_sort = None;
      reduce_motion = None;
      hints_visible = None;
      coalesce_queued_input = None;
      send_on_stop = None;
      audio_input_device = None;
    }
  in
  let m_after_prefs, _ =
    Update.step ~now:t0 m_cli
      (Msg.Http_reply
         {
           epoch = m_cli.epoch;
           reply = Msg.Reply_tui_preferences (Ok server_prefs);
         })
  in
  Alcotest.(check bool) "UX-09 CLI --lang ko survives Reply_tui_preferences" true
    (Say.equal_lang m_after_prefs.lang Say.Lang_ko);
  Alcotest.(check bool) "UX-09 CLI --theme paper survives Reply_tui_preferences"
    true
    (Theme.equal_preset m_after_prefs.theme_preset Theme.Paper_light);
  let m_explicit_en, _ =
    Update.execute_slash ~now:t0 m_after_prefs (Slash.Lang (Some Say.Lang_en))
  in
  Alcotest.(check bool) "UX-09 explicit /lang en updates lang" true
    (Say.equal_lang m_explicit_en.lang Say.Lang_en);
  Alcotest.(check bool) "UX-09 explicit /lang clears cli_lang_override" false
    m_explicit_en.cli_lang_override

let test_ux_batch2_modals_settings_overlays () =
  let step m ev = Update.step ~now:t0 m (Msg.Key_event ev) in
  let has_cmd pred cmds = List.exists pred cmds in
  let m_base = Model.initial ~cols:120 ~rows:34 () in
  let k_alpha = grouped_keeper ~group:"org-a" "alpha" in
  let k_beta = grouped_keeper ~group:"org-a" "beta" in
  let m_fleet =
    {
      m_base with
      fleet =
        Fleet_store.apply_keepers ~observed_at:t0 [ k_alpha; k_beta ]
          m_base.fleet;
    }
  in

  (* UX-10: Ack_toast_only never closes an open inline modal; Ack_close_modal_and_refresh closes + refreshes; Reply_memory_act Error sets Toast_error *)
  let m_modal, _ = Update_nav.open_inline_modal m_fleet Nav.Repo_add_form in
  let m_after_bg, _ =
    Update.step ~now:t0 m_modal
      (Msg.Http_reply
         {
           epoch = m_modal.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "Copied";
                 ack_scope = Msg.Ack_toast_only;
                 for_modal = None;
                 result = Ok ();
               };
         })
  in
  Alcotest.(check bool) "UX-10 Ack_toast_only preserves open inline modal" true
    (Option.is_some m_after_bg.inline_modal
    && Option.is_some m_after_bg.nav.overlay);
  let m_submitting =
    {
      m_after_bg with
      inline_modal =
        Option.map
          (fun (md : Model.inline_modal_state) -> { md with submitting = true })
          m_after_bg.inline_modal;
    }
  in
  let m_after_submit, cmds_submit =
    Update.step ~now:t0 m_submitting
      (Msg.Http_reply
         {
           epoch = m_submitting.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "Repo added";
                 ack_scope = Msg.Ack_close_modal_and_refresh;
                 for_modal = Some Nav.Repo_add_form;
                 result = Ok ();
               };
         })
  in
  Alcotest.(check bool) "UX-10 Ack_close_modal_and_refresh closes modal" true
    (Option.is_none m_after_submit.inline_modal
    && Option.is_none m_after_submit.nav.overlay);
  Alcotest.(check bool) "UX-10 Ack_close_modal_and_refresh refreshes current view"
    true (cmds_submit <> []);
  let m_mem_err, _ =
    Update.step ~now:t0 m_fleet
      (Msg.Http_reply
         {
           epoch = m_fleet.epoch;
           reply =
             Msg.Reply_memory_act
               {
                 keeper = "alpha";
                 result =
                   Error
                     (Msg.Http_error
                        { status = 500; body = "boom"; api_error = None });
               };
         })
  in
  Alcotest.(check bool) "UX-10 Reply_memory_act error shows Toast_error" true
    (match m_mem_err.toast with
    | Some { level = Model.Toast_error; _ } -> true
    | Some _ | None -> false);

  (* UX-11: Inline modal cursor movement, mid-string insert, Delete, Ctrl+U, Ctrl+W *)
  let m_m0, _ = Update_nav.open_inline_modal m_fleet Nav.Repo_add_form in
  let m_m1, _ = step m_m0 (char_key "a") in
  let m_m2, _ = step m_m1 (char_key "c") in
  let m_m3, _ = step m_m2 (key Keymap.Input.Left) in
  let m_m4, _ = step m_m3 (char_key "b") in
  let cur_val m =
    match m.Model.inline_modal with
    | Some mdl -> Model.modal_active_field_value mdl
    | None -> ""
  in
  Alcotest.(check string) "UX-11 inline modal Left + insert edits mid-string"
    "abc" (cur_val m_m4);
  let m_m5, _ = step m_m4 (key Keymap.Input.Home) in
  let m_m6, _ = step m_m5 (key Keymap.Input.Delete) in
  Alcotest.(check string) "UX-11 inline modal Home + Delete removes first char"
    "bc" (cur_val m_m6);
  let m_m7, _ = step m_m6 (key Keymap.Input.End) in
  let m_m8, _ = step m_m7 (char_key ~ctrl:true "u") in
  Alcotest.(check string) "UX-11 inline modal End + Ctrl+U clears field" ""
    (cur_val m_m8);

  (* UX-12: Settings 2-step Esc confirm on dirty_count > 0, per-target dirty preservation, Ack_editor_saved clears dirty *)
  let m_set0, _ = Update_nav.open_global_settings m_fleet in
  let dirty_cfg =
    Config_store.stage_patch ~full_key:"runtime.timeout"
      (Wire_config.Set_int { table = "runtime"; key = "timeout"; value = 99 })
      m_set0.config
  in
  let m_set_dirty = { m_set0 with config = dirty_cfg } in
  let m_esc1, _ = step m_set_dirty (key Keymap.Input.Escape) in
  Alcotest.(check bool) "UX-12 first Esc arms discard confirm & keeps Settings open"
    true
    (m_esc1.config.discard_confirm_armed
    && Option.is_some m_esc1.nav.overlay
    && Config_store.dirty_count m_esc1.config = 1);
  let m_esc2, _ = step m_esc1 (key Keymap.Input.Escape) in
  Alcotest.(check bool) "UX-12 second Esc discards dirty & closes Settings" true
    ((not m_esc2.config.discard_confirm_armed)
    && Option.is_none m_esc2.nav.overlay
    && Config_store.dirty_count m_esc2.config = 0);
  let cfg_sw =
    dirty_cfg
    |> Config_store.set_target (Wire_config.Target_keeper "alpha")
    |> Config_store.set_target Wire_config.Target_runtime
  in
  Alcotest.(check int) "UX-12 set_target preserves per-target dirty_fields" 1
    (Config_store.dirty_count cfg_sw);
  let m_ed_saved, _ =
    Update.step ~now:t0 m_set_dirty
      (Msg.Http_reply
         {
           epoch = m_set_dirty.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "Saved in $EDITOR";
                 ack_scope = Msg.Ack_editor_saved;
                 for_modal = None;
                 result = Ok ();
               };
         })
  in
  Alcotest.(check int) "UX-12 Ack_editor_saved clears stale dirty_fields" 0
    (Config_store.dirty_count m_ed_saved.config);

  (* UX-13: Leading @mention switches keeper, @none opens Palette_keepers, multiline Up/Down, no __default__ ghost count *)
  let m_comp_none =
    {
      m_base with
      drafts =
        m_base.drafts |> Drafts.set_focus true |> Drafts.set_current_text "hello";
    }
  in
  let m_no_keeper, _ = step m_comp_none (key Keymap.Input.Enter) in
  Alcotest.(check bool) "UX-13 submit with no target keeper opens Palette_keepers"
    true
    (Option.equal Nav.equal_overlay m_no_keeper.nav.overlay (Some Nav.Palette)
    && Model.equal_palette_mode m_no_keeper.palette.mode Model.Palette_keepers);
  let m_mention =
    {
      m_fleet with
      drafts =
        m_fleet.drafts
        |> Drafts.set_active_keeper "alpha"
        |> Drafts.set_focus true
        |> Drafts.set_current_text "@be";
    }
  in
  let m_mention_done =
    match Update_nav.resolve_composer_popup m_mention with
    | Update_nav.Composer_popup_mention { items = cand :: _; _ } ->
        Update_nav.apply_popup_completion cand m_mention
    | _ -> m_mention
  in
  Alcotest.(check (option string))
    "UX-13 leading @mention switches active_keeper to beta" (Some "beta")
    m_mention_done.drafts.active_keeper;
  let d_ml =
    Drafts.empty
    |> Drafts.set_active_keeper "alpha"
    |> Drafts.set_current_text "line1\nline2"
    |> Drafts.move_cursor_vertical `Up
  in
  Alcotest.(check bool) "UX-13 multiline Up moves cursor to line 1" true
    ((Drafts.current_draft d_ml).cursor <= 5);
  let d_ghost =
    Drafts.empty
    |> Drafts.set_current_text "pre-keeper"
    |> Drafts.set_active_keeper "alpha"
  in
  Alcotest.(check int) "UX-13 other_keepers_draft_count excludes __default__" 0
    (Drafts.other_keepers_draft_count d_ghost);
  let m_mention_send =
    {
      m_fleet with
      drafts =
        m_fleet.drafts
        |> Drafts.set_active_keeper "beta"
        |> Drafts.set_current_text "beta draft 한글"
        |> Drafts.set_active_keeper "alpha"
        |> Drafts.set_focus true
        |> Drafts.set_current_text "@beta hi";
    }
  in
  let m_mention_sent, _ = step m_mention_send (key Keymap.Input.Enter) in
  Alcotest.(check bool) "UX-13 @beta hi queues body hi for beta" true
    (List.exists
       (fun (tx : Drafts.pending_message) ->
         String.equal tx.keeper "beta" && String.equal tx.body "hi")
       m_mention_sent.drafts.pending_txs);
  Alcotest.(check string) "UX-13 @beta hi keeps beta's earlier unsent draft"
    "beta draft 한글"
    (Drafts.draft_for ~keeper:"beta" m_mention_sent.drafts).text;
  Alcotest.(check string) "UX-13 @beta hi clears alpha's composer text" ""
    (Drafts.draft_for ~keeper:"alpha" m_mention_sent.drafts).text;
  (* Mentioning the Keeper whose composer holds the text: the sent text must not
     come back into the composer. *)
  let m_self_mention =
    {
      m_fleet with
      drafts =
        m_fleet.drafts
        |> Drafts.set_active_keeper "alpha"
        |> Drafts.set_focus true
        |> Drafts.set_current_text "@alpha hi";
    }
  in
  let m_self_sent, _ = step m_self_mention (key Keymap.Input.Enter) in
  Alcotest.(check bool) "UX-13 @alpha hi from alpha queues body hi for alpha" true
    (List.exists
       (fun (tx : Drafts.pending_message) ->
         String.equal tx.keeper "alpha" && String.equal tx.body "hi")
       m_self_sent.drafts.pending_txs);
  Alcotest.(check string) "UX-13 @alpha hi from alpha empties alpha's composer" ""
    (Drafts.draft_for ~keeper:"alpha" m_self_sent.drafts).text;
  (* Nested mention: beta's earlier draft goes back into beta's own slot, not
     into gamma's, and the message reaches gamma. *)
  let k_gamma = grouped_keeper ~group:"org-a" "gamma" in
  let m_fleet3 =
    {
      m_fleet with
      fleet =
        Fleet_store.apply_keepers ~observed_at:t0 [ k_alpha; k_beta; k_gamma ]
          m_fleet.fleet;
    }
  in
  let m_nested_mention =
    {
      m_fleet3 with
      drafts =
        m_fleet3.drafts
        |> Drafts.set_active_keeper "beta"
        |> Drafts.set_current_text "beta draft"
        |> Drafts.set_active_keeper "alpha"
        |> Drafts.set_focus true
        |> Drafts.set_current_text "@beta @gamma hi";
    }
  in
  let m_nested_sent, _ = step m_nested_mention (key Keymap.Input.Enter) in
  Alcotest.(check bool) "UX-13 @beta @gamma hi queues body hi for gamma" true
    (List.exists
       (fun (tx : Drafts.pending_message) ->
         String.equal tx.keeper "gamma" && String.equal tx.body "hi")
       m_nested_sent.drafts.pending_txs);
  Alcotest.(check string)
    "UX-13 @beta @gamma hi keeps beta's earlier draft in beta's slot"
    "beta draft"
    (Drafts.draft_for ~keeper:"beta" m_nested_sent.drafts).text;
  Alcotest.(check string) "UX-13 @beta @gamma hi leaves gamma's slot empty" ""
    (Drafts.draft_for ~keeper:"gamma" m_nested_sent.drafts).text;

  (* UX-14: Inline modal field help lookup populated *)
  Alcotest.(check bool) "UX-14 modal_field_help returns help for memory_act" true
    (Option.is_some (Model.modal_field_help ~key:"memory_act"));

  (* UX-15: /btw scroll, copy y, and Enter-close when answered *)
  let long_reply =
    String.concat "\n" (List.init 40 (fun i -> Printf.sprintf "line %d" i))
  in
  let m_btw0, _ = Update_nav.open_inline_modal m_fleet Nav.Btw_query in
  let m_btw_ans =
    {
      m_btw0 with
