      ~summary:(Say.literal "err") ~detail:"detail" ~status:Health.Resolved
      m_fleet.incidents
  in
  let m_inc, _ =
    Update_nav.open_overlay { m_fleet with incidents = inc0 } Nav.Incidents
  in
