  Alcotest.(check bool) "UX-19 Incidents first c arms confirm without clearing"
    true
    (m_inc_c1.incidents.clear_confirm_armed
    && Incidents.count m_inc_c1.incidents = 1);
  let m_inc_c2, _ = step m_inc_c1 (char_key "c") in
