let test_freeze_fixes_epoch_locks_micro_inline_and_cut_reply () =
  let t0 = Clock.Mono.of_ns 50_000_000_000L in
  let key k =
    Msg.Key_event
      {
        Keymap.Input.key = k;
        mods = { ctrl = false; alt = false; shift = false };
      }
  in
  let char_key ?(ctrl = false) s =
    Msg.Key_event
      {
        Keymap.Input.key = Keymap.Input.Char s;
        mods = { ctrl; alt = false; shift = false };
      }
  in
  let sample_tool_approval : Wire_work.held_tool_approval =
    {
      approval_id = "ta-lock-1";
      tool_call_id = "tc-1";
      keeper = "alpha";
      tool = "bash";
      args_preview = "ls";
      question = "Allow bash?";
      because = None;
      asked_at = 1795250000.0;
      timeout_sec = 60.0;
    }
  in
  let sample_ask : Wire_work.ask_row =
    {
      ask_id = "ask-lock-1";
      keeper = "alpha";
      asked_at = 1795250001.0;
      context = Some "Need decision";
      questions =
        [
          {
            question_id = "q1";
            header = "Confirm";
            prompt = "Proceed?";
            mode = Wire_work.Ask_single;
            allow_free_text = true;
            free_text_hint = None;
            choices =
              [ { choice_id = "yes"; label = "Yes"; description = None } ];
          };
        ];
      resolution = Wire_work.Ask_open;
    }
  in
  let base_attention =
    Attention.empty
    |> Attention.rebuild ~asks:[ sample_ask ]
         ~tool_approvals:[ sample_tool_approval ] ~gate_pending:[] ~goals:[]
    |> Attention.mark_in_flight ~id:"tool:ta-lock-1"
    |> Attention.mark_in_flight ~id:"ask:ask-lock-1"
  in
  let locked_inline_modal =
    {
      (Model.inline_modal_for (Nav.Board_comment { post_id = "p1"; parent_id = None })) with
      submitting = true;
    }
  in
  let locked_ask_modal =
    { (Model.ask_modal_for sample_ask) with submitting = true }
  in
  let locked_config =
    Config_store.empty
    |> Config_store.mark_dry_run_loading
    |> Config_store.mark_save_in_flight
  in
  let locked_runtime =
    Runtime_store.empty |> Runtime_store.set_fusion_submitting true
  in
  let locked_kc =
    Keeper_context_store.empty
    |> Keeper_context_store.start_github_login ~keeper:"alpha"
  in
  let locked_knowledge =
    let diag : Knowledge_store.memory_diagram_state =
      {
        request_id = 1;
        keeper = "alpha";
        event_identity = "ev-1";
        source = Knowledge_store.Diagram_source_event "ev-1";
        revision = 1;
        kind = Knowledge_store.Diagram_pele_card;
        mode = Knowledge_store.Diagram_mode_auto;
        payload = Observed.loading ~since_ns:t0;
        scroll = 0;
        copy_source = "";
      }
    in
    Knowledge_store.empty
    |> Knowledge_store.open_memory_diagram diag
    |> Knowledge_store.request_wiki_edit ~slug:"guide"
    |> Knowledge_store.set_pending_artifact_revision (Some ("art-1", Some 2))
  in
  let m_locked =
    let m0 = Model.initial ~cols:120 ~rows:40 () in
    {
      m0 with
      attention = base_attention;
      inline_modal = Some locked_inline_modal;
      ask_modal = Some locked_ask_modal;
      nav =
        {
          m0.nav with
          overlay =
            Some
              (Nav.Inline_action
                 (Nav.Board_comment { post_id = "p1"; parent_id = None }));
        };
      config = locked_config;
      knowledge = locked_knowledge;
      runtime = locked_runtime;
      keeper_context = locked_kc;
    }
  in
  let check_locks_cleared ~label ~expect_modals_closed (m : Model.t) cmds =
    Alcotest.(check bool) (label ^ ": epoch bumped") true
      (not (Epoch.equal m.epoch m_locked.epoch));
    Alcotest.(check int) (label ^ ": attention in_flight_ids cleared") 0
      (List.length m.attention.in_flight_ids);
    Alcotest.(check bool) (label ^ ": tool approval actionable again") true
      (Option.is_some (Attention.top_fast_path m.attention));
    (if expect_modals_closed then begin
       Alcotest.(check bool) (label ^ ": inline_modal closed") true
         (Option.is_none m.inline_modal);
       Alcotest.(check bool) (label ^ ": ask_modal closed") true
         (Option.is_none m.ask_modal);
       Alcotest.(check bool) (label ^ ": Inline_action overlay cleared") true
         (Option.is_none m.nav.overlay)
     end
     else begin
       Alcotest.(check bool) (label ^ ": inline_modal.submitting reset") true
         (match m.inline_modal with
          | Some modal -> not modal.submitting
          | None -> false);
       Alcotest.(check bool) (label ^ ": ask_modal.submitting reset") true
         (match m.ask_modal with
          | Some modal -> not modal.submitting
          | None -> false)
     end);
    Alcotest.(check bool) (label ^ ": config dry_run reset to idle") true
      (match m.config.dry_run_preview with
       | Config_store.Dry_run_idle -> true
       | _ -> false);
    Alcotest.(check bool) (label ^ ": config save_state reset to idle") true
      (match m.config.save_state with
       | Config_store.Save_idle -> true
       | _ -> false);
    Alcotest.(check bool) (label ^ ": fusion submitting reset") false
      m.runtime.fusion_launch_draft.submitting;
    Alcotest.(check bool) (label ^ ": github_login.running reset") false
      (Keeper_context_store.get_keeper ~keeper:"alpha" m.keeper_context)
        .github_login.running;
    Alcotest.(check bool) (label ^ ": loading memory_diagram cleared") true
      (Option.is_none m.knowledge.memory_diagram);
    Alcotest.(check bool) (label ^ ": Cancel_memory_diagram emitted") true
      (List.exists
         (function Cmd.Cancel_memory_diagram -> true | _ -> false)
         (Cmd.flatten cmds));
    Alcotest.(check bool) (label ^ ": pending_wiki_edit_slug cleared") true
      (Option.is_none m.knowledge.pending_wiki_edit_slug);
    Alcotest.(check bool) (label ^ ": pending_artifact_revision cleared") true
      (Option.is_none m.knowledge.pending_artifact_revision)
  in
  (* P0-3 Path A: 409 Workspace_mismatch *)
  let m_wm, cmds_wm =
    Update.step ~now:t0 m_locked
      (Msg.Http_reply
         {
           epoch = m_locked.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "test";
                 ack_scope = Msg.Ack_toast_only;
                 for_modal = None;
                 result =
                   Error
                     (Msg.Workspace_mismatch
                        {
                          expected_instance = Some "i1";
                          observed_instance = Some "i2";
                          observed_workspace_sha256 = None;
                          message = "changed";
                        });
               };
         })
  in
  check_locks_cleared ~label:"Workspace_mismatch" ~expect_modals_closed:true
    m_wm cmds_wm;
  (* P0-3 Path B: Server_start_result (Ok ()) *)
  let m_srv, cmds_srv =
    Update.step ~now:t0 m_locked (Msg.Server_start_result (Ok ()))
  in
  check_locks_cleared ~label:"Server_start_result" ~expect_modals_closed:false
    m_srv cmds_srv;
  (* P0-3 Path C: Offline 'r' refresh *)
  let m_offline =
    {
      m_locked with
      freshness = { m_locked.freshness with server_offline = true };
      nav = { m_locked.nav with overlay = None };
    }
  in
  let m_ref, cmds_ref = Update.step ~now:t0 m_offline (char_key "r") in
  check_locks_cleared ~label:"Offline refresh" ~expect_modals_closed:false
    m_ref cmds_ref;

  (* P1-7: Micro teleport_blocked opens visible overlay without mutating hidden workspace *)
  let m_micro_tool =
    let m0 = Model.initial ~cols:100 ~rows:20 () in
    let attention =
      Attention.empty
      |> Attention.rebuild ~asks:[] ~tool_approvals:[ sample_tool_approval ]
           ~gate_pending:[] ~goals:[]
    in
    { m0 with attention; nav = { m0.nav with workspace = Nav.Pulse } }
  in
  Alcotest.(check bool) "100x20 is Micro breakpoint" true
    (Model.equal_breakpoint m_micro_tool.breakpoint Model.Micro);
  let m_micro_after_j, _ = Update.step ~now:t0 m_micro_tool (char_key "J") in
  Alcotest.(check bool) "Micro J on tool approval opens Drawer_queue overlay"
    true
    (Option.equal Nav.equal_overlay m_micro_after_j.nav.overlay
       (Some (Nav.Queue_context Nav.Drawer_queue)));
  Alcotest.(check bool) "Micro J preserves hidden workspace" true
    (Nav.equal_workspace m_micro_after_j.nav.workspace Nav.Pulse);
  let m_micro_ask =
    let m0 = Model.initial ~cols:100 ~rows:20 () in
    let attention =
      Attention.empty
      |> Attention.rebuild ~asks:[ sample_ask ] ~tool_approvals:[]
           ~gate_pending:[] ~goals:[]
    in
    { m0 with attention; nav = { m0.nav with workspace = Nav.Pulse } }
  in
  let m_micro_after_j_ask, _ = Update.step ~now:t0 m_micro_ask (char_key "J") in
  Alcotest.(check bool) "Micro J on Pending_ask opens Ask_answer overlay" true
    (Option.equal Nav.equal_overlay m_micro_after_j_ask.nav.overlay
       (Some Nav.Ask_answer));
  Alcotest.(check bool) "Micro J on Ask preserves hidden workspace" true
    (Nav.equal_workspace m_micro_after_j_ask.nav.workspace Nav.Pulse);
  (* P1-7: Enlarging terminal defensively clears System_gate Micro_viewport *)
  let m_gated =
    let m0 = Model.initial ~cols:70 ~rows:20 () in
    {
      m0 with
      nav = { m0.nav with overlay = Some (Nav.System_gate Nav.Micro_viewport) };
    }
  in
  let m_enlarged, _ =
    Update.step ~now:t0 m_gated (Msg.Resize { cols = 100; rows = 30 })
  in
  Alcotest.(check bool) "Resize >= 80x24 clears Micro_viewport overlay" true
    (Option.is_none m_enlarged.nav.overlay);

  (* P2-9: open_overlay initializes inline_modal & orphaned overlay does not trap Esc/Ctrl+Q *)
  let m_open_inl, _ =
    Update_nav.open_overlay (Model.initial ~cols:120 ~rows:40 ())
      (Nav.Inline_action (Nav.Task_cancel "t-9"))
  in
  Alcotest.(check bool) "open_overlay (Inline_action _) populates inline_modal"
    true (Option.is_some m_open_inl.inline_modal);
  let m_orphan =
    let m0 = Model.initial ~cols:120 ~rows:40 () in
    {
      m0 with
      nav =
        {
          m0.nav with
          overlay = Some (Nav.Inline_action (Nav.Task_cancel "t-9"));
        };
      inline_modal = None;
    }
  in
  let m_orphan_esc, _ =
    Update.step ~now:t0 m_orphan (key Keymap.Input.Escape)
  in
  Alcotest.(check bool) "Esc clears orphaned Inline_action overlay" true
    (Option.is_none m_orphan_esc.nav.overlay);
  let quit_emitted cmds =
    List.exists (function Cmd.Quit _ -> true | _ -> false) (Cmd.flatten cmds)
  in
  let m_orphan_quit, cmds_orphan_quit =
    Update.step ~now:t0 m_orphan (char_key ~ctrl:true "q")
  in
  Alcotest.(check bool)
    "1st Ctrl+Q clears the orphan overlay and arms quit without exiting" true
    (Option.is_none m_orphan_quit.nav.overlay
     && Option.is_some m_orphan_quit.quit_armed_at
     && not (quit_emitted cmds_orphan_quit));
  let _, cmds_orphan_quit2 =
    Update.step ~now:t0 m_orphan_quit (char_key ~ctrl:true "q")
  in
  Alcotest.(check bool)
    "2nd Ctrl+Q after the orphan overlay was cleared emits Quit" true
    (quit_emitted cmds_orphan_quit2);
  (* P2-9 in Micro breakpoint: the first Ctrl+Q clears the orphaned
     Inline_action and arms quit, the second one quits *)
  let m_micro_orphan =
    let m0 = Model.initial ~cols:100 ~rows:20 () in
    {
      m0 with
      nav =
        {
          m0.nav with
          overlay = Some (Nav.Inline_action (Nav.Task_cancel "t-9"));
        };
      inline_modal = None;
    }
  in
  let m_micro_orphan_quit, cmds_micro_orphan_quit =
    Update.step ~now:t0 m_micro_orphan (char_key ~ctrl:true "q")
  in
  Alcotest.(check bool)
    "Micro orphaned Inline_action: 1st Ctrl+Q clears it and arms quit" true
    (Option.is_none m_micro_orphan_quit.nav.overlay
     && Option.is_some m_micro_orphan_quit.quit_armed_at
     && not (quit_emitted cmds_micro_orphan_quit));
  let _, cmds_micro_orphan_quit2 =
    Update.step ~now:t0 m_micro_orphan_quit (char_key ~ctrl:true "q")
  in
  Alcotest.(check bool)
    "Micro orphaned Inline_action: 2nd Ctrl+Q emits Quit" true
    (quit_emitted cmds_micro_orphan_quit2);

  (* P2-10: Duplicate Enter on submitting inline modal + scoped Reply_action_ack *)
  let m_comment, _ =
    Update_nav.open_inline_modal (Model.initial ~cols:120 ~rows:40 ())
      (Nav.Board_comment { post_id = "p-10"; parent_id = None })
  in
  let m_comment, _ = Update.step ~now:t0 m_comment (char_key "h") in
  let m_comment, _ = Update.step ~now:t0 m_comment (char_key "i") in
  (* Background Reply_action_ack while user is typing (submitting = false) must NOT close modal *)
  let m_comment_after_bg, _ =
    Update.step ~now:t0 m_comment
      (Msg.Http_reply
         {
           epoch = m_comment.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "copied";
                 ack_scope = Msg.Ack_toast_only;
                 for_modal = None;
                 result = Ok ();
               };
         })
  in
  Alcotest.(check bool) "background ack preserves open non-submitting inline_modal"
    true
    (Option.is_some m_comment_after_bg.inline_modal
     && Option.is_some m_comment_after_bg.nav.overlay);
  let m_comment_after_bg_err, _ =
    Update.step ~now:t0 m_comment_after_bg
      (Msg.Http_reply
         {
           epoch = m_comment_after_bg.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "bg err";
                 ack_scope = Msg.Ack_toast_only;
                 for_modal = None;
                 result = Error (Msg.Transport (Health.Other_io "unrelated"));
               };
         })
  in
  Alcotest.(check bool)
    "background error ack does not overwrite non-submitting modal.error" true
    (match m_comment_after_bg_err.inline_modal with
     | Some modal -> Option.is_none modal.error
     | None -> false);
  (* Submit once -> emits Post_board_comment & marks submitting = true *)
  let m_sub1, cmds_sub1 =
    Update.step ~now:t0 m_comment_after_bg (key Keymap.Input.Enter)
  in
  Alcotest.(check int) "first Enter emits 1 Post_board_comment" 1
    (List.length
       (List.filter
          (function
            | Cmd.Http_post { req = Cmd.Post_board_comment _; _ } -> true
            | _ -> false)
          (Cmd.flatten cmds_sub1)));
  (* Second Enter while submitting -> NO duplicate POST *)
  let m_sub2, cmds_sub2 =
    Update.step ~now:t0 m_sub1 (key Keymap.Input.Enter)
  in
  Alcotest.(check int) "second Enter while submitting emits 0 commands" 0
    (List.length (Cmd.flatten cmds_sub2));
  (* Background Reply_action_ack (Ok & Error, for_modal=None or mismatched) while
     Board_comment is submitting MUST NOT close or unlock it! *)
  let m_sub_bg_ok, _ =
    Update.step ~now:t0 m_sub2
      (Msg.Http_reply
         {
           epoch = m_sub2.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "copied";
                 ack_scope = Msg.Ack_toast_only;
                 for_modal = None;
                 result = Ok ();
               };
         })
  in
  Alcotest.(check bool)
    "background Ok ack (for_modal=None) does NOT close submitting Board_comment"
    true
    (match m_sub_bg_ok.inline_modal with
     | Some modal -> modal.submitting && Option.is_some m_sub_bg_ok.nav.overlay
     | None -> false);
  let m_sub_bg_err, _ =
    Update.step ~now:t0 m_sub_bg_ok
      (Msg.Http_reply
         {
           epoch = m_sub_bg_ok.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "bg err";
                 ack_scope = Msg.Ack_toast_only;
                 for_modal = None;
                 result = Error (Msg.Transport (Health.Other_io "unrelated"));
               };
         })
  in
  Alcotest.(check bool)
    "background Error ack (for_modal=None) does NOT unlock submitting Board_comment"
    true
    (match m_sub_bg_err.inline_modal with
     | Some modal -> modal.submitting && Option.is_none modal.error
     | None -> false);
  let m_sub_other_modal, _ =
    Update.step ~now:t0 m_sub_bg_err
      (Msg.Http_reply
         {
           epoch = m_sub_bg_err.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "sched";
                 ack_scope = Msg.Ack_close_modal_and_refresh;
                 for_modal = Some Nav.Schedule_form;
                 result = Ok ();
               };
         })
  in
  Alcotest.(check bool)
    "mismatched for_modal ack does NOT close submitting Board_comment" true
    (match m_sub_other_modal.inline_modal with
     | Some modal -> modal.submitting
     | None -> false);
  (* Matching Reply_board_comment closes Board_comment cleanly *)
  let m_comment_closed, _ =
    Update.step ~now:t0 m_sub_other_modal
      (Msg.Http_reply
         {
           epoch = m_sub_other_modal.epoch;
           reply = Msg.Reply_board_comment { post_id = "p-10"; result = Ok () };
         })
  in
  Alcotest.(check bool)
    "matching Reply_board_comment closes submitting Board_comment" true
    (Option.is_none m_comment_closed.inline_modal
     && Option.is_none m_comment_closed.nav.overlay);
  (* Reply_action_ack-backed modal (Task_cancel "t-10"): only matching for_modal
     unlocks on Error or closes on Ok! *)
  let m_tc0 =
    let m0 = Model.initial ~cols:120 ~rows:40 () in
    let m_open, _ = Update_nav.open_inline_modal m0 (Nav.Task_cancel "t-10") in
    {
      m_open with
      inline_modal =
        Option.map
          (fun (md : Model.inline_modal_state) -> { md with submitting = true })
          m_open.inline_modal;
    }
  in
  let m_tc_bg_ok, _ =
    Update.step ~now:t0 m_tc0
      (Msg.Http_reply
         {
           epoch = m_tc0.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "bg";
                 ack_scope = Msg.Ack_close_modal_and_refresh;
                 for_modal = None;
                 result = Ok ();
               };
         })
  in
  Alcotest.(check bool)
    "for_modal=None Ok does NOT close submitting Task_cancel" true
    (match m_tc_bg_ok.inline_modal with Some md -> md.submitting | None -> false);
  let m_tc_wrong_id, _ =
    Update.step ~now:t0 m_tc_bg_ok
      (Msg.Http_reply
         {
           epoch = m_tc_bg_ok.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "other";
                 ack_scope = Msg.Ack_close_modal_and_refresh;
                 for_modal = Some (Nav.Task_cancel "t-other");
                 result = Ok ();
               };
         })
  in
  Alcotest.(check bool)
    "mismatched Task_cancel id does NOT close submitting Task_cancel" true
    (match m_tc_wrong_id.inline_modal with
     | Some md -> md.submitting
     | None -> false);
  let m_tc_err, _ =
    Update.step ~now:t0 m_tc_wrong_id
      (Msg.Http_reply
         {
           epoch = m_tc_wrong_id.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "cancel failed";
                 ack_scope = Msg.Ack_close_modal_and_refresh;
                 for_modal = Some (Nav.Task_cancel "t-10");
                 result = Error (Msg.Transport (Health.Other_io "boom"));
               };
         })
  in
  Alcotest.(check bool)
    "matching Task_cancel Error unlocks submitting and sets error" true
    (match m_tc_err.inline_modal with
     | Some md -> (not md.submitting) && Option.is_some md.error
     | None -> false);
  let m_tc_resub =
    {
      m_tc_err with
      inline_modal =
        Option.map
          (fun (md : Model.inline_modal_state) -> { md with submitting = true })
          m_tc_err.inline_modal;
    }
  in
  let m_tc_closed, _ =
    Update.step ~now:t0 m_tc_resub
      (Msg.Http_reply
         {
           epoch = m_tc_resub.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.literal "cancelled";
                 ack_scope = Msg.Ack_close_modal_and_refresh;
                 for_modal = Some (Nav.Task_cancel "t-10");
                 result = Ok ();
               };
         })
  in
  Alcotest.(check bool)
    "matching Task_cancel Ok closes inline_modal & overlay" true
    (Option.is_none m_tc_closed.inline_modal
     && Option.is_none m_tc_closed.nav.overlay);

  (* P2-11: Cut_reply cursor-progress guard & max-page cap *)
  let c1 : Wire_chat_journal.cursor = { last_seq = 5; next_offset = 100 } in
  let page1 : Wire_chat_journal.page =
    {
      events =
        [
          Wire_chat_journal.Text_delta
            { text = "hi"; owner = Wire_chat_journal.Unobserved_scope None };
        ];
      next = Some c1;
    }
  in
  let cut1 =
    match Cut_reply.apply_page_checked page1 Cut_reply.start with
    | Ok c -> c
    | Error err -> Alcotest.fail (Cut_reply.page_error_to_string err)
  in
  (match Cut_reply.apply_page_checked { events = []; next = Some c1 } cut1 with
   | Error (Cut_reply.Cursor_did_not_advance _) -> ()
   | Ok _ -> Alcotest.fail "repeated cursor must be rejected"
   | Error err -> Alcotest.fail (Cut_reply.page_error_to_string err));
  (* Through Update.step: repeated cursor stops emitting Get_chat_operation_events
     and marks slot as non-retryable Observed.Failed *)
  let m_cut0 = Model.initial ~cols:120 ~rows:40 () in
  let m_cut1, cmds_cut1 =
    Update.step ~now:t0 m_cut0
      (Msg.Http_reply
         {
           epoch = m_cut0.epoch;
           reply =
             Msg.Reply_chat_operation_events
               {
                 keeper = "alpha";
                 operation_id = "op-loop";
                 from = Wire_chat_journal.From_start;
                 result = Ok page1;
               };
         })
  in
  Alcotest.(check bool) "advancing page 1 requests After c1" true
    (List.exists
       (function
         | Cmd.Http_get
             {
               req =
                 Cmd.Get_chat_operation_events
                   { from = Wire_chat_journal.After c; _ };
               _;
             } ->
             c.last_seq = 5 && c.next_offset = 100
         | _ -> false)
       (Cmd.flatten cmds_cut1));
  let m_cut2, cmds_cut2 =
    Update.step ~now:t0 m_cut1
      (Msg.Http_reply
         {
           epoch = m_cut1.epoch;
           reply =
             Msg.Reply_chat_operation_events
               {
                 keeper = "alpha";
                 operation_id = "op-loop";
                 from = Wire_chat_journal.After c1;
                 result = Ok { events = []; next = Some c1 };
               };
         })
  in
  Alcotest.(check int) "repeated cursor stops HTTP loop (0 cmds)" 0
    (List.length (Cmd.flatten cmds_cut2));
  Alcotest.(check bool) "repeated cursor marks slot Failed non-retryable" true
    (match
       Fleet_store.cut_reply_for ~keeper:"alpha" ~operation_id:"op-loop"
         m_cut2.fleet
     with
     | Observed.Failed { retryable = false; _ } -> true
     | _ -> false);
  (* Page cap (max_pages = 100) *)
  let rec feed_pages n cut =
    let page : Wire_chat_journal.page =
      {
        events = [];
        next = Some { last_seq = n; next_offset = n * 10 };
      }
    in
    match Cut_reply.apply_page_checked page cut with
    | Ok next ->
        if n > Cut_reply.max_pages + 5 then
          Alcotest.fail "expected Page_limit_exceeded"
        else feed_pages (n + 1) next
    | Error (Cut_reply.Page_limit_exceeded { max_pages }) ->
        Alcotest.(check int) "capped at Cut_reply.max_pages" Cut_reply.max_pages
          max_pages;
        Alcotest.(check int) "stopped on page 100" Cut_reply.max_pages n
    | Error err -> Alcotest.fail (Cut_reply.page_error_to_string err)
  in
  feed_pages 1 Cut_reply.start

let test_keeper_board_quarantine_recovery () =
  let module Q = Board_quarantine in
  let keeper = "alpha" in
  let base = Model.initial () in
  let m = { base with nav = { base.nav with workspace = Nav.Keepers; sidebar_focused = false;
            dive_stack = [Nav.Dive_keeper { name = keeper; tab = Nav.Keeper_work_candle }] } } in
  let act model key = Update.execute_action ~now:t1 model key in
  let reply (m : Model.t) response =
    Update.step ~now:t2 m (Msg.Http_reply { epoch = m.epoch; reply = response }) in
  let read cmds =
    match List.filter_map (function
      | Cmd.Http_get { req = Cmd.Get_board_quarantines { keeper; generation } as req; _ } ->
          Some (keeper, generation, Cmd.get_request_path req)
      | _ -> None) (Cmd.flatten cmds) with
    | [result] -> result
    | _ -> Alcotest.fail "expected one scoped Board inventory GET" in
  let item name id : Q.inventory_item =
    { keeper_name = name; partition_id = "partition-" ^ id; candidate_id = id;
      quarantine_id = "generation-" ^ id; phase = Q.Inventory_quarantined;
      failure_category = Q.Exact_lane_exhausted; attempt_provenance = None;
      quarantined_at = 1.; requested_at = None; requeued_at = None; requested_by = None } in
  let a = item keeper "A" and b = item keeper "B" in
  let inventory ?(errors = []) items = { Q.items; errors } in
  let observe model generation result =
    reply model (Msg.Reply_board_quarantines { keeper; generation; result }) |> fst in
  let action model = act model Keymap.Context_primary_action in
  let posts cmds = List.filter_map (function
    | Cmd.Http_post { req = Cmd.Post_board_recovery item as req; _ } -> Some (item, req)
    | _ -> None) (Cmd.flatten cmds) in
  let m, cmds = act m Keymap.Cycle_view_mode in
  let who, first, path = read cmds in
  Alcotest.(check (pair string string)) "selected Keeper inventory route"
    (keeper, "/api/v1/keepers/alpha/board-attention/quarantines") (who, path);
  let forbidden = Msg.Http_error { status = 403; body = "forbidden"; api_error = None } in
  let failed = observe m first (Error forbidden) in
  Alcotest.(check int) "unreadable inventory never submits" 0 (List.length (posts (snd (action failed))));
  let partial = observe m first (Ok (inventory ~errors:[{ Q.keeper_name = keeper;
                           kind = Q.Inventory_partition_ledger_unavailable }] [a; b])) in
  Alcotest.(check int) "partial ledger cannot authorize the mutation" 0 (List.length (posts (snd (action partial))));
  let m = observe m first (Ok (inventory [a; b])) in
  let force model = reply model (Msg.Reply_action_ack { label = Say.literal "refresh";
    ack_scope = Msg.Ack_refresh_view; for_modal = None; result = Ok () }) in
  let refreshing, forced = force m in
  let _, auto_generation, _ = read forced in
  Alcotest.(check bool) "background refresh reserves a new read before another action" true
    (auto_generation > first && posts (snd (action refreshing)) = []);
  let _, duplicate = force refreshing in
  Alcotest.(check bool) "a second background refresh shares the pending read" false
    (List.mem (Cmd.Http_get { epoch = m.epoch; req = Cmd.Get_board_quarantines { keeper; generation = auto_generation } })
       (Cmd.flatten duplicate));
  let m, _ = act m (Keymap.Move Keymap.Down) in
  let m, cmds = act m Keymap.Refresh in
  let _, second, _ = read cmds in
  let m = observe m second (Ok (inventory [b; a])) in
  let m = observe m first (Ok (inventory [a])) in
  let pending, cmds = action m in
  let target, req = match posts cmds with [one] -> one | _ -> Alcotest.fail "expected one CAS" in
  Alcotest.(check string) "selection follows the exact candidate after reordering" b.candidate_id target.candidate_id;
  Alcotest.(check string) "partition from that candidate" "/api/v1/keepers/alpha/board-attention/quarantines/partition-B/recovery" (Cmd.post_request_path req);
  Alcotest.(check bool) "producer request includes schema and expected generation"
    true (Cmd.post_request_body req = Q.request_to_json { candidate_id = "B"; expected_quarantine_id = b.quarantine_id;
                                                         decision = Acknowledge_and_requeue });
  Alcotest.(check int) "in-flight action is not submitted twice" 0 (List.length (posts (snd (action pending))));
  let check_readback err outcome =
    let model, gets = reply pending (Msg.Reply_board_recovery { item = b; result = err }) in
    let who, generation, _ = read gets in
    Alcotest.(check string) "the sent Keeper is read again" keeper who;
    let new_generation = { b with quarantine_id = "different-generation"; phase = Q.Inventory_quarantined } in
    let model = observe model generation (Ok (inventory [new_generation; a])) in
    let row = Board_recovery.entry ~keeper model.knowledge.board_recovery in
    Alcotest.(check bool) "outcome stays tied to the old generation" true
      (match row.command with Board_recovery.Result (actual, actual_outcome) ->
            Q.same_candidate actual b && outcome actual_outcome | _ -> false);
    Alcotest.(check int) "new generation must be selected explicitly" 0 (List.length (posts (snd (action model)))) in
  check_readback (Error forbidden) (function Board_recovery.Rejected _ -> true | _ -> false);
  check_readback (Error (Msg.Http_error { status = 409; body = "stale"; api_error = None }))
    (function Board_recovery.Unconfirmed _ -> true | _ -> false);
  check_readback (Error (Msg.Decode_error "quarantine tuple mismatch"))
    (function Board_recovery.Unconfirmed _ -> true | _ -> false);
  check_readback (Error (Msg.Transport (Health.Other_io "connection closed")))
    (function Board_recovery.Unconfirmed _ -> true | _ -> false);
  let switched, _ = Update.step ~now:t2 pending (Msg.Server_start_result (Ok ())) in
  let receipt : Q.recovery_receipt = { wake = Q.Not_registered; audit = Q.Recording_failed } in
  let success = Msg.Reply_board_recovery { item = b; result = Ok receipt } in
  let switched, late_cmds = Update.step ~now:t2 switched (Msg.Http_reply { epoch = pending.epoch; reply = success }) in
  let old = Board_recovery.entry ~keeper switched.knowledge.board_recovery in
  Alcotest.(check bool) "old workspace selection, receipt and read-back are discarded" true
    (old.command = Board_recovery.Idle && old.selected = None && late_cmds = []);
  let accepted, gets = reply pending success in
  let _, generation, _ = read gets in
  let complete = { b with phase = Q.Inventory_requeued } in
  let accepted = observe accepted generation (Ok (inventory [a; complete])) in
  let entry = Board_recovery.entry ~keeper accepted.knowledge.board_recovery in
  Alcotest.(check bool) "receipt preserves the wake and audit outcomes after read-back" true
    (entry.command = Board_recovery.Result (b, Board_recovery.Accepted receipt));
  Alcotest.(check bool) "completed exact generation cannot be requeued again" true
    (Board_recovery.actionable entry = None && Board_recovery.selection_index entry = Some 1);
  Alcotest.(check bool) "an inventory returned for another Keeper is rejected" true
    (Result.is_error (Q.inventory_of_json ~keeper (Q.inventory_to_json (inventory [item "beta" "A"]))))

let test_ux_sweep_12_fixes () =
  let t0 = Clock.Mono.of_ns 10_000_000_000L in
  let step_at ~now m k = Update.step ~now m (Msg.Key_event k) in
  let step m k = step_at ~now:t0 m k in
  let mk_key ?(ctrl = false) ?(alt = false) ?(shift = false) k =
    { Keymap.Input.key = k; mods = { ctrl; alt; shift } }
  in
  let char_k ?(ctrl = false) ?(alt = false) ?(shift = false) c =
    mk_key ~ctrl ~alt ~shift (Keymap.Input.Char c)
  in
  let has_cmd pred cmds =
    List.exists pred (Cmd.flatten cmds)
  in
  let ws_id : Wire_common.workspace_identity =
    {
      instance_id = Some "inst-1";
      base_path = "/tmp/ws";
      masc_root = "/tmp/ws/.masc";
      workspace_sha256 =
        Some "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    }
  in
  let base_with_ws =
    let m0 = Model.initial ~cols:150 ~rows:42 () in
    {
      m0 with
      server_identity =
        {
          m0.server_identity with
          workspace = Some ws_id;
          observer_instance_id = Some "inst-1";
        };
    }
  in

  (* === 1. Pulse Human Attention selection truthfulness (Y/N/J/Enter) === *)
  let ta0 : Wire_work.held_tool_approval =
    {
      approval_id = "ta-0";
      tool_call_id = "tc-0";
      keeper = "alpha";
      tool = "bash";
      args_preview = "ls";
      question = "Allow ls?";
      because = None;
      asked_at = 100.0;
      timeout_sec = 60.0;
    }
  in
  let ask1 : Wire_work.ask_row =
    {
      ask_id = "ask-1";
      keeper = "beta";
      context = Some "ctx";
      asked_at = 200.0;
      questions =
        [
          {
            question_id = "q1";
            header = "Choice";
            prompt = "Choose approach";
            choices =
              [
                { choice_id = "c1"; label = "Option A"; description = None };
                { choice_id = "c2"; label = "Option B"; description = None };
              ];
            mode = Wire_work.Ask_single;
            allow_free_text = true;
            free_text_hint = None;
          };
        ];
      resolution = Wire_work.Ask_open;
    }
  in
  let goal2 : Wire_work.goal =
    {
      id = "goal-2";
      title = "Ship feature";
      measure = "Tests pass";
      procedure = "Run dune";
      priority = 1;
      phase = Wire_work.Awaiting_confirmation;
      due_date = None;
      created_at = Some "2026-01-01T00:00:00Z";
      updated_at = Some "2026-01-02T00:00:00Z";
      criterion_verdict = Wire_work.Criterion_valid;
      criterion_revision = Some "rev-1";
      last_review_note = None;
      last_review_at = None;
      linked_task_count = Observed.value ~observed_at:t0 0;
    }
  in
  let m_pulse =
    let work =
      base_with_ws.work
      |> Work_store.apply_tool_approvals ~observed_at:t0 [ ta0 ]
      |> Work_store.apply_asks ~observed_at:t0 [ ask1 ]
      |> Work_store.apply_planning ~observed_at:t0
           { goals = [ goal2 ]; tasks = [] }
    in
    Model.rebuild_attention { base_with_ws with work }
  in
  (* Move cursor to row 1 (ask-1) *)
  let m_p1, _ = step m_pulse (mk_key Keymap.Input.Down) in
  Alcotest.(check bool) "Item 1: strip shows exact selected row 1 (ask-1)" true
    (match Model.fast_approval_strip_item m_p1 with
     | Some { payload = Attention.Payload_ask a; _ } -> String.equal a.ask_id "ask-1"
     | _ -> false);
  let m_p1_y, cmds_p1_y = step m_p1 (char_k ~shift:true "Y") in
  Alcotest.(check bool) "Item 1: Y on selected ask-1 opens Ask_answer (never approves ta-0)"
    true
    (Option.equal Nav.equal_overlay m_p1_y.nav.overlay (Some Nav.Ask_answer)
     && (match m_p1_y.ask_modal with
         | Some am -> String.equal am.ask.ask_id "ask-1"
         | None -> false)
     && not
          (has_cmd
             (function
               | Cmd.Http_post { req = Cmd.Post_tool_approval _; _ } -> true
               | _ -> false)
             cmds_p1_y));
  let _, cmds_p1_n = step m_p1 (char_k ~shift:true "N") in
  Alcotest.(check bool) "Item 1: N on selected ask-1 skips ask-1" true
    (has_cmd
       (function
         | Cmd.Http_post { req = Cmd.Post_ask_answer { ask_id = "ask-1"; _ }; _ } -> true
         | _ -> false)
       cmds_p1_n);
  let m_p1_enter, _ = step m_p1 (mk_key Keymap.Input.Enter) in
  Alcotest.(check bool) "Item 1: Enter on selected ask-1 opens Ask_answer" true
    (Option.equal Nav.equal_overlay m_p1_enter.nav.overlay (Some Nav.Ask_answer));
  let m_p1_j, _ = step m_p1 (char_k ~shift:true "J") in
  Alcotest.(check bool) "Item 1: J on selected ask-1 opens Ask_answer for ask-1" true
    (Option.equal Nav.equal_overlay m_p1_j.nav.overlay (Some Nav.Ask_answer)
     && match m_p1_j.ask_modal with
        | Some am -> String.equal am.ask.ask_id "ask-1"
        | None -> false);
  (* Move cursor to row 2 (goal-2) *)
  let m_p2, _ = step m_p1 (mk_key Keymap.Input.Down) in
  let m_p2_y, _ = step m_p2 (char_k ~shift:true "Y") in
  let m_p2_enter, _ = step m_p2 (mk_key Keymap.Input.Enter) in
  let m_p2_j, _ = step m_p2 (char_k ~shift:true "J") in
  List.iter
    (fun (lbl, m_res) ->
      Alcotest.(check bool) lbl true
        (match Model.active_dive m_res with
         | Some (Nav.Dive_work (Nav.Goal_dive "goal-2")) -> true
         | _ -> false))
    [
      ("Item 1: Y on selected goal-2 pushes Goal_dive", m_p2_y);
      ("Item 1: Enter on selected goal-2 pushes Goal_dive", m_p2_enter);
      ("Item 1: J on selected goal-2 pushes Goal_dive", m_p2_j);
    ];
  (* Mark selected row 2 in-flight: Y must NOT silently jump to row 0 (ta-0)! *)
  let m_p2_inflight =
    {
      m_p2 with
      attention = Attention.mark_in_flight ~id:"goal:goal-2" m_p2.attention;
    }
  in
  Alcotest.(check bool) "Item 1: in-flight selected row does not jump strip to row 0"
    true
    (Option.is_none (Model.fast_approval_strip_item m_p2_inflight));
  let _, cmds_inflight_y = step m_p2_inflight (char_k ~shift:true "Y") in
  Alcotest.(check int) "Item 1: Y on in-flight row 2 never approves row 0" 0
    (List.length (Cmd.flatten cmds_inflight_y));

  (* === 2. Chat Composer PgUp/PgDn scrolling with draft & cursor preserved === *)
  let chat_msgs =
    List.init 60 (fun i ->
        {
          Wire_fleet.id = Printf.sprintf "m-%d" i;
          role = (if i mod 2 = 0 then Wire_fleet.Role_user else Wire_fleet.Role_assistant);
          content = Printf.sprintf "Message line %d with enough text to wrap and scroll cleanly" i;
          ts_unix = 1000.0 +. Float.of_int i;
          turn_ref = None;
          model_used = None;
          tool_call_id = None;
          tool_call_name = None;
          execution_id = None;
          provenance = None;
          failure_kind = None;
          thinking = None;
          retained_images = [];
        })
  in
  let keeper_alpha : Wire_fleet.keeper_summary =
    {
      name = "alpha";
      group = Some "core";
      company = "core";
      health = Wire_fleet.Keeper_healthy;
      paused = false;
      keepalive_running = true;
      activation_mode = Wire_fleet.Activation_autonomous;
      runtime_id = "glm";
      model_id = Some "glm";
      current_task_id = None;
      context = Observed.unreported;
      total_turns = Observed.value ~observed_at:t0 5;
      last_turn_at_unix = None;
      active_turn = None;
    }
  in
  let fleet_chat =
    Fleet_store.empty
    |> Fleet_store.apply_roster ~observed_at:t0
         { keepers = [ keeper_alpha ]; unreadable = [] }
    |> Fleet_store.select_keeper "alpha"
    |> Fleet_store.set_keeper_dive_tab Nav.Keeper_chat
    |> Fleet_store.apply_chat_history ~observed_at:t0 ~keeper:"alpha"
         { messages = chat_msgs; next_cursor = None; has_more = false }
  in
  let drafts_focused =
    Drafts.empty
    |> Drafts.set_active_keeper "alpha"
    |> Drafts.set_focus true
    |> Drafts.insert_text "hello draft"
    |> Drafts.move_cursor `Left
    |> Drafts.move_cursor `Left
  in
  let expected_cursor = (Drafts.current_draft drafts_focused).cursor in
  let m_dive_chat =
    {
      base_with_ws with
      nav =
        {
          base_with_ws.nav with
          workspace = Nav.Keepers;
          dive_stack = [ Nav.Dive_keeper { name = "alpha"; tab = Nav.Keeper_chat } ];
        };
      fleet = fleet_chat;
      drafts = drafts_focused;
    }
  in
  let m_dc_up, _ = step m_dive_chat (mk_key Keymap.Input.Page_up) in
  Alcotest.(check bool) "Item 2: Dive_keeper Chat PgUp scrolls while composer focused"
    true
    (m_dc_up.fleet.chat_scroll_offset > 0
     && Drafts.is_focused m_dc_up.drafts
     && String.equal (Drafts.current_draft m_dc_up.drafts).text "hello draft"
     && Int.equal (Drafts.current_draft m_dc_up.drafts).cursor expected_cursor);
  let m_dc_dn, _ = step m_dc_up (mk_key Keymap.Input.Page_down) in
  Alcotest.(check bool) "Item 2: Dive_keeper Chat PgDn scrolls back down" true
    (m_dc_dn.fleet.chat_scroll_offset < m_dc_up.fleet.chat_scroll_offset
     && Drafts.is_focused m_dc_dn.drafts);
  let m_split_chat =
    {
      base_with_ws with
      nav = { base_with_ws.nav with workspace = Nav.Keepers; pane_index = 0 };
      fleet = fleet_chat;
      drafts = drafts_focused;
    }
  in
  let m_sc_up, _ = step m_split_chat (mk_key Keymap.Input.Page_up) in
  Alcotest.(check bool)
    "Item 2: Keepers embedded split Chat PgUp scrolls even from pane 0 with draft intact"
    true
    (m_sc_up.fleet.chat_scroll_offset > 0
     && Drafts.is_focused m_sc_up.drafts
     && String.equal (Drafts.current_draft m_sc_up.drafts).text "hello draft"
     && Int.equal (Drafts.current_draft m_sc_up.drafts).cursor expected_cursor);

  (* === 3. Ctrl+Q 2-press armed confirmation guard === *)
  let ctrl_q = char_k ~ctrl:true "q" in
  let m_q1, cmds_q1 = step_at ~now:t0 base_with_ws ctrl_q in
  Alcotest.(check bool) "Item 3: 1st Ctrl+Q arms quit and emits 0 Quit cmds" true
    (Option.is_some m_q1.quit_armed_at
     && Option.is_some m_q1.toast
     && not (has_cmd (function Cmd.Quit _ -> true | _ -> false) cmds_q1));
  let m_q2, cmds_q2 = step_at ~now:(Clock.Mono.after_s t0 1.0) m_q1 ctrl_q in
  Alcotest.(check bool) "Item 3: 2nd Ctrl+Q within 2.5s quits cleanly" true
    (Option.is_none m_q2.quit_armed_at
     && has_cmd (function Cmd.Quit Exit_reason.Quit_key -> true | _ -> false) cmds_q2);
  let m_q_tick, _ =
    Update.step ~now:(Clock.Mono.after_s t0 3.0) m_q1
      (Msg.Tick { wall_unix = 1000.0 })
  in
  Alcotest.(check bool) "Item 3: Tick past 2.5s disarms quit_armed_at" true
    (Option.is_none m_q_tick.quit_armed_at);
  let m_q_rearm, cmds_q_rearm =
    step_at ~now:(Clock.Mono.after_s t0 3.1) m_q_tick ctrl_q
  in
  Alcotest.(check bool) "Item 3: Ctrl+Q after expiry re-arms instead of quitting" true
    (Option.is_some m_q_rearm.quit_armed_at
     && not (has_cmd (function Cmd.Quit _ -> true | _ -> false) cmds_q_rearm));
  let m_p_arm, _ = step_at ~now:t0 m_pulse ctrl_q in
  let m_q_cancel, _ =
    step_at ~now:(Clock.Mono.after_s t0 0.4) m_p_arm (char_k "j")
  in
  Alcotest.(check bool)
    "Item 3: non-Esc key 'j' disarms quit_armed_at, clears arm toast AND executes normal Move Down"
    true
    (Option.is_none m_q_cancel.quit_armed_at
     && Option.is_none m_q_cancel.toast
     && Int.equal m_q_cancel.attention.triage_index 1);
  let m_comp_arm, _ = step_at ~now:t0 m_dive_chat ctrl_q in
  let m_comp_typed, _ =
    step_at ~now:(Clock.Mono.after_s t0 0.4) m_comp_arm (char_k "x")
  in
  Alcotest.(check bool)
    "Item 3: typing 'x' in focused composer while quit-armed disarms AND inserts 'x'"
    true
    (Option.is_none m_comp_typed.quit_armed_at
     && Option.is_none m_comp_typed.toast
     && String.equal (Drafts.current_draft m_comp_typed.drafts).text
          "hello draxft");

  (* === 4. Esc dive pop restores exact return_pane & return_zoomed === *)
  let m_from_p2 =
    { base_with_ws with nav = { base_with_ws.nav with workspace = Nav.Pulse; pane_index = 2 } }
  in
  let m_dived_p2, _ =
    Update_nav.push_dive m_from_p2 (Nav.Dive_knowledge (Nav.Thread_dive "p1"))
  in
  let m_popped_p2, _ = step m_dived_p2 (mk_key Keymap.Input.Escape) in
  Alcotest.(check int) "Item 4: Esc restores exact Pulse pane_index=2" 2
    m_popped_p2.nav.pane_index;
  Alcotest.(check int) "Item 4: dive_return_stack stays synchronized" 0
    (List.length m_popped_p2.nav.dive_return_stack);
  let m_zoom_know =
    {
      base_with_ws with
      nav =
        {
          base_with_ws.nav with
          workspace = Nav.Knowledge;
          pane_index = 1;
          zoomed = true;
        };
    }
  in
  let m_z_dived, _ =
    Update_nav.push_dive m_zoom_know (Nav.Dive_knowledge (Nav.Thread_dive "p1"))
  in
  let m_z_popped, _ = step m_z_dived (mk_key Keymap.Input.Escape) in
  Alcotest.(check bool) "Item 4: Esc restores exact zoomed=true state" true
    m_z_popped.nav.zoomed;
  let m_sw, _ = Update_nav.switch_workspace m_z_dived Nav.Pulse in
  Alcotest.(check bool) "Item 4: switch_workspace clears dive_return_stack" true
    (m_sw.nav.dive_stack = [] && m_sw.nav.dive_return_stack = []);

  (* === 6 & 7. Work > Goals phase filter/sort & Goal_dive 2-section Enter drill === *)
  let mk_goal id phase priority updated_at =
    { goal2 with id; title = "Goal " ^ id; phase; priority; updated_at = Some updated_at }
  in
  let g_exec = mk_goal "g-exec" Wire_work.Executing 2 "2026-01-01T00:00:00Z" in
  let g_ver = mk_goal "g-ver" Wire_work.Verifying 1 "2026-01-03T00:00:00Z" in
  let g_paused =
    mk_goal "g-paused" (Wire_work.Paused Wire_work.Resume_executing) 3
      "2026-01-02T00:00:00Z"
  in
  let g_done = mk_goal "g-done" Wire_work.Completed 4 "2026-01-04T00:00:00Z" in
  let mk_task id gid status desc =
    {
      Wire_work.id;
      title = "Task " ^ id;
      description = Some desc;
      status;
      priority = 1;
      goal_link = Wire_work.Linked gid;
      created_at = None;
      updated_at = None;
    }
  in
  let long_desc =
    String.concat "\n"
      (List.init 65 (fun i -> Printf.sprintf "Description paragraph line %d with details." i))
  in
  let tk1 =
    mk_task "tk-1" "g-exec"
      (Wire_work.AwaitingVerification
         {
           assignee = "alpha";
           started_at = "2026-01-01T00:00:00Z";
           submitted_at = "2026-01-01T01:00:00Z";
           verification_id = "ver-1";
         })
      long_desc
  in
  let tk2 =
    mk_task "tk-2" "g-exec"
      (Wire_work.Done
         {
           assignee = "alpha";
           completed_at = "2026-01-01T02:00:00Z";
           notes = None;
         })
      "Short"
  in
  let mk_verif req_id task_id obs =
    {
      Wire_work.request_id = req_id;
      task_id;
      task_title = "Task " ^ task_id;
      submitted_by = "alpha";
      created_at_unix = Some 1000.0;
      completion_contract = [ "check-1" ];
      required_artifacts = [ "art-1" ];
      submitted_evidence = [ "ev-1" ];
      evidence_projection_error = None;
      review_observation = obs;
    }
  in
  let v1 = mk_verif "ver-1" "tk-1" None in
  let v2 =
    mk_verif "ver-2" "tk-2"
      (Some
         {
           Wire_work.state = Wire_work.Review_approved;
           actor = "verifier";
           detail = "looks good";
         })
  in
  let m_work =
    let work =
      base_with_ws.work
      |> Work_store.set_tab Nav.Work_pipeline
      |> Work_store.apply_planning ~observed_at:t0
           { goals = [ g_exec; g_ver; g_paused; g_done ]; tasks = [ tk1; tk2 ] }
      |> Work_store.apply_verifications ~observed_at:t0 [ v1; v2 ]
    in
    { base_with_ws with nav = { base_with_ws.nav with workspace = Nav.Work }; work }
  in
  (* Item 6: Space cycles phase filter (0 POSTs) and Esc resets to All *)
  let m_f1, cmds_f1 = step m_work (char_k " ") in
  Alcotest.(check bool) "Item 6: Space filters to Active (Executing only, 0 POSTs)" true
    (Work_store.equal_goal_phase_filter m_f1.work.goal_phase_filter
       Work_store.Goal_filter_active
     && List.length (Work_store.filtered_goals m_f1.work) = 1
     && List.length (Cmd.flatten cmds_f1) = 0);
  let m_f2, _ = step m_f1 (char_k " ") in
  Alcotest.(check bool) "Item 6: 2nd Space filters to Verifying" true
    (Work_store.equal_goal_phase_filter m_f2.work.goal_phase_filter
       Work_store.Goal_filter_verifying
     && List.length (Work_store.filtered_goals m_f2.work) = 1);
  let m_f_esc, _ = step m_f2 (mk_key Keymap.Input.Escape) in
  Alcotest.(check bool) "Item 6: Esc resets non-All goal filter back to All" true
    (Work_store.equal_goal_phase_filter m_f_esc.work.goal_phase_filter
       Work_store.Goal_filter_all
     && List.length (Work_store.filtered_goals m_f_esc.work) = 4);
  (* Item 6: S cycles sort Default -> Phase -> Progress -> Recent -> Default *)
  let m_s1, _ = step m_work (char_k ~shift:true "S") in
  let m_s2, _ = step m_s1 (char_k ~shift:true "S") in
  let m_s3, _ = step m_s2 (char_k ~shift:true "S") in
  Alcotest.(check bool) "Item 6: S cycles Goal sort Default -> Phase -> Progress -> Recent" true
    (Work_store.equal_goal_sort_mode m_work.work.goal_sort_mode
       Work_store.Goal_sort_default
     && Work_store.equal_goal_sort_mode m_s1.work.goal_sort_mode
          Work_store.Goal_sort_phase
     && (match Work_store.filtered_goals m_s1.work with
        | first :: _ -> String.equal first.id "g-ver"
        | [] -> false)
     && Work_store.equal_goal_sort_mode m_s2.work.goal_sort_mode
          Work_store.Goal_sort_progress
     && Work_store.equal_goal_sort_mode m_s3.work.goal_sort_mode
          Work_store.Goal_sort_recent
     && match Work_store.filtered_goals m_s3.work with
        | first :: _ -> String.equal first.id "g-done"
        | [] -> false);

  (* Item 7: Goal_dive 2 sections (Linked Tasks & Verifier Runs) + Enter drill *)
  let m_gd, _ = Update_nav.push_dive m_work (Nav.Dive_work (Nav.Goal_dive "g-exec")) in
  Alcotest.(check int) "Item 7: Goal_dive has 2 focusable panes" 2
    (Model.focusable_pane_count m_gd);
  let m_gd_down, _ = step m_gd (mk_key Keymap.Input.Down) in
  Alcotest.(check int) "Item 7: Goal_dive pane 0 Down moves task cursor to 1" 1
    m_gd_down.work.goal_dive_task_index;
  let m_gd_td, _ = step m_gd_down (mk_key Keymap.Input.Enter) in
  Alcotest.(check bool) "Item 7: Goal_dive pane 0 Enter pushes Task_dive tk-2" true
    (match Model.active_dive m_gd_td with
     | Some (Nav.Dive_work (Nav.Task_dive "tk-2")) -> true
     | _ -> false);
  let m_gd_tab, _ = step m_gd (mk_key Keymap.Input.Tab) in
  Alcotest.(check int) "Item 7: Goal_dive Tab focuses pane 1 (Verifier Runs)" 1
    m_gd_tab.nav.pane_index;
  let m_gd_vdown, _ = step m_gd_tab (mk_key Keymap.Input.Down) in
  Alcotest.(check int) "Item 7: Goal_dive pane 1 Down selects 2nd verifier run" 1
    m_gd_vdown.work.goal_dive_verif_index;
  let m_gd_vd, _ = step m_gd_vdown (mk_key Keymap.Input.Enter) in
  Alcotest.(check bool) "Item 7: Goal_dive pane 1 Enter pushes Verification_dive ver-2"
    true
    (match Model.active_dive m_gd_vd with
     | Some (Nav.Dive_work (Nav.Verification_dive "ver-2")) -> true
     | _ -> false);
  let m_gd_back, _ = step m_gd_vd (mk_key Keymap.Input.Escape) in
  Alcotest.(check int) "Item 4+7: Esc from nested Verification_dive restores Goal_dive pane 1"
    1 m_gd_back.nav.pane_index;

  (* === 8. Harness_overrule auto-seed + missing-hash block + Schedule_form prefill === *)
  let hash64 =
    "abcdef0123456789abcdef0123456789abcdef0123456789abcdef0123456789"
  in
  let m_gd_nohh_h, _ = step m_gd (char_k "h") in
  Alcotest.(check bool) "Item 8: Goal_dive [h] without harness verdict warns, no empty modal"
    true
    (Option.is_none m_gd_nohh_h.nav.overlay && Option.is_some m_gd_nohh_h.toast);
  let hh_linked : Wire_work.harness_health =
    {
      generated_at = 1795254000.0;
      scope_note = "last 7d";
      evaluator_status = "healthy";
      fallback_ratio = 0.0;
      last_signal_at = Some 1795253900.0;
      calibration =
        {
          total_verdicts = 1;
          approve_count = 1;
          reject_count = 0;
          labeled_count = 1;
          false_positive_count = 0;
          false_negative_count = 0;
          agreement_rate = 1.0;
          fallback_count = 0;
          distinct_runtime_count = 1;
          verdicts_with_generator_runtime = 1;
          distinct_runtime_rate = Some 1.0;
          recent_fallback_reasons = [];
          unreadable_record_count = 0;
        };
      recent_verdicts =
        [
          {
            timestamp = 1700000000.0;
            task_id = "tk-1";
            task_title = "Task tk-1";
            agent_name = "alpha";
            gate = "completion";
            verdict = "approve";
            evaluator_runtime = "glm";
            fallback_reason = None;
            notes_hash = hash64;
          };
        ];
      unreadable_verdicts_count = 0;
    }
  in
  let m_gd_hh =
    { m_gd with work = Work_store.apply_harness_health ~observed_at:t0 hh_linked m_gd.work }
  in
  let m_gd_hh_h, _ = step m_gd_hh (char_k "h") in
  Alcotest.(check bool)
    "Item 8: Goal_dive [h] binds the linked hash and starts on reason"
    true
    (Option.equal Nav.equal_overlay m_gd_hh_h.nav.overlay
       (Some (Nav.Inline_action (Nav.Harness_overrule hash64)))
     && match m_gd_hh_h.inline_modal with
        | Some md -> md.active_field = 1
        | None -> false);
  let m_sched_tab =
    {
      m_work with
      work = Work_store.set_tab Nav.Work_schedules m_work.work;
      drafts = Drafts.set_active_keeper "alpha" m_work.drafts;
    }
  in
  let m_sched_modal, _ = step m_sched_tab (char_k "n") in
  Alcotest.(check bool) "Item 8: Schedule_form pre-fills active keeper and jumps to field 2"
    true
    (match m_sched_modal.inline_modal with
     | Some md ->
         String.equal (Model.modal_field_value ~key:"keeper" md) "alpha"
         && md.active_field = 2
     | None -> false);

  (* === 9. Eliminate 'a'/'x' HTTP 400 + Goal_drop note modal + error extraction === *)
  (* 9a. Already-approved verification 'a' and 'x' emit 0 HTTP POSTs *)
  let m_vd_done, _ =
    Update_nav.push_dive m_work (Nav.Dive_work (Nav.Verification_dive "ver-2"))
  in
  let m_vd_done_a, cmds_vda = step m_vd_done (char_k "a") in
  let m_vd_done_x, cmds_vdx = step m_vd_done (char_k "x") in
  Alcotest.(check bool) "Item 9: 'a' on approved verification blocked locally (0 POSTs)"
    true
    (Option.is_some m_vd_done_a.toast && List.length (Cmd.flatten cmds_vda) = 0);
  Alcotest.(check bool) "Item 9: 'x' on approved verification blocked locally (no modal)"
    true
    (Option.is_none m_vd_done_x.nav.overlay && List.length (Cmd.flatten cmds_vdx) = 0);
  (* 9b. Goal 'c' on Paused / Completed emits 0 POSTs *)
  let m_gd_paused, _ =
    Update_nav.push_dive m_work (Nav.Dive_work (Nav.Goal_dive "g-paused"))
  in
  let m_gp_c, cmds_gpc = step m_gd_paused (char_k "c") in
  Alcotest.(check bool) "Item 9: 'c' on Paused goal blocked locally (0 POSTs)" true
    (Option.is_some m_gp_c.toast && List.length (Cmd.flatten cmds_gpc) = 0);
  (* 9c. Goal 'x' on Paused opens Goal_drop modal and submits non-empty note *)
  let m_gp_x, cmds_gpx = step m_gd_paused (char_k "x") in
  Alcotest.(check bool) "Item 9: 'x' on Paused goal opens Goal_drop modal (0 immediate POSTs)"
    true
    (Option.equal Nav.equal_overlay m_gp_x.nav.overlay
       (Some (Nav.Inline_action (Nav.Goal_drop "g-paused")))
     && List.length (Cmd.flatten cmds_gpx) = 0);
  let m_gp_empty_err, cmds_gp_empty = step m_gp_x (mk_key Keymap.Input.Enter) in
  Alcotest.(check bool) "Item 9: Goal_drop refuses blank note" true
    (List.length (Cmd.flatten cmds_gp_empty) = 0
     && match m_gp_empty_err.inline_modal with
        | Some md -> Option.is_some md.error
        | None -> false);
  let m_gp_typed =
    String.fold_left
      (fun acc ch -> fst (step acc (char_k (String.make 1 ch))))
      m_gp_x "obsolete"
  in
  let m_gp_sub, cmds_gp_ok = step m_gp_typed (mk_key Keymap.Input.Enter) in
  Alcotest.(check bool) "Item 9: Goal_drop submit sends Drop with non-empty note" true
    (has_cmd
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_goal_transition
                   {
                     goal_id = "g-paused";
                     action = Wire_work.Drop;
                     note = Some "obsolete";
                     _;
                   };
               _;
             } ->
             true
         | _ -> false)
       cmds_gp_ok);
  Alcotest.(check bool) "Item 9 (Finding #10): Goal_drop marks submitting while in flight" true
    (match m_gp_sub.inline_modal with
     | Some md -> md.submitting && String.equal (Model.modal_field_value ~key:"note" md) "obsolete"
     | None -> false);
  let m_gp_err, _ =
    Update.step ~now:t0 m_gp_sub
      (Msg.Http_reply
         {
           epoch = m_gp_sub.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.make ~ko:"목표 상태 변경됨" ~en:"Goal transitioned";
                 ack_scope = Msg.Ack_close_modal_and_refresh;
                 for_modal = Some (Nav.Goal_drop "g-paused");
                 result =
                   Error
                     (Msg.Http_error
                        { status = 400; body = {|{"error":"conflict"}|}; api_error = None });
               };
         })
  in
  Alcotest.(check bool)
    "Item 9 (Finding #10): Goal_drop Error preserves typed note and surfaces error"
    true
    (match m_gp_err.inline_modal with
     | Some md ->
         (not md.submitting)
         && Option.is_some md.error
         && String.equal (Model.modal_field_value ~key:"note" md) "obsolete"
     | None -> false);
  let m_gp_closed, _ =
    Update.step ~now:t0 m_gp_sub
      (Msg.Http_reply
         {
           epoch = m_gp_sub.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label = Say.make ~ko:"목표 상태 변경됨" ~en:"Goal transitioned";
                 ack_scope = Msg.Ack_close_modal_and_refresh;
                 for_modal = Some (Nav.Goal_drop "g-paused");
                 result = Ok ();
               };
         })
  in
  Alcotest.(check bool) "Item 9 (Finding #10): Goal_drop Ok closes modal cleanly" true
    (Option.is_none m_gp_closed.inline_modal && Option.is_none m_gp_closed.nav.overlay);
  (* 9d. HTTP 400 JSON error extraction (plain + nested tool_result JSON + UTF-8 Korean) *)
