  (* Round-2 #496 hardening: expired quit_armed_at (>2.5s) clears arm AND lets Esc pop dive *)
  let t_expired = Clock.Mono.of_ns 15_000_000_000L in
  let m_dive_exp_esc, _ = step_at ~now:t_expired m_dive_arm1 (mk_key Keymap.Input.Escape) in
  Alcotest.(check bool)
    "Round-2 #496: expired quit_armed_at (>2.5s) does NOT swallow Esc (pops Goal_dive)"
    true
    (Option.is_none m_dive_exp_esc.quit_armed_at
     && Option.is_none (Model.active_dive m_dive_exp_esc));

  (* === Round-3 GitHub CR Fixes (P2 #1, P2 #2, P2 #3) === *)
  (* CR P2 #1: Thread_dive B with stale active_thread A never shows/scrolls A or votes on A's comment *)
  let long_post_a =
    mk_post "post-a" "Post A"
      (String.concat "\n"
         (List.init 60 (fun i -> Printf.sprintf "Post A body line %d" i)))
  in
  let m_thread_a =
    let k0 = Knowledge_store.empty |> Knowledge_store.set_tab Nav.Knowledge_board in
    let knowledge =
      {
        k0 with
        board =
          Observed.value ~observed_at:t0
            {
              Wire_knowledge.posts = [ long_post_a ];
              count = 1;
              sort_by = "recent";
              signal_only = true;
            };
        active_thread = Observed.value ~observed_at:t0 (long_post_a, many_comments);
        active_thread_target = Some "post-a";
        thread_selected_comment = Some "c-0";
      }
    in
    {
      base_with_ws with
      nav = { base_with_ws.nav with workspace = Nav.Knowledge; pane_index = 0 };
      knowledge;
    }
  in
  let expanded_comment =
    String.concat "\n\n" (List.init 50 (fun i -> Printf.sprintf "Paragraph %d" i))
  in
  let comments =
    List.map
      (fun (comment : Wire_knowledge.board_comment) ->
        { comment with post_id = "post-a"; body = expanded_comment })
      many_comments
  in
  let reader =
    {
      m_thread_a with
      knowledge =
        Knowledge_store.apply_thread ~observed_at:t0 (long_post_a, comments)
          m_thread_a.knowledge;
    }
  in
  let post, _ =
    Update_nav.push_dive reader (Nav.Dive_knowledge (Nav.Thread_dive "post-a"))
  in
  let post, _ = step post (mk_key Keymap.Input.Page_down) in
  let comment, switch_cmds = step post (mk_key Keymap.Input.Tab) in
  let comment, _ = step comment (mk_key Keymap.Input.Page_down) in
  Alcotest.(check bool) "thread reader scrolls its full comment without sending"
    true
    (List.is_empty (Cmd.flatten switch_cmds)
     && comment.knowledge.thread_comment_scroll > 0
     && Int.equal post.nav.dive_scroll_offset comment.nav.dive_scroll_offset);
  let post_again, _ = step comment (mk_key Keymap.Input.Tab) in
  let comment_again, _ = step post_again (mk_key Keymap.Input.Tab) in
  Alcotest.(check int) "Tab restores the selected comment scroll"
    comment.knowledge.thread_comment_scroll
    comment_again.knowledge.thread_comment_scroll;
  let next_comment, _ = step comment_again (char_k ">") in
  let reply, _ = step next_comment (char_k "c") in
  Alcotest.(check bool) "reply targets the visible comment and starts it at the top"
    true
    (Int.equal next_comment.knowledge.thread_comment_scroll 0
     && Option.equal Nav.equal_overlay reply.nav.overlay
          (Some (Nav.Inline_action
             (Nav.Board_comment { post_id = "post-a"; parent_id = Some "c-1" }))));
  let reading, _ = step next_comment (mk_key Keymap.Input.Page_down) in
  let apply_thread_reply m result =
    Update.step ~now:t0 m
      (Msg.Http_reply
         { epoch = m.Model.epoch;
           reply = Msg.Reply_board_thread { post_id = "post-a"; result } })
    |> fst
  in
  let failed =
    apply_thread_reply reading
      (Error (Msg.Http_error { status = 503; body = "temporary"; api_error = None }))
  in
  let failed, _ = step failed (mk_key Keymap.Input.Page_down) in
  let added : Wire_knowledge.board_comment =
    { (List.hd comments) with id = "c-earlier"; created_at_unix = 1050.0 }
  in
  let recovered = apply_thread_reply failed (Ok (long_post_a, added :: comments)) in
  Alcotest.(check bool) "the same comment and position survive a retryable refresh failure"
    true
    (Option.equal String.equal recovered.knowledge.thread_selected_comment (Some "c-1")
     && Int.equal reading.knowledge.thread_comment_scroll
          recovered.knowledge.thread_comment_scroll);
  (* Entering Thread_dive "post-b" (not in board feed) marks active_thread Loading for post-b *)
  let m_dive_b, cmds_dive_b =
    Update_nav.push_dive m_thread_a (Nav.Dive_knowledge (Nav.Thread_dive "post-b"))
  in
  Alcotest.(check bool)
    "CR P2 #1: push_dive Thread_dive B marks active_thread Loading for B & clears comment selection"
    true
    (Observed.is_loading m_dive_b.knowledge.active_thread
     && Option.equal String.equal m_dive_b.knowledge.active_thread_target (Some "post-b")
     && Option.is_none m_dive_b.knowledge.thread_selected_comment
     && has_cmd
          (function
            | Cmd.Http_get { req = Cmd.Get_board_thread { post_id = "post-b"; _ }; _ } -> true
            | _ -> false)
          cmds_dive_b);
  (* Even if active_thread still holds stale Post A + selected comment c-0 while in Thread_dive B:
     - selected_thread_comment ~post_id:"post-b" is None
     - PgDn yields dive_scroll_offset = 0 (never uses Post A's long body/comments)
     - Board_vote NEVER constructs Post_board_comment_vote { post_id = "post-b"; comment_id = "c-0" }
     - Board_comment NEVER sets parent_id = Some "c-0" from Post A *)
  let m_dive_b_stale =
    {
      m_dive_b with
      knowledge =
        {
          m_dive_b.knowledge with
          active_thread = Observed.value ~observed_at:t0 (long_post_a, many_comments);
          active_thread_target = Some "post-a";
          thread_selected_comment = Some "c-0";
        };
    }
  in
  Alcotest.(check bool)
    "CR P2 #1: selected_thread_comment ~post_id:B returns None when active_thread holds A"
    true
    (Option.is_none
       (Knowledge_store.selected_thread_comment ~post_id:"post-b"
          { m_dive_b_stale.knowledge with thread_view = Knowledge_store.Thread_comments }));
  let m_dive_b_pgdn, _ = step m_dive_b_stale (mk_key Keymap.Input.Page_down) in
  Alcotest.(check int)
    "CR P2 #1: Thread_dive B PgDn does not scroll stale Post A's body/comments"
    0 m_dive_b_pgdn.nav.dive_scroll_offset;
  let m_vote_arm, _ = step m_dive_b_stale (char_k "+") in
  let _, cmds_vote_confirm = step m_vote_arm (char_k "+") in
  Alcotest.(check bool)
    "CR P2 #1: Board_vote in Thread_dive B never votes on Post A's comment under post-b"
    true
    (not
       (has_cmd
          (function
            | Cmd.Http_post { req = Cmd.Post_board_comment_vote _; _ } -> true
            | _ -> false)
          cmds_vote_confirm)
     && has_cmd
          (function
            | Cmd.Http_post
                { req = Cmd.Post_board_vote { post_id = "post-b"; direction = `Up }; _ } ->
                true
            | _ -> false)
          cmds_vote_confirm);
  let m_comment_b, _ = step m_dive_b_stale (char_k "c") in
  Alcotest.(check bool)
    "CR P2 #1: Board_comment in Thread_dive B never attaches Post A's comment as parent_id"
    true
    (match m_comment_b.nav.overlay with
     | Some (Nav.Inline_action (Nav.Board_comment { post_id = "post-b"; parent_id = None })) ->
         true
     | _ -> false);
  (* mark_thread_loading preserves matching loaded Value and settled non-retryable 404 unless force=true *)
  let k_keep_loaded =
    Knowledge_store.mark_thread_loading ~post_id:"post-a" ~since_ns:t0
      m_thread_a.knowledge
  in
  let k_keep_404 =
    Knowledge_store.mark_thread_loading ~post_id:"post-1" ~since_ns:t0
      m_board_404.knowledge
  in
  let k_force_404 =
    Knowledge_store.mark_thread_loading ~force:true ~post_id:"post-1" ~since_ns:t0
      m_board_404.knowledge
  in
  Alcotest.(check bool)
    "CR P2 #1: mark_thread_loading keeps loaded same-post Value & settled 404 unless force=true"
    true
    (Observed.is_value k_keep_loaded.active_thread
     && (not (Observed.is_loading k_keep_404.active_thread))
     && Observed.is_loading k_force_404.active_thread);
  (* Switching Board selection from post-1 to post-2 marks active_thread Loading for post-2 *)
  let m_board_sel2, _ = step m_board (mk_key Keymap.Input.Down) in
  Alcotest.(check bool)
    "CR P2 #1: Board pane 0 Down to post-2 marks active_thread Loading for post-2"
    true
    (Observed.is_loading m_board_sel2.knowledge.active_thread
     && Option.equal String.equal m_board_sel2.knowledge.active_thread_target
          (Some "post-2"));

  (* CR P2 #3: Attention ID-anchored selection across Work > Inbox filter clear & workspace switch *)
  let m_inbox_3 =
    let attn =
      Attention.rebuild ~asks:[] ~tool_approvals:[ ta0 ]
        ~gate_pending:[ g_beta1; g_beta2 ] ~goals:[] Attention.empty
    in
    {
      base_with_ws with
      nav = { base_with_ws.nav with workspace = Nav.Work; pane_index = 0 };
      work = base_with_ws.work |> Work_store.set_tab Nav.Work_inbox;
      attention = attn;
    }
  in
  (* Scenario A: filter "beta" -> Down selects gate-b2 -> clear filter "" -> gate-b2 stays selected & Y approves gate-b2 *)
  let m_f_beta, _ = Update_nav.set_active_filter_query "beta" m_inbox_3 in
  let m_f_b2, _ = step m_f_beta (mk_key Keymap.Input.Down) in
  Alcotest.(check (option string))
    "CR P2 #3: Down on filtered Inbox selects gate:gate-b2"
    (Some "gate:gate-b2")
    (Option.map (fun (e : Attention.entry) -> e.id)
       (Attention.current_filtered_item ~query:m_f_b2.work.filter_query
          m_f_b2.attention));
  (* Opening an overlay (Help) over filtered Inbox never falls back to unfiltered Alpha (ta0) *)
  let m_f_b2_help, _ = Update_nav.open_overlay m_f_b2 Nav.Help in
  Alcotest.(check (option string))
    "CR P2 #3: overlay over filtered Inbox keeps strip on gate:gate-b2 (never Alpha)"
    (Some "gate:gate-b2")
    (Option.map (fun (e : Attention.entry) -> e.id)
       (Model.fast_approval_strip_item m_f_b2_help));
  let m_f_cleared, _ = Update_nav.set_active_filter_query "" m_f_b2 in
  Alcotest.(check (option int))
    "CR P2 #3: clearing filter syncs selected_index_in_filtered to 2 (gate:gate-b2)"
    (Some 2)
    (Attention.selected_index_in_filtered ~query:"" m_f_cleared.attention);
  Alcotest.(check (option string))
    "CR P2 #3: clearing filter keeps gate:gate-b2 selected (not Alpha or Beta1)"
    (Some "gate:gate-b2")
    (Option.map (fun (e : Attention.entry) -> e.id)
       (Attention.current_filtered_item ~query:"" m_f_cleared.attention));
  let _, cmds_approve_b2 = step m_f_cleared (char_k ~shift:true "Y") in
  Alcotest.(check bool)
    "CR P2 #3: Y after filter clear approves gate-b2 (never Alpha ta-0 or gate-b1)"
    true
    (has_cmd
       (function
         | Cmd.Http_post
             { req = Cmd.Post_gate_resolution { id = "gate-b2"; approved = true; _ }; _ } ->
             true
         | _ -> false)
       cmds_approve_b2
     && not
          (has_cmd
             (function
               | Cmd.Http_post { req = Cmd.Post_tool_approval _; _ } -> true
               | _ -> false)
             cmds_approve_b2));
  let check_disarmed reason (m : Model.t) =
    Alcotest.(check (option int)) (reason ^ ": no highlighted row") None
      (Attention.selected_index_in_filtered ~query:m.work.filter_query
         m.attention);
    Alcotest.(check bool) (reason ^ ": inspector and action strip are closed")
      true
      (m.nav.pane_index = 0 && Model.focusable_pane_count m = 1
       && Option.is_none (Model.fast_approval_strip_item m));
    let _, cmds = step m (char_k ~shift:true "Y") in
    Alcotest.(check bool) (reason ^ ": Y sends no approval") false
      (has_cmd
         (function
           | Cmd.Http_post
               { req = (Cmd.Post_tool_approval _ | Cmd.Post_gate_resolution _); _ } ->
               true
           | _ -> false)
         cmds)
  in
  let m_f_detail =
    { m_f_cleared with nav = { m_f_cleared.nav with pane_index = 1 } }
  in
  let m_f_edit, _ = step m_f_detail (char_k "/") in
  let m_f_typed, _ = Update.step ~now:t0 m_f_edit (Msg.Paste_text "alpha") in
  let m_f_hidden, _ = step m_f_typed (mk_key Keymap.Input.Enter) in
  Alcotest.(check string) "filter edit exposes the Alpha row" "alpha"
    m_f_hidden.work.filter_query;
  check_disarmed "filter hides the selected Beta row" m_f_hidden;
  let m_f_restored, _ = Update_nav.set_active_filter_query "" m_f_hidden in
  Alcotest.(check (option string)) "clearing the filter restores Beta2"
    (Some "gate:gate-b2")
    (Option.map (fun (e : Attention.entry) -> e.id)
       (Model.fast_approval_strip_item m_f_restored));
  let m_inventory =
    let work =
      m_f_detail.work
      |> Work_store.apply_tool_approvals ~observed_at:t0 [ ta0 ]
      |> Work_store.apply_gate_pending ~observed_at:t0 [ g_beta1; g_beta2 ]
    in
    Model.rebuild_attention { m_f_detail with work }
  in
  let m_f_gone, _ =
    Update.step ~now:t0 m_inventory
      (Msg.Http_reply
         { epoch = m_inventory.epoch; reply = Msg.Reply_gate_pending (Ok [ g_beta1 ]) })
  in
  check_disarmed "server removes the selected Beta row" m_f_gone;
  let m_f_moved, _ = step m_f_gone (mk_key Keymap.Input.Down) in
  let _, cmds_approve_alpha = step m_f_moved (char_k ~shift:true "Y") in
  Alcotest.(check bool) "moving to Alpha enables approval of that row" true
    (has_cmd
       (function
         | Cmd.Http_post
             { req = Cmd.Post_tool_approval { approval_id = "ta-0"; _ }; _ } ->
             true
         | _ -> false)
       cmds_approve_alpha);
  (* Scenario B: acting on Beta1 (Gate_reject auto-advances to Beta2), then clearing filter & switching to Pulse keeps Beta2 *)
  let m_gr_cleared, _ = Update_nav.set_active_filter_query "" m_gr_sub in
  let m_gr_pulse, _ = Update_nav.switch_workspace m_gr_sub Nav.Pulse in
  Alcotest.(check (option string))
    "CR P2 #3: clearing filter after Gate_reject auto-advance stays on gate:gate-b2"
    (Some "gate:gate-b2")
    (Option.map (fun (e : Attention.entry) -> e.id)
       (Model.fast_approval_strip_item m_gr_cleared));
  Alcotest.(check (option string))
    "CR P2 #3: switching to Pulse after filtered auto-advance keeps gate:gate-b2 selected"
    (Some "gate:gate-b2")
    (Option.map (fun (e : Attention.entry) -> e.id)
       (Attention.current_filtered_item ~query:"" m_gr_pulse.attention))

let test_live_chat_activity_uses_open_content_and_tool_receipts () =
  let open Chat_transcript in
  let keeper = "alpha-leader" and request_id = "activity-request" in
  let model = Model.initial ~cols:56 ~rows:20 () in
  let model =
    { model with fleet = Fleet_store.start_chat_stream ~keeper ~request_id model.fleet }
  in
  let apply ?(request_id = request_id) m chunk =
    fst (Update.step ~now:t1 m
           (Msg.Chat_stream_chunk
              { epoch = m.epoch; keeper; request_id; is_btw = false; chunk }))
  in
  let apply_json m json =
    match Wire_fleet.decode_chat_stream_chunk (Yojson.Safe.from_string json) with
    | Ok chunk -> apply m chunk
    | Error error -> Alcotest.fail error
  in
  let check_phase label expected model =
    Alcotest.(check bool) label true
      (equal_live_chat_phase (live_chat_phase ~model ~keeper) expected)
  in
  let custom m name value =
    apply_json m
      (Printf.sprintf {|{"type":"CUSTOM","name":"%s","value":%s}|} name value)
  in
  let content m ~scope ~block channel state =
    custom m "KEEPER_MODEL_CONTENT_ACTIVITY"
      (Printf.sprintf
         {|{"generation":3,"stream_scope":%d,"block_index":%d,"channel":"%s","state":"%s"}|}
         scope block channel state)
  in
  let stop m scope =
    custom m "KEEPER_STREAM_MESSAGE_STOP"
      (Printf.sprintf {|{"content_generation":3,"stream_scope":%d}|} scope)
  in
  let start ?(generation = 3) m scope =
    custom m "KEEPER_STREAM_MESSAGE_START"
      (Printf.sprintf
         {|{"content_generation":%d,"stream_scope":%d,"provider_message_id":"message","model":"model"}|}
         generation scope)
  in
  let m =
    apply_json model
      {|{"type":"TEXT_MESSAGE_CONTENT","delta":"Earlier reply text","textResponse":{"content_generation":3,"stream_scope":1}}|}
  in
  let m = content m ~scope:1 ~block:0 "text" "observed" in
  let thinking = content m ~scope:1 ~block:1 "thinking" "observed" in
  check_phase "new reasoning takes precedence over retained reply bytes" Phase_thinking thinking;
  check_phase "the reasoning detail preference leaves activity visible" Phase_thinking
    { thinking with fleet = { thinking.fleet with chat_thinking_mode = Thinking_hidden } };
  let finished_thinking = content thinking ~scope:1 ~block:1 "thinking" "ended" in
  check_phase "closing reasoning returns to the open text block" Phase_streaming finished_thinking;
  let repeated = content finished_thinking ~scope:1 ~block:1 "thinking" "observed" in
  check_phase "replayed activity cannot reopen an ended block" Phase_streaming repeated;
  let stopped = stop repeated 1 in
  check_phase "response stop clears activity while the turn is open" Phase_awaiting_turn stopped;
  let next = content stopped ~scope:2 ~block:1 "thinking" "observed" in
  check_phase "a previous response stop cannot hide new reasoning" Phase_thinking (stop next 1);
  let other_request = apply ~request_id:"other-request" next
      (Wire_fleet.Chunk_model_response_stop
         { operation_id = None; owner = Some { content_generation = 3; stream_scope = 2 } }) in
  check_phase "a different request cannot stop this response" Phase_thinking other_request;
  let start_tool m =
    apply_json m
      {|{"type":"TOOL_CALL_START","toolStreamScope":2,"toolCallBlockIndex":2,"toolCallId":"provider-id","toolCallName":"Read"}|}
  in
  let close_tool_block m =
    apply_json m
      {|{"type":"TOOL_CALL_END","toolStreamScope":2,"toolCallBlockIndex":2,"toolCallId":"provider-id"}|}
  in
  let tool = start_tool (stop next 2) in
  let args_ended = close_tool_block tool in
  check_phase "end of argument input leaves the tool pending" (Phase_tool_waiting "Read") args_ended;
  let same_response = close_tool_block (start_tool next) in
  let trailing_text = content same_response ~scope:2 ~block:3 "text" "observed" in
  check_phase "fresh content can follow a closed tool without a result in the same response"
    Phase_streaming trailing_text;
  check_phase "same-response model output leaves the tool result pending"
    (Phase_tool_waiting "Read") (stop trailing_text 2);
  check_phase "a same-scope prelude leaves the tool result pending"
    (Phase_tool_waiting "Read") (start args_ended 2);
  let next_response = start args_ended 3 in
  let buffer (m : Model.t) = Fleet_store.String_map.find keeper m.fleet.chat_streams in
  check_phase "a new prelude clears still-open reasoning from a lost stop"
    Phase_awaiting_turn (start thinking 2);
  let fresh_run = apply model (Wire_fleet.Chunk_run_started { operation_id = None }) in
  check_phase "delayed activity cannot take over a prelude that has no content yet"
    Phase_awaiting_turn (content (start fresh_run 3) ~scope:2 ~block:9 "text" "observed");
  check_phase "a delayed tool start cannot reopen the retired tool"
    Phase_awaiting_turn (start_tool next_response);
  check_phase "a stopped newer response still excludes a replayed older tool"
    Phase_awaiting_turn (start_tool (stop next_response 3));
  check_phase "a newer generation resets the scope and retires the old tool"
    Phase_awaiting_turn (start ~generation:4 args_ended 0);
  let new_gen_tool = start_tool (start ~generation:4 args_ended 1) in
  check_phase "a higher scope in an older generation leaves the current tool running"
    (Phase_tool_running "Read") (start ~generation:3 new_gen_tool 9);
  check_phase "a prelude without generation cannot supersede a known response"
    (Phase_tool_running "Read")
    (custom new_gen_tool "KEEPER_STREAM_MESSAGE_START" {|{"stream_scope":9}|});
  let legacy_tool = close_tool_block (start_tool model) in
  check_phase "a scope-only prelude can still retire a scope-only tool"
    Phase_awaiting_turn (custom legacy_tool "KEEPER_STREAM_MESSAGE_START" {|{"stream_scope":3}|});
  let legacy_start m scope =
    custom m "KEEPER_STREAM_MESSAGE_START"
      (Printf.sprintf {|{"stream_scope":%d,"provider_message_id":"message","model":"model"}|} scope)
  in
  let owned_after_bare = start ~generation:4 (legacy_start fresh_run 9) 0 in
  check_phase "a prior bare scope without a generation cannot reject the first owned start"
    (Phase_tool_running "Read") (legacy_start (start_tool owned_after_bare) 10);
  let old_activity = content (legacy_start fresh_run 1) ~scope:1 ~block:0 "thinking" "observed" in
  let legacy_wait = close_tool_block (start_tool (legacy_start old_activity 2)) in
  check_phase "legacy typed content does not prevent the next bare start from retiring its tool"
    Phase_awaiting_turn (legacy_start legacy_wait 3);
  check_phase "an equal bare start leaves its tool pending"
    (Phase_tool_waiting "Read") (legacy_start legacy_wait 2);
  check_phase "a lower bare start leaves the later tool pending"
    (Phase_tool_waiting "Read") (legacy_start legacy_wait 1);
  let legacy_next = legacy_start legacy_wait 3 in
  check_phase "late activity from the retired legacy scope stays closed"
    Phase_awaiting_turn (content legacy_next ~scope:2 ~block:9 "text" "observed");
  check_phase "the new legacy scope can report exact content"
    Phase_streaming (content legacy_next ~scope:3 ~block:0 "text" "observed");
  let delta m scope text =
    apply_json m (Printf.sprintf
      {|{"type":"TEXT_MESSAGE_CONTENT","delta":"%s","textResponse":{"content_generation":3,"stream_scope":%d}}|}
      text scope)
  in
  let thoughts m name key scope value =
    custom m name (Printf.sprintf
      {|{"index":0,"%s":"%s","response":{"content_generation":3,"stream_scope":%d}}|}
      key value scope)
  in
  Alcotest.(check string) "a prelude excludes stale bytes before its first content"
    "Earlier reply text" (buffer (delta next_response 2 " late")).text;
  let old_run = apply_json next_response
      {|{"type":"TEXT_MESSAGE_CONTENT","runId":"keeper-operation-run-other","delta":"late","textResponse":{"content_generation":3,"stream_scope":2}}|} in
  Alcotest.(check (option string)) "a rejected delta cannot bind its operation to the live request"
    (buffer next_response).operation_id (buffer old_run).operation_id;
  let owned_activity = content fresh_run ~scope:3 ~block:0 "thinking" "observed" in
  let matching_start = start owned_activity 3 in
  let next_attempt =
    Wire_fleet.Chunk_runtime_attempt_started
      { operation_id = None; runtime_id = None; attempt_index = None }
  in
  let matching_retry = apply matching_start next_attempt in
  Alcotest.(check string) "retry retires a matching prelude received after content activity alone"
    "" (buffer (delta matching_retry 3 "late")).text;
  let after_owned_start = content (start fresh_run 1) ~scope:3 ~block:0 "thinking" "observed" in
  let retry_after_match = apply (start after_owned_start 3) next_attempt in
  Alcotest.(check string) "a prior owned prelude cannot mask the retry boundary of a later matching start"
    "" (buffer (delta retry_after_match 3 "late")).text;
  let current_bytes = delta next_response 3 " fresh" in
  Alcotest.(check string) "only this response can append text after its prelude"
    "Earlier reply text fresh" (buffer (delta current_bytes 2 " late")).text;
  let current_thought = thoughts next_response "KEEPER_THINKING_SNAPSHOT" "snapshot" 3 "current" in
  let current_thought = thoughts current_thought "KEEPER_THINKING_DELTA" "delta" 3 "+" in
  let late = thoughts current_thought "KEEPER_THINKING_SNAPSHOT" "snapshot" 2 "stale" in
  let late = thoughts late "KEEPER_THINKING_DELTA" "delta" 2 "stale" in
  Alcotest.(check string) "late reasoning cannot replace or append to the current thought"
    "current+" (buffer late).thinking;
  let retrying =
    apply next_response
      (Wire_fleet.Chunk_provider_retry
         { operation_id = None; runtime_id = None; attempt = 1;
           max_retries = 2; retry_delay_ms = 125; error_status = None })
  in
  let retrying = thoughts retrying "KEEPER_THINKING_DELTA" "delta" 2 "stale" in
  Alcotest.(check (option string)) "stale reasoning preserves the retry notice"
    (Some "retry 1/2 (125ms)") (buffer retrying).retry_notice;
  let resumed = thoughts retrying "KEEPER_THINKING_SNAPSHOT" "snapshot" 3 "resumed" in
  Alcotest.(check (option string)) "accepted reasoning clears the retry notice"
    None (buffer resumed).retry_notice;
  let retry = apply next_response next_attempt in
  Alcotest.(check string) "retry retires a prelude even if that response sent no text"
    "" (buffer (delta retry 3 " late")).text;
  check_phase "replaying a prelude cannot reopen a stopped response"
    Phase_awaiting_turn (content (start (stop next_response 3) 3) ~scope:3 ~block:9 "text" "observed");
  Alcotest.(check bool) "an invalid generation cannot become a scope-only prelude" true
    (Result.is_error (Wire_fleet.decode_chat_stream_chunk
      (Yojson.Safe.from_string
         {|{"type":"CUSTOM","name":"KEEPER_STREAM_MESSAGE_START","value":{"content_generation":-1,"stream_scope":9}}|})));
  check_phase "a newer response prelude retires the earlier tool before any content"
    Phase_awaiting_turn next_response;
  check_phase "the first content sets activity after the new response prelude"
    Phase_thinking (content next_response ~scope:3 ~block:1 "thinking" "observed");
  check_phase "fresh content can follow an unadmitted tool in the next response"
    Phase_thinking (content args_ended ~scope:3 ~block:1 "thinking" "observed");
  let next_tool = apply_json args_ended
      {|{"type":"TOOL_CALL_START","toolStreamScope":3,"toolCallBlockIndex":1,"toolCallName":"Write"}|} in
  check_phase "a tool-only response also retires the earlier unadmitted tool"
    Phase_awaiting_turn
    (custom next_tool "KEEPER_TOOL_RESULT_READY"
       {|{"toolStreamScope":3,"toolCallBlockIndex":1,"executionId":"exec-write"}|});
  let settled = custom args_ended "KEEPER_TOOL_RESULT_READY"
      {|{"toolStreamScope":2,"toolCallBlockIndex":2,"executionId":"exec-read"}|} in
  check_phase "the matching tool result clears the tool activity" Phase_awaiting_turn settled;
  let quarantined = custom tool "KEEPER_STREAM_PROTOCOL_ERROR"
      {|{"kind":"sse_stream_incomplete","quarantined_occurrence":{"toolStreamScope":2,"toolCallBlockIndex":2}}|} in
  check_phase "a quarantined tool occurrence is no longer pending" Phase_awaiting_turn quarantined;
  let retry =
    apply args_ended
      (Wire_fleet.Chunk_runtime_attempt_started
         { operation_id = None; runtime_id = None; attempt_index = None })
  in
  check_phase "retry retires pending tools from the previous attempt" Phase_awaiting_turn retry

let test_active_turn_preview_visibility_and_queued_followup () =
  let keeper = "e-masc-the-leader" in
  let hist_page : Wire_fleet.chat_history_page =
    {
      messages =
        [
          {
            id = "hist-1";
            role = Wire_fleet.Role_assistant;
            content = "Previous turn summary";
            ts_unix = 1795498418.0;
            turn_ref = Some "trace-1#15204";
            model_used = None;
            tool_call_id = None;
            tool_call_name = None;
            execution_id = None;
            provenance = None;
            failure_kind = None;
            thinking = None;
            retained_images = [];
          };
        ];
      has_more = false;
      next_cursor = None;
    }
  in
  let active_preview_waiting : Wire_fleet.turn_preview =
    {
      status_text =
        "ollama · waiting for provider response · last observed tool: Execute";
      activity = Wire_fleet.Preview_waiting;
      text_tail = "";
      last_tool = Some "Execute";
      updated_at_unix = 1795503086.0;
      revision = None;
      preparation = None;
      work_context = None;
    }
  in
  let active_turn_no_tail : Wire_fleet.active_turn =
    {
      lane = Wire_fleet.Lane_proactive;
      turn_ref = Some "trace-1#15206";
      started_at_unix = 1795503055.0;
      interrupt_token = "itok-auto-15206";
      phase = None;
      tool_in_flight = None;
      elapsed_ms = None;
      preview_observed_through = None;
      preview = Some active_preview_waiting;
    }
  in
  let turn_row_of turn : Wire_fleet.keeper_turn_row =
    {
      keeper_name = keeper;
      chat_control_token = Some "ctrl-tok-1";
      state = Wire_fleet.Turn_active turn;
    }
  in
  let m0 =
    let base = Model.initial ~cols:120 ~rows:36 () in
    {
      base with
      nav =
        {
          base.nav with
          workspace = Nav.Keepers;
          dive_stack =
            [ Nav.Dive_keeper { name = keeper; tab = Nav.Keeper_chat } ];
        };
      fleet =
        base.fleet
        |> Fleet_store.apply_chat_history ~observed_at:t0 ~keeper hist_page
        |> Fleet_store.apply_turns ~observed_at:t0
             [ turn_row_of active_turn_no_tail ];
      drafts =
        base.drafts |> Drafts.set_active_keeper keeper |> Drafts.set_focus true;
    }
  in
  (* 1. Autonomous running turn without queued messages projects Phase_turn_running
     and Section_active_turn, without hijacking Esc away from Dive_keeper back. *)
  let phase0 = Chat_transcript.live_chat_phase ~model:m0 ~keeper in
  Alcotest.(check bool) "running autonomous turn reports Phase_turn_running" true
    (Chat_transcript.equal_live_chat_phase phase0
       (Chat_transcript.Phase_turn_running
          { turn = active_turn_no_tail; queued_count = 0 }));
  Alcotest.(check bool)
    "autonomous Phase_turn_running does not hijack Esc (is_phase_interruptible=false)"
    false
    (Chat_transcript.is_phase_interruptible phase0);
  let m0_esc, cmds_m0_esc =
    Update.step ~now:t0
      { m0 with drafts = Drafts.set_focus false m0.drafts }
      (Msg.Key_event (key Keymap.Input.Escape))
  in
  Alcotest.(check bool) "Esc during autonomous turn pops Dive_keeper cleanly"
    true
    (Option.is_none (Model.active_dive m0_esc));
  Alcotest.(check bool) "Esc during autonomous turn emits 0 interrupt POSTs" false
    (List.exists
       (function
         | Cmd.Http_post { req = Cmd.Post_keeper_turn_interrupt _; _ } -> true
         | _ -> false)
       (Cmd.flatten cmds_m0_esc));
  (* 2. Submitting a follow-up while autonomous turn runs queues the message,
     requests fresh Get_keeper_turns on Accepted_queued, and keeps the running
     turn visible ahead of the queued message. *)
  let m1, _ =
    Update.execute_action ~now:t0
      { m0 with drafts = Drafts.insert_text "go on" m0.drafts }
      Keymap.Submit_followup
  in
  let m_sending_esc, sending_esc_cmds =
    Update.step ~now:t0
      { m1 with drafts = Drafts.set_focus false m1.drafts }
      (Msg.Key_event (key Keymap.Input.Escape))
  in
  Alcotest.(check bool) "Esc leaves chat before the follow-up is accepted" true
    (Option.is_none (Model.active_dive m_sending_esc));
  Alcotest.(check bool) "Esc before acceptance sends no turn interrupt" false
    (List.exists
       (function
         | Cmd.Http_post { req = Cmd.Post_keeper_turn_interrupt _; _ } -> true
         | _ -> false)
       (Cmd.flatten sending_esc_cmds));
  let sending_maintenance =
    {
      m1 with
      drafts = Drafts.set_focus false m1.drafts;
      fleet =
        Fleet_store.apply_turns ~observed_at:t0
          [ turn_row_of { active_turn_no_tail with lane = Wire_fleet.Lane_maintenance } ]
          m1.fleet;
    }
  in
  let _, maintenance_cmds =
    Update.step ~now:t0 sending_maintenance (Msg.Key_event (char_key ~ctrl:true "x"))
  in
  Alcotest.(check bool) "a sending follow-up cannot make a maintenance turn interruptible"
    false
    (List.exists
       (function
         | Cmd.Http_post { req = Cmd.Post_keeper_turn_interrupt _; _ } -> true
         | _ -> false)
       (Cmd.flatten maintenance_cmds));
  let tx_q =
    match Drafts.active_tx_for_keeper ~keeper m1.drafts with
    | Some tx -> tx
    | None -> Alcotest.fail "expected queued follow-up tx"
  in
  let m2, cmds_acc =
    Update.step ~now:t1 m1
      (Msg.Chat_stream_chunk
         {
           epoch = m1.epoch;
           keeper;
           request_id = tx_q.request_id;
           is_btw = false;
           chunk =
             Wire_fleet.Chunk_accepted
               {
                 operation_id = tx_q.request_id;
                 queued_count = 1;
                 state = Keeper_chat_operation.State_name.Queued;
                 interactive_outcome = None;
                 control_token = None;
               };
         })
  in
  Alcotest.(check bool) "Accepted_queued refreshes Get_keeper_turns" true
    (List.exists
       (function
         | Cmd.Http_get { req = Cmd.Get_keeper_turns; _ } -> true
         | _ -> false)
       (Cmd.flatten cmds_acc));
  let phase2 = Chat_transcript.live_chat_phase ~model:m2 ~keeper in
  Alcotest.(check bool)
    "queued follow-up behind active turn keeps Phase_turn_running with queued_count=1"
    true
    (Chat_transcript.equal_live_chat_phase phase2
       (Chat_transcript.Phase_turn_running
          { turn = active_turn_no_tail; queued_count = 1 }));
  (* Esc while queued behind an autonomous turn still pops Dive_keeper cleanly. *)
  let m2_esc, cmds_m2_esc =
    Update.step ~now:t1
      { m2 with drafts = Drafts.set_focus false m2.drafts }
      (Msg.Key_event (key Keymap.Input.Escape))
  in
  Alcotest.(check bool) "Esc while queued behind active turn pops Dive_keeper"
    true
    (Option.is_none (Model.active_dive m2_esc));
  Alcotest.(check bool) "Esc while queued behind active turn emits 0 interrupts"
    false
    (List.exists
       (function
         | Cmd.Http_post { req = Cmd.Post_keeper_turn_interrupt _; _ } -> true
         | _ -> false)
       (Cmd.flatten cmds_m2_esc));
  Alcotest.(check bool) "Esc preserves the queued follow-up" true
    (match Drafts.active_tx_for_keeper ~keeper m2_esc.drafts with
    | Some tx -> Drafts.equal_tx_state tx.state Drafts.Queued
    | None -> false);
  (* 2c. An inactive stale stream (active = false) does not suppress Section_active_turn. *)
  let m2_stale_stream =
    let stale_buf : Fleet_store.chat_stream_buffer =
      {
        request_id = "old-req-0";
        operation_id = Some "old-req-0";
        turn_ref = None;
        run_started = true;
        interrupting = false;
        text = "Earlier unpersisted reply";
        text_ownership = Cut_reply.fresh_ownership;
        thinking = "";
        model_activity = Fleet_store.empty_model_activity;
        response_start = None;
        tools = [];
        active_runtime_id = None;
        attempt_index = None;
        retry_notice = None;
        checkpoint_notice = None;
        protocol_warning = None;
        active = false;
        ended = true;
        last_error = None;
      }
    in
    {
      m2 with
      fleet =
        {
          m2.fleet with
          chat_streams =
            Fleet_store.String_map.add keeper stale_buf m2.fleet.chat_streams;
        };
    }
  in
  Alcotest.(check bool) "stale inactive stream does not hide Section_active_turn"
    true
    (List.exists
       (function
         | Chat_transcript.Section_active_turn _ -> true
         | Chat_transcript.Section_history _
         | Chat_transcript.Section_pending _
         | Chat_transcript.Section_stream _ ->
             false)
       (Chat_transcript.project_transcript ~model:m2_stale_stream ~keeper));
  (* 4. Ctrl+X interrupts the running autonomous turn without corrupting the
     queued follow-up tx, enters Phase_interrupting, and deduplicates repeats. *)
  let m_unfocused = { m2 with drafts = Drafts.set_focus false m2.drafts } in
  let m_int, cmds_int =
    Update.step ~now:t1 m_unfocused (Msg.Key_event (char_key ~ctrl:true "x"))
  in
  Alcotest.(check bool) "Ctrl+X interrupts running turn by interrupt_token" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_keeper_turn_interrupt
                   { keeper = k; target = `Turn_token "itok-auto-15206" };
               _;
             }
           when String.equal k keeper ->
             true
         | _ -> false)
       (Cmd.flatten cmds_int));
  Alcotest.(check bool) "Ctrl+X transitions observed turn into Phase_interrupting"
    true
    (Chat_transcript.equal_live_chat_phase
       (Chat_transcript.live_chat_phase ~model:m_int ~keeper)
       Chat_transcript.Phase_interrupting);
  Alcotest.(check bool) "Ctrl+X keeps queued follow-up tx intact in Queued" true
    (match Drafts.active_tx_for_keeper ~keeper m_int.drafts with
    | Some { state = Drafts.Queued; _ } -> true
    | Some _ | None -> false);
  let _, cmds_int_dup =
    Update.step ~now:t1 m_int (Msg.Key_event (char_key ~ctrl:true "x"))
  in
  Alcotest.(check bool) "Repeated Ctrl+X while interrupting emits 0 duplicate POSTs"
    false
    (List.exists
       (function
         | Cmd.Http_post { req = Cmd.Post_keeper_turn_interrupt _; _ } -> true
         | _ -> false)
       (Cmd.flatten cmds_int_dup));
  (* 4b. Maintenance turns cannot be interrupted via Ctrl+X. *)
  let maint_turn =
    { active_turn_no_tail with lane = Wire_fleet.Lane_maintenance }
  in
  let m_maint =
    {
      m_unfocused with
      fleet =
        Fleet_store.apply_turns ~observed_at:t1 [ turn_row_of maint_turn ]
          m_unfocused.fleet;
    }
  in
  let _, cmds_maint =
    Update.step ~now:t1 m_maint (Msg.Key_event (char_key ~ctrl:true "x"))
  in
  Alcotest.(check bool) "Ctrl+X refuses to interrupt Lane_maintenance" false
    (List.exists
       (function
         | Cmd.Http_post { req = Cmd.Post_keeper_turn_interrupt _; _ } -> true
         | _ -> false)
       (Cmd.flatten cmds_maint));
  (* 5. Roster refresh (apply_keepers with active_turn = None) preserves overlaid
     active_turn from fleet.turns and reflects it in keeper_live_state/counts. *)
  let roster_row : Wire_fleet.keeper_summary =
    {
      name = keeper;
      group = Some "core";
      company = "core";
      health = Wire_fleet.Keeper_healthy;
      paused = false;
      keepalive_running = true;
      activation_mode = Wire_fleet.Activation_autonomous;
      runtime_id = "ollama";
      model_id = Some "deepseek";
      current_task_id = None;
      context = Observed.unreported;
      total_turns = Observed.unreported;
      last_turn_at_unix = None;
      active_turn = None;
    }
  in
  let fleet_after_roster =
    Fleet_store.apply_keepers ~observed_at:t1 [ roster_row ] m0.fleet
  in
  let refreshed_k =
    match Fleet_store.find_keeper ~name:keeper fleet_after_roster with
    | Some k -> k
    | None -> Alcotest.fail "keeper missing after apply_keepers"
  in
  Alcotest.(check bool) "apply_keepers overlays active_turn from fleet.turns"
    true
    (Option.is_some refreshed_k.active_turn);
  Alcotest.(check bool) "healthy keeper with active_turn reports Health.Working"
    true
    (match Fleet_store.keeper_live_state refreshed_k with
    | Health.Working _ -> true
    | Health.Healthy
    | Health.Needs_attention _
    | Health.Degraded _
    | Health.Down _
    | Health.Idle ->
        false);
  let hc = Fleet_store.fleet_health_counts [ refreshed_k ] in
  Alcotest.(check int) "fleet_health_counts counts healthy+active_turn as working"
    1 hc.working;
  (* 6. Keeper_turn_changed SSE during Dive_keeper refreshes only for the viewed
     keeper (ignoring preview_only churn from unrelated keepers). *)
  let m_work_dive =
    { m0 with nav = { m0.nav with workspace = Nav.Work } }
  in
  let _, cmds_sse_same =
    Update.step ~now:t1 m_work_dive
      (Msg.Sse_event
         {
           epoch = m_work_dive.epoch;
           event =
             Msg.Sse_observer_delivery
               {
                 cursor = None;
                 decoded =
                   Wire_observer.Event
                     (Wire_observer.Keeper_turn_changed
                        { keeper; preview_only = true });
               };
         })
  in
  Alcotest.(check bool)
    "Keeper_turn_changed refreshes Get_keeper_turns for viewed keeper on Nav.Work"
    true
    (List.exists
       (function
         | Cmd.Http_get { req = Cmd.Get_keeper_turns; _ } -> true
         | _ -> false)
       (Cmd.flatten cmds_sse_same));
  let _, cmds_sse_other =
    Update.step ~now:t1 m_work_dive
      (Msg.Sse_event
         {
           epoch = m_work_dive.epoch;
           event =
             Msg.Sse_observer_delivery
               {
                 cursor = None;
                 decoded =
                   Wire_observer.Event
                     (Wire_observer.Keeper_turn_changed
                        { keeper = "unrelated-keeper"; preview_only = true });
               };
         })
  in
  Alcotest.(check bool)
    "Keeper_turn_changed ignores unrelated keeper preview churn in Dive_keeper"
    false
    (List.exists
       (function
         | Cmd.Http_get { req = Cmd.Get_keeper_turns; _ } -> true
         | _ -> false)
       (Cmd.flatten cmds_sse_other));
  let m_queue =
    { m0 with
      drafts = Drafts.set_active_keeper keeper m0.drafts;
      nav =
        { m0.nav with
          workspace = Nav.Knowledge;
          dive_stack = [];
          overlay = Some (Nav.Queue_context Nav.Drawer_queue);
        };
    }
  in
  let queue_event event =
    let _, cmds =
      Update.step ~now:t1 m_queue
        (Msg.Sse_event
           {
             epoch = m_queue.epoch;
             event =
               Msg.Sse_observer_delivery
                 { cursor = None; decoded = Wire_observer.Event event };
           })
    in
    Cmd.flatten cmds
  in
  let queue_fetches_turns keeper =
    queue_event (Wire_observer.Keeper_turn_changed { keeper; preview_only = true })
    |> List.exists (function
         | Cmd.Http_get { req = Cmd.Get_keeper_turns; _ } -> true
         | _ -> false)
  in
  Alcotest.(check bool) "queue refreshes the selected Keeper outside Fleet"
    true (queue_fetches_turns keeper);
  Alcotest.(check bool) "queue ignores unrelated Keeper previews"
    false (queue_fetches_turns "unrelated-keeper");
  Alcotest.(check bool) "queue refreshes Task and Goal observations outside Work"
    true
    (queue_event (Wire_observer.Dataset_changed Wire_observer.Dataset_backlog)
     |> List.exists (function
          | Cmd.Http_get { req = Cmd.Get_planning; _ } -> true
          | _ -> false));
  (* 8. Submitting while busy preserves a prior unpersisted stream buffer (tools/text)
     instead of wiping it with start_chat_stream. *)
  let prior_tool_buf : Fleet_store.chat_stream_buffer =
    {
      request_id = "prior-req";
      operation_id = Some "prior-req";
      turn_ref = None;
      run_started = true;
      interrupting = false;
      text = "Prior streamed answer";
      text_ownership = Cut_reply.fresh_ownership;
      thinking = "";
      model_activity = Fleet_store.empty_model_activity;
      response_start = None;
      tools =
        [
          {
            tool_use_id = "tu-1";
            stream_scope = None;
            tool_name = "Read";
            args_preview = Some "README.md";
            progress_label = None;
            tool_state = Tool_settled;
            ok = Some true;
            output_preview = None;
          };
        ];
      active_runtime_id = None;
      attempt_index = None;
      retry_notice = None;
      checkpoint_notice = None;
      protocol_warning = None;
      active = false;
      ended = true;
      last_error = None;
    }
  in
  let m0_with_prior =
    {
      m0 with
      fleet =
        {
          m0.fleet with
          chat_streams =
            Fleet_store.String_map.add keeper prior_tool_buf m0.fleet.chat_streams;
        };
      drafts = Drafts.insert_text "go on" m0.drafts;
    }
  in
  let m_busy_sent, _ =
    Update.execute_action ~now:t1 m0_with_prior Keymap.Submit_followup
  in
  let kept_buf = Fleet_store.String_map.find keeper m_busy_sent.fleet.chat_streams in
  Alcotest.(check string)
    "submitting while busy preserves prior stream buffer request_id"
    "prior-req" kept_buf.request_id;
  Alcotest.(check int)
    "submitting while busy preserves prior stream tool cards"
    1 (List.length kept_buf.tools);
  (* Completed tools leave the active stream waiting for the response. *)
  let tool_done_active : Fleet_store.chat_stream_buffer =
    { prior_tool_buf with text = ""; active = true; ended = false }
  in
  let m_stream_wait =
    {
      m0 with
      fleet =
        {
          m0.fleet with
          turns = Observed.value ~observed_at:t1 [];
          chat_streams =
            Fleet_store.String_map.add keeper tool_done_active
              m0.fleet.chat_streams;
        };
    }
  in
  Alcotest.(check bool) "active stream with settled tools awaits the response"
    true
    (Chat_transcript.equal_live_chat_phase
       (Chat_transcript.live_chat_phase ~model:m_stream_wait ~keeper)
       Chat_transcript.Phase_awaiting_turn);
  (* 10. Accepted_running emits Get_keeper_turns for live preview during wait. *)
  let _, cmds_acc_run =
    Update.step ~now:t1 m1
      (Msg.Chat_stream_chunk
         {
           epoch = m1.epoch;
           keeper;
           request_id = tx_q.request_id;
           is_btw = false;
           chunk =
             Wire_fleet.Chunk_accepted
               {
                 operation_id = tx_q.request_id;
                 queued_count = 0;
                 state = Keeper_chat_operation.State_name.Running;
                 interactive_outcome = None;
                 control_token = None;
               };
         })
  in
  Alcotest.(check bool) "Accepted_running refreshes Get_keeper_turns" true
    (List.exists
       (function
         | Cmd.Http_get { req = Cmd.Get_keeper_turns; _ } -> true
         | _ -> false)
       (Cmd.flatten cmds_acc_run));
  let m_orphan_modal =
    {
      m0 with
      nav =
        {
          m0.nav with
          overlay = Some (Nav.Inline_action Nav.Board_new_post);
        };
      inline_modal = None;
    }
  in
  let m_escaped, _ =
    Update.step ~now:t1 m_orphan_modal (Msg.Key_event (key Keymap.Input.Escape))
  in
  Alcotest.(check bool) "Esc closes orphaned Inline_action overlay" true
    (Option.is_none m_escaped.nav.overlay)

let test_turn_preview_updates_keep_owner_and_skip_fleet_reads () =
  let keeper = "alpha" in
  let base = Model.initial () in
  let base =
    { base with nav = { base.nav with workspace = Nav.Keepers };
      server_identity =
        { base.server_identity with observer_instance_id = Some "before-restart" } }
  in
  let frame model json =
    let delivery =
      Wire_observer.decode_frame
        { id = None; data = Yojson.Safe.to_string json }
    in
    Update.step ~now:t1 model
      (Msg.Sse_event
         { epoch = model.epoch; event = Msg.Sse_observer_delivery delivery })
  in
  let preview revision text : Wire_fleet.turn_preview =
    { status_text = "streaming"; activity = Preview_streaming; text_tail = text;
      last_tool = None; updated_at_unix = 100.0; revision = Some revision;
      preparation = None; work_context = None }
  in
  let row ~keeper_name ~token ~ref_id ~revision ~text : Wire_fleet.keeper_turn_row =
    { keeper_name; chat_control_token = Some (keeper_name ^ "-control");
      state =
        Turn_active
          { lane = Lane_proactive; turn_ref = Some ref_id; started_at_unix = 90.0;
            interrupt_token = token; phase = None; tool_in_flight = None;
            elapsed_ms = None; preview_observed_through = Some revision;
            preview = Some (preview revision text) } }
  in
  let missing_preview (turn_row : Wire_fleet.keeper_turn_row) revision =
    match turn_row.state with
    | Turn_active turn ->
        { turn_row with
          state = Turn_active { turn with preview = None;
                                 preview_observed_through = Some revision } }
    | Turn_idle | Turn_unavailable _ -> Alcotest.fail "expected an active turn fixture"
  in
  let send_preview model ~owner_key ~revision ~text =
    frame model
      (`Assoc [
         "type", `String "keeper_turn_preview_changed";
         "name", `String keeper;
         "observation", `Assoc [
           "owner_key", `String owner_key;
           "preview", `Assoc [
             "status_text", `String "streaming"; "activity", `String "streaming";
             "text_tail", `String text; "last_tool", `Null;
             "updated_at_unix", `Float 100.0; "revision", `Int revision;
             "preparation", `Null
           ]
         ]
      ])
  in
  let update model ~token ~revision ~text =
    let owner_key = Digest.BLAKE256.(to_hex (string token)) in
    send_preview model ~owner_key ~revision ~text
  in
  let reply model rows =
    fst
      (Update.step ~now:t2 model
         (Msg.Http_reply { epoch = model.epoch; reply = Msg.Reply_keeper_turns (Ok rows) }))
  in
  let active model name = Fleet_store.active_turn_for ~keeper:name model.Model.fleet in
  let check_preview label expected model name =
    Alcotest.(check (option string)) label expected
      (Option.bind (active model name)
         (fun turn -> Option.map (fun p -> p.Wire_fleet.text_tail) turn.preview))
  in
  let has_fleet_read cmds =
    List.exists
      (function Cmd.Http_get { req = Cmd.Get_keeper_turns; _ } -> true | _ -> false)
      (Cmd.flatten cmds)
  in
  let a = row ~keeper_name:keeper ~token:"first-owner" ~ref_id:"trace#1"
      ~revision:8 ~text:"earlier response" in
  let other = row ~keeper_name:"beta" ~token:"other-owner" ~ref_id:"trace#3"
      ~revision:2 ~text:"other keeper" in
  let pending, cmds =
    update base ~token:"first-owner" ~revision:9 ~text:"new response"
  in
  Alcotest.(check bool) "preview asks for no fleet read" false (has_fleet_read cmds);
  check_preview "preview cannot manufacture a running slot" None pending keeper;
  let running = reply pending [ a; other ] in
  check_preview "initial snapshot can join an earlier-arriving preview"
    (Some "new response") running keeper;
  Alcotest.(check (option string)) "the preview preserves the authoritative turn reference"
    (Some "trace#1") (Option.bind (active running keeper) (fun turn -> turn.turn_ref));
  check_preview "other keeper keeps its own preview" (Some "other keeper") running "beta";
  check_preview "a missing preview observed earlier cannot erase the event"
    (Some "new response") (reply running [ missing_preview a 8; other ]) keeper;
  let withdrawn = reply running [ missing_preview a 10; other ] in
  check_preview "a newer missing preview withdraws the previous text" None withdrawn keeper;
  check_preview "a delayed response cannot bring back withdrawn text"
    None (reply withdrawn [ a; other ]) keeper;
  let running, malformed_cmds =
    send_preview running ~owner_key:"invalid" ~revision:9000 ~text:"malformed response"
  in
  Alcotest.(check bool) "malformed preview asks for no fleet read" false
    (has_fleet_read malformed_cmds);
  let next, cmds =
    update running ~token:"second-owner" ~revision:11 ~text:"second owner response"
  in
  Alcotest.(check bool) "new-owner preview leaves lifecycle reads to lifecycle events"
    false (has_fleet_read cmds);
  let delayed = reply next [ a; other ] in
  check_preview "delayed old-owner reply does not borrow or lose the owner's preview"
    (Some "new response") delayed keeper;
  let delayed, cmds =
    frame delayed
      (`Assoc [ "type", `String "keeper_turn_changed"; "name", `String keeper ])
  in
  Alcotest.(check bool) "owner change still requests the authoritative snapshot"
    true (has_fleet_read cmds);
  let _, gap_cmds = Update.step ~now:t2 delayed (Msg.Stream_gap 1) in
  Alcotest.(check bool) "a lost lifecycle event requests a snapshot in the visible view"
    true (has_fleet_read gap_cmds);
  let hidden = { delayed with nav = { delayed.nav with workspace = Nav.Knowledge } } in
  let _, hidden_gap_cmds = Update.step ~now:t2 hidden (Msg.Stream_gap 1) in
  Alcotest.(check bool) "the background fleet waits until its view is opened"
    false (has_fleet_read hidden_gap_cmds);
  let b = row ~keeper_name:keeper ~token:"second-owner" ~ref_id:"trace#2"
      ~revision:10 ~text:"earlier second response" in
  let next = reply delayed [ b; other ] in
  check_preview "malformed observation did not block the next owner's earlier preview"
    (Some "second owner response") next keeper;
  let stale_event, _ =
    update next ~token:"first-owner" ~revision:9 ~text:"late old event"
  in
  check_preview "late old-owner observation leaves current owner alone"
    (Some "second owner response") stale_event keeper;
  let idle = reply stale_event [ { b with state = Turn_idle }; other ] in
  check_preview "terminal snapshot withdraws the preview" None idle keeper;
  Alcotest.(check (option string)) "control token still comes from the snapshot"
    (Some "alpha-control") (Fleet_store.chat_control_token_for ~keeper idle.fleet);
  let after_restart = row ~keeper_name:keeper ~token:"restarted-owner" ~ref_id:"trace#4"
      ~revision:1 ~text:"after restart" in
  let check_restart label message =
    let reset, _ = Update.step ~now:t2 idle message in
    let fresh, cmds =
      update (reply reset [ after_restart ]) ~token:"restarted-owner"
        ~revision:2 ~text:"new process preview"
    in
    Alcotest.(check bool) "new process preview still needs no fleet read" false
      (has_fleet_read cmds);
    check_preview label (Some "new process preview") fresh keeper
  in
  let reconnect ~handshake ~needs_cold_resync =
    Msg.Sse_event
      { epoch = idle.epoch;
        event = Msg.Sse_observer_handshake
          { handshake; identity = None; needs_cold_resync } }
  in
  check_restart "cold reconnect retires the old process revision"
    (reconnect ~handshake:None ~needs_cold_resync:true);
  check_restart "a fresh observer instance retires the old process revision"
    (reconnect ~handshake:(Some { instance_id = "after-restart"; replay = Fresh })
       ~needs_cold_resync:false);
  check_restart "a new server epoch retires the old process revision"
    (Msg.Server_start_result (Ok ()))

let test_interrupt_reply_and_stream_completion_are_request_scoped () =
  let keeper = "alpha-leader" in
  let m_chat_run =
    let base = Model.initial ~cols:120 ~rows:36 () in
    let base =
      {
        base with
        nav =
          {
            base.nav with
            workspace = Nav.Keepers;
            dive_stack =
              [ Nav.Dive_keeper { name = keeper; tab = Nav.Keeper_chat } ];
          };
        drafts =
          base.drafts |> Drafts.set_active_keeper keeper
          |> Drafts.insert_text "hello" |> Drafts.set_focus false;
      }
    in
    let m_sub, _ = Update.execute_action ~now:t0 base Keymap.Submit_steer in
    let tx_s =
      match Drafts.active_tx_for_keeper ~keeper m_sub.drafts with
      | Some tx -> tx
      | None -> Alcotest.fail "missing submitted tx"
    in
    let m_acc, _ =
      Update.step ~now:t0 m_sub
        (Msg.Chat_stream_chunk
           {
             epoch = m_sub.epoch;
             keeper;
             request_id = tx_s.request_id;
             is_btw = false;
             chunk =
               Wire_fleet.Chunk_accepted
                 {
                   operation_id = tx_s.request_id;
                   queued_count = 0;
                   state = Keeper_chat_operation.State_name.Running;
                   interactive_outcome = None;
                   control_token = None;
                 };
           })
    in
    m_acc
  in
  let m_esc_int, interrupt_cmds =
    Update.step ~now:t1 m_chat_run (Msg.Key_event (key Keymap.Input.Escape))
  in
  let target =
    match List.find_map
      (function
        | Cmd.Http_post { req = Cmd.Post_keeper_turn_interrupt { target; _ }; _ } ->
            Some target
        | _ -> None)
      (Cmd.flatten interrupt_cmds)
    with
    | Some target -> target
    | None -> Alcotest.fail "expected an operation interrupt"
  in
  let stream model =
    Fleet_store.String_map.find keeper model.Model.fleet.chat_streams
  in
  let request_id = (stream m_esc_int).request_id in
  Alcotest.(check bool) "Esc targets this chat operation" true
    (match target with
    | `Operation_id id -> String.equal id request_id
    | `Turn_token _ -> false);
  Alcotest.(check bool) "Esc marks the operation as interrupting" true
    (stream m_esc_int).interrupting;
  let reply_to target result model =
    Update.step ~now:t2 model
      (Msg.Http_reply
         { epoch = model.Model.epoch; reply = Msg.Reply_turn_interrupt { keeper; target; result } })
  in
  let m_late_reply, _ =
    reply_to (`Operation_id "earlier-operation")
      (Error (Msg.Transport (Health.Other_io "connection closed"))) m_esc_int
  in
  Alcotest.(check bool) "an earlier POST error leaves this operation interrupting"
    true (stream m_late_reply).interrupting;
  let m_paused, _ =
    reply_to target
      (Ok
         {
           signalled = false;
           paused = true;
           chat_control_token = None;
           reason = Some "paused_pending_admission";
         })
      m_esc_int
  in
  Alcotest.(check bool) "the matching pause receipt releases the interrupt"
    false (stream m_paused).interrupting;
  Alcotest.(check bool) "a pause receipt preserves the accepted draft" true
    (match Drafts.active_tx_for_keeper ~keeper m_paused.drafts with
    | Some tx -> Drafts.equal_tx_state tx.state Drafts.Pending_processing
    | None -> false);
  let m_idle, _ =
    Update.step ~now:t2 m_esc_int
      (Msg.Http_reply
         {
           epoch = m_esc_int.epoch;
           reply =
             Msg.Reply_keeper_turns
               (Ok
                  [
                    {
                      keeper_name = keeper;
                      chat_control_token = None;
                      state = Wire_fleet.Turn_idle;
                    };
                  ]);
         })
  in
  Alcotest.(check bool) "an idle Owner observation cannot close this chat stream"
    false (stream m_idle).ended;
  Alcotest.(check bool) "the draft awaits completion of its own stream" true
    (match Drafts.active_tx_for_keeper ~keeper m_idle.drafts with
    | Some tx -> Drafts.equal_tx_state tx.state Drafts.Interrupting
    | None -> false);
  let m_delta, _ =
    Update.step ~now:t2 m_idle
      (Msg.Chat_stream_chunk
         {
           epoch = m_idle.epoch;
           keeper;
           request_id;
           is_btw = false;
           chunk =
             Wire_fleet.Chunk_text_delta
               {
                 operation_id = Some request_id;
                 delta = "response in transit";
                 owner = Wire_chat_journal.Unobserved_scope None;
               };
         })
  in
  Alcotest.(check string) "the stream still admits this operation's in-flight data"
    "response in transit" (stream m_delta).text;
  let m_completed, completion_cmds =
    Update.step ~now:t2 m_delta
      (Msg.Chat_stream_done
         { epoch = m_delta.epoch; keeper; request_id; is_btw = false; result = Ok () })
  in
  Alcotest.(check bool) "the matching stream completion clears the interrupt"
    false (stream m_completed).interrupting;
  Alcotest.(check bool) "the matching stream completion reconciles the draft" true
    (match Drafts.active_tx_for_keeper ~keeper m_completed.drafts with
    | Some tx -> Drafts.equal_tx_state tx.state Drafts.Confirming_delivery
    | None -> false);
  Alcotest.(check bool) "the completion requests persisted chat history" true
    (List.exists
       (function
         | Cmd.Http_get { req = Cmd.Get_chat_history { keeper = name; _ }; _ } ->
             String.equal name keeper
         | _ -> false)
       (Cmd.flatten completion_cmds));
  let escaped, cmds =
    Update.step ~now:t2 m_esc_int (Msg.Key_event (key Keymap.Input.Escape))
  in
  Alcotest.(check bool) "Esc already awaiting an interrupt leaves chat" true
    (Option.is_none (Model.active_dive escaped));
  Alcotest.(check bool) "leaving an interrupting chat sends no second interrupt"
    false
    (List.exists
       (function
         | Cmd.Http_post { req = Cmd.Post_keeper_turn_interrupt _; _ } -> true
         | _ -> false)
       (Cmd.flatten cmds));
  let m_submitted, _ =
    Update.execute_action ~now:t2
      { m_esc_int with drafts = Drafts.insert_text "next request" m_esc_int.drafts }
      Keymap.Submit_followup
  in
  let new_request_id =
    match List.find_opt
      (fun (tx : Drafts.pending_message) -> not (String.equal tx.request_id request_id))
      (Drafts.pending_txs_for_keeper ~keeper m_submitted.drafts)
    with
    | Some tx -> tx.request_id
    | None -> Alcotest.fail "missing second request"
  in
  let m_second_running, _ =
    Update.step ~now:t2 m_submitted
      (Msg.Chat_stream_chunk
         {
           epoch = m_submitted.epoch;
           keeper;
           request_id = new_request_id;
           is_btw = false;
           chunk =
             Wire_fleet.Chunk_accepted
               {
                 operation_id = new_request_id;
                 queued_count = 0;
                 state = Keeper_chat_operation.State_name.Running;
                 interactive_outcome = None;
                 control_token = Some "newer-control";
               };
         })
  in
  let m_second_interrupt, second_cmds =
    Update.step ~now:t2 m_second_running (Msg.Key_event (char_key ~ctrl:true "x"))
  in
  Alcotest.(check bool) "the new local stream supplies the running phase"
    true
    (Chat_transcript.equal_live_chat_phase
       (Chat_transcript.live_chat_phase ~model:m_second_running ~keeper)
       Chat_transcript.Phase_awaiting_turn);
  Alcotest.(check bool) "an earlier pending interruption cannot block the current target"
    true
    (List.exists
       (function
         | Cmd.Http_post
             { req = Cmd.Post_keeper_turn_interrupt { target = `Operation_id id; _ }; _ } ->
             String.equal id new_request_id
         | _ -> false)
       (Cmd.flatten second_cmds));
  let m_after_old_receipt, _ =
    reply_to target
      (Ok
         {
           signalled = false;
           paused = false;
           chat_control_token = Some "older-control";
           reason = Some "operation_not_current";
         })
      m_second_interrupt
  in
  Alcotest.(check bool) "the older result leaves the new stream interrupting"
    true (stream m_after_old_receipt).interrupting;
  Alcotest.(check (option string)) "the older result cannot replace the new control token"
    (Some "newer-control")
    (Fleet_store.chat_control_token_for ~keeper m_after_old_receipt.fleet)

let test_timeout_detail_retryable_and_update_parity () =
  let cases =
    [
      ( Health.Timeout_connect
      , Some 5.0
      , Some "/api/v1/dashboard/tools"
      , "연결 시간 초과 (5.0s · /api/v1/dashboard/tools)"
      , "Connect timed out (5.0s · /api/v1/dashboard/tools)" );
      ( Health.Timeout_connect_cooldown
      , Some 5.0
      , Some "/api/v1/infra/sandboxes"
      , "연결 쿨다운 대기 중 (5.0s · /api/v1/infra/sandboxes)"
      , "Connect cooldown active (5.0s · /api/v1/infra/sandboxes)" );
      ( Health.Timeout_response
      , Some 30.0
      , Some "/api/v1/dashboard/tools"
      , "응답 시간 초과 (30.0s · /api/v1/dashboard/tools)"
      , "Response timed out (30.0s · /api/v1/dashboard/tools)" );
      ( Health.Timeout_stream_header
      , Some 45.0
      , Some "/api/v1/keepers/chat/stream"
      , "스트림 응답 대기 초과 (45.0s · /api/v1/keepers/chat/stream)"
      , "Stream header timed out (45.0s · /api/v1/keepers/chat/stream)" );
      ( Health.Timeout_stream_idle
      , Some 120.0
      , Some "/mcp"
      , "스트림 유휴 시간 초과 (120.0s · /mcp)"
      , "Stream idle timed out (120.0s · /mcp)" );
    ]
  in
  Alcotest.(check bool) "legacy Timeout retryable" true
    (Msg.http_error_retryable (Msg.Transport Health.Timeout));
  List.iter
    (fun (phase, after_sec, path, exp_ko, exp_en) ->
      let err =
        Msg.Transport (Health.Timeout_detail { phase; after_sec; path })
      in
      Alcotest.(check bool) ("retryable: " ^ exp_en) true
        (Msg.http_error_retryable err);
      let summary = Msg.http_error_summary err in
      Alcotest.(check string) ("summary KO: " ^ exp_ko) exp_ko
        (Say.resolve Say.Lang_ko summary);
      Alcotest.(check string) ("summary EN: " ^ exp_en) exp_en
        (Say.resolve Say.Lang_en summary);
      Alcotest.(check string) ("detail EN: " ^ exp_en) exp_en
        (Msg.http_error_detail err))
    cases;
  (* Update.ml: Server_health_result treats Timeout_detail identically to Timeout
     (does not mark server_offline or trigger Start_local_server, records incident) *)
  let m0 = Model.initial () in
  let td_err =
    Msg.Transport
      (Health.Timeout_detail
         {
           phase = Health.Timeout_response;
           after_sec = Some 12.0;
           path = Some "/health";
         })
  in
  let m_health, health_cmds =
    Update.step ~now:t0 m0
      (Msg.Server_health_result { epoch = m0.epoch; result = Error td_err })
  in
  Alcotest.(check bool) "health Timeout_detail does not mark server_offline"
    false m_health.freshness.server_offline;
  Alcotest.(check int) "health Timeout_detail emits no autostart cmd" 0
    (List.length health_cmds);
  Alcotest.(check int) "health Timeout_detail records 1 incident" 1
    (List.length m_health.incidents.entries);
  let inc = List.hd m_health.incidents.entries in
  Alcotest.(check string) "health incident detail preserves phase/sec/path"
    "Response timed out (12.0s · /health)" inc.detail;

  (* Update_http.ml: Reply_action_ack uses Msg.http_error_summary for Timeout_detail
     (identical to Health.Timeout, distinct from Health.Other_io which shows label) *)
  let action_err =
    Msg.Transport
      (Health.Timeout_detail
         {
           phase = Health.Timeout_response;
           after_sec = Some 30.0;
           path = Some "/api/v1/infra/sandboxes/probe";
         })
  in
  let m_ack, _ =
    Update.step ~now:t1 m0
      (Msg.Http_reply
         {
           epoch = m0.epoch;
           reply =
             Msg.Reply_action_ack
               {
                 label =
                   Say.make ~ko:"샌드박스 프로브 요청됨"
                     ~en:"Sandbox probe requested";
                 ack_scope = Msg.Ack_refresh_view;
                 for_modal = None;
                 result = Error action_err;
               };
         })
  in
  (match m_ack.toast with
  | None -> Alcotest.fail "expected error toast on Reply_action_ack Timeout_detail"
  | Some toast ->
      Alcotest.(check string) "toast KO shows Timeout_detail summary"
        "응답 시간 초과 (30.0s · /api/v1/infra/sandboxes/probe)"
        (Say.resolve Say.Lang_ko toast.message);
      Alcotest.(check string) "toast EN shows Timeout_detail summary"
        "Response timed out (30.0s · /api/v1/infra/sandboxes/probe)"
        (Say.resolve Say.Lang_en toast.message))

let test_lazy_keeper_context_fetches_and_sidebar_workspace_discovery () =
  let keeper = "alpha" in
  let tr_json =
    Yojson.Safe.from_string
      {|{
        "keeper": "alpha",
        "count": 1,
        "skipped_rows": 0,
        "health": "healthy",
        "live_turn_in_progress": false,
        "entries": [
          {
            "diff_vs_prev": null,
            "record": {
              "execution_ids": ["exec-900"],
              "keeper": "alpha",
              "agent_name": "alpha",
              "turn_kind": "direct",
              "trace_id": "tr-900",
              "absolute_turn": 90,
              "turn_ref": "tr-900#90",
              "blocks": [],
              "input_components": [],
              "request_observations": [],
              "runtime_profile": "claude-sonnet-4",
              "request_runtime_profile": "claude-sonnet-4",
              "request_body_bytes": 1200,
              "transmitted_atoms": null,
              "total_atoms": null,
              "model_input_measurement": null,
              "model_input_front": null,
              "response_observed_model_input": null,
              "refused_model_input": null,
              "raw_trace_run_ref": null,
              "selected_model": "claude-sonnet-4",
              "finish_reason": "end_turn",
              "context_window": 200000,
              "provider_context_window": 200000,
              "request_latency_ms": 120,
              "input_tokens": 1200,
              "cache_creation_input_tokens": 0,
              "cache_read_input_tokens": 1000,
              "output_tokens": 100,
              "usage_scope": "per_request",
              "input_provenance": "measured_request",
              "ts": 1795252000.0
            }
          }
        ]
      }|}
  in
  let tr_page =
    match Wire_keeper_context.decode_turn_records tr_json with
    | Ok p -> p
    | Error e -> Alcotest.fail ("decode_turn_records failed: " ^ e)
  in
  let base = Model.initial () in
  let kc =
    Keeper_context_store.empty
    |> Keeper_context_store.apply_turn_records ~observed_at:t1 ~keeper tr_page
  in
  let model_for_subtab subtab =
    {
      base with
      nav =
        {
          base.nav with
          workspace = Nav.Keepers;
          dive_stack = [ Nav.Dive_keeper { name = keeper; tab = Nav.Keeper_context } ];
        };
      keeper_context = Keeper_context_store.set_subtab ~keeper subtab kc;
    }
  in
  let has_get pred cmds =
    List.exists
      (function Cmd.Http_get { req; _ } -> pred req | _ -> false)
      (Cmd.flatten cmds)
  in
  let is_next_req = function Cmd.Get_keeper_next_request _ -> true | _ -> false in
  let is_provider_in = function Cmd.Get_keeper_provider_input _ -> true | _ -> false in
  let is_cache_out = function Cmd.Get_keeper_cache_outcome _ -> true | _ -> false in
  let is_transcript = function Cmd.Get_keeper_turn_transcript _ -> true | _ -> false in
  let is_tool_calls = function Cmd.Get_keeper_tool_calls _ -> true | _ -> false in
  (* 1. Default Ctx_composition fetches only next-request, not heavy per-turn scans *)
  let cmds_comp =
    View_fetches.fetches_for_current_view (model_for_subtab Keeper_context_store.Ctx_composition)
  in
  Alcotest.(check bool) "Ctx_composition requests next-request" true
    (has_get is_next_req cmds_comp);
  Alcotest.(check bool) "Ctx_composition skips provider-input" false
    (has_get is_provider_in cmds_comp);
  Alcotest.(check bool) "Ctx_composition skips cache-outcome" false
    (has_get is_cache_out cmds_comp);
  Alcotest.(check bool) "Ctx_composition skips turn-transcript" false
    (has_get is_transcript cmds_comp);
  Alcotest.(check bool) "Ctx_composition skips tool-calls" false
    (has_get is_tool_calls cmds_comp);
  (* 2. Ctx_exact_input fetches provider-input + cache-outcome only *)
  let cmds_exact =
    View_fetches.fetches_for_current_view (model_for_subtab Keeper_context_store.Ctx_exact_input)
  in
  Alcotest.(check bool) "Ctx_exact_input requests provider-input" true
    (has_get is_provider_in cmds_exact);
  Alcotest.(check bool) "Ctx_exact_input requests cache-outcome" true
    (has_get is_cache_out cmds_exact);
  Alcotest.(check bool) "Ctx_exact_input skips turn-transcript" false
    (has_get is_transcript cmds_exact);
  (* 3. Ctx_input_map fetches provider-input without cache-outcome or transcript *)
  let cmds_map =
    View_fetches.fetches_for_current_view (model_for_subtab Keeper_context_store.Ctx_input_map)
  in
  Alcotest.(check bool) "Ctx_input_map requests provider-input" true
    (has_get is_provider_in cmds_map);
  Alcotest.(check bool) "Ctx_input_map skips cache-outcome" false
    (has_get is_cache_out cmds_map);
  (* 4. Ctx_response fetches turn-transcript + tool-calls without provider-input/cache-outcome *)
  let cmds_resp =
    View_fetches.fetches_for_current_view (model_for_subtab Keeper_context_store.Ctx_response)
  in
  Alcotest.(check bool) "Ctx_response requests turn-transcript" true
    (has_get is_transcript cmds_resp);
  Alcotest.(check bool) "Ctx_response requests tool-calls" true
    (has_get is_tool_calls cmds_resp);
  Alcotest.(check bool) "Ctx_response skips provider-input" false
    (has_get is_provider_in cmds_resp);
  Alcotest.(check bool) "Ctx_response skips cache-outcome" false
    (has_get is_cache_out cmds_resp);
  (* 5. Ctrl+T Drawer_context still fetches next-request + cache-outcome without provider-input/transcript *)
  let m_dive, _ =
    Update_nav.push_dive
    {
      base with
        nav = { base.nav with workspace = Nav.Keepers };
      keeper_context = kc;
    }
      (Nav.Dive_keeper { name = keeper; tab = Nav.Keeper_chat })
  in
  let is_next_req_for k = function
    | Cmd.Get_keeper_next_request { keeper } -> String.equal keeper k
    | _ -> false
  in
  let is_cache_out_for k = function
    | Cmd.Get_keeper_cache_outcome { keeper; _ } -> String.equal keeper k
    | _ -> false
  in
  let _, cmds_drawer =
    Update_nav.open_overlay m_dive (Nav.Queue_context Nav.Drawer_context)
  in
  Alcotest.(check bool) "Drawer_context requests cache-outcome for Dive keeper alpha"
    true (has_get (is_cache_out_for keeper) cmds_drawer);
  Alcotest.(check bool) "Drawer_context requests next-request for Dive keeper alpha"
    true (has_get (is_next_req_for keeper) cmds_drawer);
  Alcotest.(check bool) "Drawer_context skips provider-input" false
    (has_get is_provider_in cmds_drawer);
  Alcotest.(check bool) "Drawer_context skips turn-transcript" false
    (has_get is_transcript cmds_drawer);
  (* 6. Sidebar overflow surfaces Infra & System sections when terminal height clips menu,
     and reaching bottom clears the below-overflow banner without snapping back *)
  Alcotest.(check bool) "sidebar reports overflow below on short terminal" true
    (Model.sidebar_has_below_overflow ~inner_h:20 ~start:0);
  let hidden_secs = Model.sidebar_hidden_below_sections ~inner_h:20 ~start:0 in
  Alcotest.(check bool) "Infra section reported in hidden-below overflow" true
    (List.exists (Nav.equal_menu_section Nav.Sec_infra) hidden_secs);
  Alcotest.(check bool) "System section reported in hidden-below overflow" true
    (List.exists (Nav.equal_menu_section Nav.Sec_system) hidden_secs);
  let total_rows = List.length Model.sidebar_visual_rows in
  let max_scroll = Int.max 0 (total_rows - 20) in
  let last_item_idx = Int.max 0 (List.length Nav.all_menu_items - 1) in
  let bottom_start =
    Model.sidebar_viewport_start ~inner_h:20 ~scroll:max_scroll
      ~cursor:last_item_idx
  in
  Alcotest.(check int) "sidebar reaches max_scroll cleanly at bottom" max_scroll
    bottom_start;
  Alcotest.(check bool) "below-overflow clears at bottom" false
    (Model.sidebar_has_below_overflow ~inner_h:20 ~start:bottom_start);
  (* 7. Palette workspace/repo aliases discover Repos & Changes and Code *)
  let palette_has_target query target =
    let m_pal =
      {
        base with
        nav = { base.nav with overlay = Some Nav.Palette };
        palette = { base.palette with query };
      }
    in
    List.exists
      (fun (e : Update_nav.palette_entry) ->
        match e.action with
        | Update_nav.Pal_menu_target t -> Nav.equal_menu_target t target
        | _ -> false)
      (Update_nav.palette_entries m_pal)
  in
  Alcotest.(check bool) "Palette 'workspace' finds Repos & Changes" true
    (palette_has_target "workspace" (Nav.Menu_infra Nav.Infra_repos_changes));
  Alcotest.(check bool) "Palette 'workspace' finds Code" true
    (palette_has_target "workspace" (Nav.Menu_infra Nav.Infra_code));
  Alcotest.(check bool) "Palette '저장소' finds Repos & Changes" true
    (palette_has_target "저장소" (Nav.Menu_infra Nav.Infra_repos_changes))

let test_runtime_lane_crud_requests_and_cas () =
  (* 1. Keymap SSOT: zero collisions across all scopes with Delete_selected on 'd' *)
  Alcotest.(check int) "Keymap has zero collisions" 0
    (List.length (Keymap.collisions ()));
  (* 2. Wire_runtime candidate parsing & exact JSON wire contracts *)
  Alcotest.(check (list string)) "parse_candidate_runtime_ids trims & splits"
    [ "rt-a"; "rt-b"; "rt-c" ]
    (Wire_runtime.parse_candidate_runtime_ids " rt-a , rt-b ;\n rt-c , ");
  let rev1 = String.make 64 'a' in
  let rev2 = String.make 64 'b' in
  let create_req =
    Cmd.Post_runtime_lane_create
      {
        lane_id = "coder";
        kind = Wire_runtime.Lane_failover;
        runtime_ids = [ "rt-a"; "rt-b" ];
      }
  in
  Alcotest.(check string) "lane create path" "/api/v1/runtime/config/routing"
    (Cmd.post_request_path create_req);
  Alcotest.(check string) "failover lane create JSON"
    {|{"lane":"coder","action":"create","runtime_ids":["rt-a","rt-b"]}|}
    (Yojson.Safe.to_string (Cmd.post_request_body create_req));
  let exact_create_req =
    Cmd.Post_runtime_lane_create
      {
        lane_id = "verifier_exact";
        kind = Wire_runtime.Lane_exact_output;
        runtime_ids = [ "rt-a" ];
      }
  in
  Alcotest.(check string) "exact lane create JSON uses exact/ prefix & action=set"
    {|{"lane":"exact/verifier_exact","action":"set","runtime_ids":["rt-a"]}|}
    (Yojson.Safe.to_string (Cmd.post_request_body exact_create_req));
  let update_req =
    Cmd.Post_runtime_lane_update
      {
        lane_id = "coder";
        kind = Wire_runtime.Lane_failover;
        runtime_ids = [ "rt-b"; "rt-a" ];
        expected_source_revision = Some rev1;
      }
  in
  Alcotest.(check string) "lane update path" "/api/v1/runtime/config/routing"
    (Cmd.post_request_path update_req);
  Alcotest.(check string) "failover lane update JSON includes CAS revision"
    (Printf.sprintf
       {|{"lane":"coder","action":"set","runtime_ids":["rt-b","rt-a"],"expected_source_revision":"%s"}|}
       rev1)
    (Yojson.Safe.to_string (Cmd.post_request_body update_req));
  let delete_req =
    Cmd.Post_runtime_lane_delete
      { lane_id = "coder"; expected_source_revision = Some rev1 }
  in
  Alcotest.(check string) "lane delete path" "/api/v1/runtime/config/routing"
    (Cmd.post_request_path delete_req);
  Alcotest.(check string) "failover lane delete JSON includes CAS revision"
    (Printf.sprintf
       {|{"lane":"coder","action":"remove","expected_source_revision":"%s"}|}
       rev1)
    (Yojson.Safe.to_string (Cmd.post_request_body delete_req));
  (* 3. Store state setup on 5 Runtime > Failover Lanes *)
  let m0 = Model.initial () in
  let m_lanes0 =
    {
      m0 with
      nav = { m0.nav with workspace = Nav.Runtime; sidebar_focused = false };
      runtime = Runtime_store.set_tab Nav.Runtime_failover_lanes m0.runtime;
    }
  in
  let snap : Wire_runtime.runtime_resolved_snapshot =
    {
      generated_at_iso = "2026-11-24T00:00:00Z";
      config_path = Some "/tmp/runtime.toml";
      default_route = Some "rt-a";
      lanes =
        [
          { id = "default"; declared = false; runtime_ids = [ "rt-a" ] };
          { id = "coder"; declared = true; runtime_ids = [ "rt-a"; "rt-b" ] };
          {
            id = "exact/verifier_exact";
            declared = true;
            runtime_ids = [ "rt-a" ];
          };
        ];
      runtimes =
        [
          {
            id = "rt-a";
            provider_id = "p1";
            provider = "anthropic";
            model = Some "claude";
            declared_reasoning_effort = None;
            transport = None;
            is_default = true;
          };
          {
            id = "rt-b";
            provider_id = "p2";
            provider = "openai";
            model = Some "gpt";
            declared_reasoning_effort = None;
            transport = None;
            is_default = false;
          };
        ];
      usage_windows = None;
    }
  in
  let m_lanes1, _ =
    Update.step ~now:t0 m_lanes0
      (Msg.Http_reply
         { epoch = m_lanes0.epoch; reply = Msg.Reply_runtime_resolved (Ok snap) })
  in
  let m_lanes, _ =
    Update.step ~now:t0 m_lanes1
      (Msg.Http_reply
         {
           epoch = m_lanes1.epoch;
           reply =
             Msg.Reply_runtime_config_raw
               (Ok { Wire_runtime.source_revision = rev1; source_text = None; assignments = [] });
         })
  in
  let set_modal_fields pairs (m : Model.t) =
    match m.inline_modal with
    | None -> Alcotest.fail "expected inline_modal to be open"
    | Some st ->
        let fields =
          List.map
            (fun (f : Model.modal_form_field) ->
              match List.assoc_opt f.key pairs with
              | Some v -> { f with value = v }
              | None -> f)
            st.fields
        in
        { m with inline_modal = Some { st with fields } }
  in
  (* 4. [n] opens Runtime_lane_create & emits Post_runtime_lane_create *)
  let m_create_open, _ =
    Update.step ~now:t0 m_lanes (Msg.Key_event (char_key "n"))
  in
  (match m_create_open.nav.overlay with
  | Some (Nav.Inline_action Nav.Runtime_lane_create) -> ()
  | _ -> Alcotest.fail "[n] on Runtime_failover_lanes must open Runtime_lane_create");
  let m_create_bad =
    set_modal_fields
      [
        ("lane_id", "default");
        ("lane_kind", "failover");
        ("lane_candidates", "rt-a");
      ]
      m_create_open
  in
  let m_create_bad_res, bad_create_cmds =
    Update.step ~now:t0 m_create_bad (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check int) "reserved failover lane emits no HTTP command" 0
    (List.length (Cmd.flatten bad_create_cmds));
  Alcotest.(check bool) "reserved failover lane records modal error" true
    (match m_create_bad_res.inline_modal with
    | Some { error = Some _; submitting = false; _ } -> true
    | _ -> false);
  let m_create_ok =
    set_modal_fields
      [
        ("lane_id", "review");
        ("lane_kind", "failover");
        ("lane_candidates", "rt-a, rt-b");
      ]
      m_create_open
  in
  let _, create_cmds =
    Update.step ~now:t0 m_create_ok (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "valid failover create emits Post_runtime_lane_create" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_runtime_lane_create
                   {
                     lane_id = "review";
                     kind = Wire_runtime.Lane_failover;
                     runtime_ids = [ "rt-a"; "rt-b" ];
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten create_cmds));
  (* Tab to lane_kind, press Right to cycle failover -> exact_output *)
  let m_kind_tab, _ =
    Update.step ~now:t0 m_create_open (Msg.Key_event (key Keymap.Input.Tab))
  in
  let m_kind_cycled, _ =
    Update.step ~now:t0 m_kind_tab (Msg.Key_event (key Keymap.Input.Right))
  in
  let m_exact_filled =
    set_modal_fields
      [ ("lane_id", "exact/verifier_exact"); ("lane_candidates", "rt-b") ]
      m_kind_cycled
  in
  let _, exact_cmds =
    Update.step ~now:t0 m_exact_filled (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "cycled exact_output emits normalized bare_id" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_runtime_lane_create
                   {
                     lane_id = "verifier_exact";
                     kind = Wire_runtime.Lane_exact_output;
                     runtime_ids = [ "rt-b" ];
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten exact_cmds));
  (* 5. [d] on synthesized default lane refuses; move down to declared 'coder' lane *)
  let m_del_default, del_default_cmds =
    Update.step ~now:t0 m_lanes (Msg.Key_event (char_key "d"))
  in
  Alcotest.(check bool) "[d] on default lane does not open delete modal" true
    (Option.is_none m_del_default.nav.overlay && Cmd.flatten del_default_cmds = []);
  let m_edit_default, edit_default_cmds =
    Update.step ~now:t0 m_lanes (Msg.Key_event (char_key "e"))
  in
  Alcotest.(check bool) "[e] on default route opens the single-runtime editor" true
    ((match m_edit_default.inline_modal with
      | Some { kind = Nav.Default_route_edit; _ } -> true
      | Some _ | None -> false)
     && Cmd.flatten edit_default_cmds = []);
  let m_coder_unobserved, _ =
    Update.step ~now:t0 m_lanes1 (Msg.Key_event (key Keymap.Input.Down))
  in
  let m_edit_unobserved, _ =
    Update.step ~now:t0 m_coder_unobserved (Msg.Key_event (char_key "e"))
  in
  let _, edit_unobserved_cmds =
    Update.step ~now:t0 m_edit_unobserved (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "a named edit without source revision refreshes without writing" true
    (match Cmd.flatten edit_unobserved_cmds with
     | [ Cmd.Http_get { req = Cmd.Get_runtime_config_raw; _ } ] -> true
     | _ -> false);
  let m_coder, _ =
    Update.step ~now:t0 m_lanes (Msg.Key_event (key Keymap.Input.Down))
  in
  (* 6. [e] opens Runtime_lane_edit seeded with current order + CAS revision *)
  let m_edit_open, _ =
    Update.step ~now:t0 m_coder (Msg.Key_event (char_key "e"))
  in
  (match m_edit_open.inline_modal with
  | Some
      ({
         kind =
           Nav.Runtime_lane_edit
             { lane_id = "coder"; exact_output = false; opened_revision = Some r };
         _;
       } as st) ->
      Alcotest.(check string) "opened_revision captured" rev1 r;
      Alcotest.(check string) "candidates seeded" "rt-a, rt-b"
        (Model.modal_field_value ~key:"lane_candidates" st)
  | _ -> Alcotest.fail "[e] on selected lane must open seeded Runtime_lane_edit");
  (* CAS drift refusal if newer raw revision arrives while editing *)
  let m_edit_drifted, _ =
    Update.step ~now:t1 m_edit_open
      (Msg.Http_reply
         {
           epoch = m_edit_open.epoch;
           reply =
             Msg.Reply_runtime_config_raw
               (Ok { Wire_runtime.source_revision = rev2; source_text = None; assignments = [] });
         })
  in
  let m_edit_drifted_res, drifted_cmds =
    Update.step ~now:t1 m_edit_drifted (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check int) "CAS revision drift blocks update POST" 0
    (List.length (Cmd.flatten drifted_cmds));
  Alcotest.(check bool) "CAS drift sets modal error" true
    (match m_edit_drifted_res.inline_modal with
    | Some { error = Some _; submitting = false; _ } -> true
    | _ -> false);
  (* Valid edit emits Post_runtime_lane_update with CAS revision *)
  let m_edit_reordered =
    set_modal_fields [ ("lane_candidates", "rt-b, rt-a") ] m_edit_open
  in
  let m_edit_submitting, edit_cmds =
    Update.step ~now:t1 m_edit_reordered (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "edit submits Post_runtime_lane_update with CAS" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_runtime_lane_update
                   {
                     lane_id = "coder";
                     kind = Wire_runtime.Lane_failover;
                     runtime_ids = [ "rt-b"; "rt-a" ];
                     expected_source_revision = Some r;
                   };
               _;
             }
           when String.equal r rev1 ->
             true
         | _ -> false)
       (Cmd.flatten edit_cmds));
  (* 409 Conflict reply keeps modal open with error and triggers raw+resolved refresh *)
  let m_conflict, conflict_cmds =
    Update.step ~now:t2 m_edit_submitting
      (Msg.Http_reply
         {
           epoch = m_edit_submitting.epoch;
           reply =
             Msg.Reply_runtime_lane_mutation
               {
                 lane_id = "coder";
                 operation = `Update;
                 result =
                   Error
                     (Msg.Http_error
                        { status = 409; body = "stale revision"; api_error = None });
               };
         })
  in
  Alcotest.(check bool) "409 keeps modal open & clears submitting" true
    (match m_conflict.inline_modal with
    | Some { submitting = false; error = Some _; _ } -> true
    | _ -> false);
  Alcotest.(check bool) "409 refreshes Get_runtime_config_raw" true
    (List.exists
       (function
         | Cmd.Http_get { req = Cmd.Get_runtime_config_raw; _ } -> true
         | _ -> false)
       (Cmd.flatten conflict_cmds));
  (* 7. Zoomed Runtime_failover_lanes fetches Get_runtime_config_raw, supports [a], and [d] unzooms on delete *)
  let m_zoomed_lane =
    {
      m_coder with
      nav =
        {
          m_coder.nav with
          zoomed = true;
          pre_zoom_pane_index = Some 0;
          pane_index = 0;
        };
    }
  in
  let zoomed_fetches =
    Cmd.flatten (View_fetches.fetches_for_current_view ~force:true m_zoomed_lane)
  in
  Alcotest.(check bool) "zoomed lane fetches Get_runtime_config_raw" true
    (List.exists
       (function
         | Cmd.Http_get { req = Cmd.Get_runtime_config_raw; _ } -> true
         | _ -> false)
       zoomed_fetches);
  let m_assign_from_zoom, _ =
    Update.step ~now:t1 m_zoomed_lane (Msg.Key_event (char_key "a"))
  in
  Alcotest.(check bool) "[a] in zoomed lane keeps Form_runtime_assign accessible" true
    (match m_assign_from_zoom.inline_modal with
    | Some { fields = { key = "assign_keeper"; _ } :: _; _ } -> true
    | _ -> false);
  let m_del_open, _ =
    Update.step ~now:t1 m_zoomed_lane (Msg.Key_event (char_key "d"))
  in
  (match m_del_open.nav.overlay with
  | Some (Nav.Inline_action (Nav.Runtime_lane_delete { lane_id = "coder"; _ })) -> ()
  | _ -> Alcotest.fail "[d] in zoomed lane must open Runtime_lane_delete");
  let m_del_wrong =
    set_modal_fields [ ("confirm_lane_id", "wrong") ] m_del_open
  in
  let _, del_wrong_cmds =
    Update.step ~now:t1 m_del_wrong (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check int) "wrong delete confirmation emits no POST" 0
    (List.length (Cmd.flatten del_wrong_cmds));
  let m_del_ok =
    set_modal_fields [ ("confirm_lane_id", "coder") ] m_del_open
  in
  let m_del_submitting, del_cmds =
    Update.step ~now:t1 m_del_ok (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "confirmed delete emits Post_runtime_lane_delete with CAS" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_runtime_lane_delete
                   { lane_id = "coder"; expected_source_revision = Some r };
               _;
             }
           when String.equal r rev1 ->
             true
         | _ -> false)
       (Cmd.flatten del_cmds));
  let m_deleted, deleted_cmds =
    Update.step ~now:t2 m_del_submitting
      (Msg.Http_reply
         {
           epoch = m_del_submitting.epoch;
           reply =
             Msg.Reply_runtime_lane_mutation
               { lane_id = "coder"; operation = `Delete; result = Ok () };
         })
  in
  Alcotest.(check bool) "delete Ok closes modal and unzooms failover lane" true
    (Option.is_none m_deleted.inline_modal
    && Option.is_none m_deleted.nav.overlay
    && not m_deleted.nav.zoomed);
  Alcotest.(check bool) "delete Ok refreshes runtime_resolved and raw config" true
    (List.exists
       (function
         | Cmd.Http_get { req = Cmd.Get_runtime_resolved; _ } -> true
         | _ -> false)
       (Cmd.flatten deleted_cmds)
    && List.exists
         (function
           | Cmd.Http_get { req = Cmd.Get_runtime_config_raw; _ } -> true
           | _ -> false)
         (Cmd.flatten deleted_cmds))

let test_work_and_board_crud_requests_and_guards () =
  (* 1. Keymap SSOT: zero collisions across all scopes with Link_task_goal on 'g' in Screen_context *)
  Alcotest.(check int) "Keymap has zero collisions" 0
    (List.length (Keymap.collisions ()));
  (* 2. Wire_work MCP 2026-07-28 envelope, goal measure parsing, and strict allowlist encoders *)
  (match Wire_work.parse_goal_measure_input ~kind:"done_when" ~spec:"All CRUD wired" with
  | Ok (Wire_work.Measure_done_when { condition = "All CRUD wired" }) -> ()
  | _ -> Alcotest.fail "done_when measure parse failed");
  (match Wire_work.parse_goal_measure_input ~kind:"count" ~spec:"14 files" with
  | Ok (Wire_work.Measure_count { noun = "files"; total = 14 }) -> ()
  | _ -> Alcotest.fail "count measure parse failed");
  (match Wire_work.parse_goal_measure_input ~kind:"quantity" ~spec:"<= 100 ms" with
  | Ok (Wire_work.Measure_quantity { unit = "ms"; direction = Wire_work.At_most; target })
    when Float.equal target 100.0 -> ()
  | _ -> Alcotest.fail "quantity measure parse failed");
  Alcotest.(check bool) "invalid count measure refused" true
    (Result.is_error (Wire_work.parse_goal_measure_input ~kind:"count" ~spec:"0 files"));
  Alcotest.(check bool) "MCP ack Ok on plain JSON" true
    (Result.is_ok
       (Wire_work.decode_mcp_tool_call_ack
          {|{"jsonrpc":"2.0","id":"1","result":{"content":[{"type":"text","text":"ok"}],"isError":false}}|}));
  Alcotest.(check bool) "MCP ack Ok on SSE data frame" true
    (Result.is_ok
       (Wire_work.decode_mcp_tool_call_ack
          "event: message\ndata: {\"jsonrpc\":\"2.0\",\"id\":\"1\",\"result\":{\"isError\":false}}\n\n"));
  Alcotest.(check bool) "MCP ack Error on result.isError=true" true
    (Result.is_error
       (Wire_work.decode_mcp_tool_call_ack
          {|{"jsonrpc":"2.0","id":"1","result":{"content":[{"type":"text","text":"goal closed"}],"isError":true}}|}));
  Alcotest.(check bool) "MCP ack Error on JSON-RPC error" true
    (Result.is_error
       (Wire_work.decode_mcp_tool_call_ack
          {|{"jsonrpc":"2.0","id":"1","error":{"code":-32602,"message":"invalid params"}}|}));
  let ws : Wire_work.expected_workspace =
    { base_path = "/repo"; masc_root = "/repo/.masc" }
  in
  let link_req =
    Cmd.Post_task_link_goal
      { task_id = "task-001"; goal_id = "goal-1"; expected_workspace = ws }
  in
  Alcotest.(check string) "task link-goal REST path"
    "/api/v1/tasks/task-001/link-goal"
    (Cmd.post_request_path link_req);
  Alcotest.(check string) "task link-goal strict 2-field body"
    {|{"goal_id":"goal-1","expected_workspace":{"base_path":"/repo","masc_root":"/repo/.masc"}}|}
    (Yojson.Safe.to_string (Cmd.post_request_body link_req));
  let upsert_req =
    Cmd.Post_goal_upsert
      {
        id = None;
        title = "Ship TUI CRUD";
        measure = Some (Wire_work.Measure_done_when { condition = "All routes tested" });
        procedure = "Check board:post-1 and test suite";
        priority = Some 2;
        due_date = None;
        expected_workspace = Some ws;
      }
  in
  Alcotest.(check string) "goal upsert MCP path" "/mcp"
    (Cmd.post_request_path upsert_req);
  Alcotest.(check (option string)) "goal upsert MCP tool name"
    (Some "masc_goal_upsert")
    (Cmd.mcp_tool_name_of_post_request upsert_req);
  let upsert_json_str = Yojson.Safe.to_string (Cmd.post_request_body upsert_req) in
  Alcotest.(check bool) "goal upsert body contains protocol version 2026-07-28 and no legacy status"
    true
    (let has sub =
       let n = String.length upsert_json_str and m = String.length sub in
       let rec loop i =
         if i + m > n then false
         else if String.equal (String.sub upsert_json_str i m) sub then true
         else loop (i + 1)
       in
       loop 0
     in
     has "2026-07-28" && has "masc_goal_upsert" && not (has {|"status":|}) && not (has {|"phase":|}));
  let pin_req = Cmd.Post_board_pin { post_id = "p-1"; pinned = true } in
  Alcotest.(check string) "board pin path" "/api/v1/dashboard/board/pin"
    (Cmd.post_request_path pin_req);
  Alcotest.(check string) "board pin JSON" {|{"post_id":"p-1","pinned":true}|}
    (Yojson.Safe.to_string (Cmd.post_request_body pin_req));
  let del_req = Cmd.Post_board_delete { post_id = "p-1" } in
  Alcotest.(check string) "board delete path" "/api/v1/dashboard/board/delete"
    (Cmd.post_request_path del_req);
  Alcotest.(check string) "board delete JSON" {|{"post_id":"p-1"}|}
    (Yojson.Safe.to_string (Cmd.post_request_body del_req));
  (* 3. Store setup with workspace identity, tasks (1 goalless, 1 linked), and goals *)
  let ws_id : Wire_common.workspace_identity =
    {
      instance_id = Some "inst-2";
      base_path = "/repo";
      masc_root = "/repo/.masc";
      workspace_sha256 = Some "sha-ws";
    }
  in
  let task_goalless : Wire_work.task =
    {
      id = "task-unlinked";
      title = "Unlinked work";
      description = None;
      priority = 2;
      status = Wire_work.Todo;
      goal_link = Wire_work.Unlinked;
      created_at = None;
      updated_at = None;
    }
  in
  let task_linked : Wire_work.task =
    {
      id = "task-linked";
      title = "Linked work";
      description = None;
      priority = 2;
      status = Wire_work.Claimed { assignee = "alpha"; claimed_at = "2026-11-24T00:00:00Z" };
      goal_link = Wire_work.Linked "g-1";
      created_at = None;
      updated_at = None;
    }
  in
  let m0 = Model.initial () in
  let m_base =
    {
      m0 with
      nav = { m0.nav with workspace = Nav.Work; sidebar_focused = false };
      server_identity = { m0.server_identity with workspace = Some ws_id };
      work =
        Work_store.empty
        |> Work_store.apply_planning ~observed_at:t0
             { goals = [ sample_goal ~id:"g-1" ~phase:Wire_work.Executing () ]; tasks = [ task_goalless; task_linked ] };
    }
  in
  let set_fields pairs (m : Model.t) =
    match m.inline_modal with
    | None -> Alcotest.fail "expected inline_modal open"
    | Some st ->
        let fields =
          List.map
            (fun (f : Model.modal_form_field) ->
              match List.assoc_opt f.key pairs with
              | Some v -> { f with value = v }
              | None -> f)
            st.fields
        in
        { m with inline_modal = Some { st with fields } }
  in
  (* 4. Tasks tab: [n] Create Task, [c] Transition, [g] Link Goalless Task *)
  let m_tasks = { m_base with work = Work_store.set_tab Nav.Work_tasks m_base.work } in
  let m_tc_open, _ = Update.step ~now:t0 m_tasks (Msg.Key_event (char_key "n")) in
  (match m_tc_open.nav.overlay with
  | Some (Nav.Inline_action Nav.Task_create_form) -> ()
  | _ -> Alcotest.fail "[n] on Work_tasks must open Task_create_form");
  let m_tc_filled =
    set_fields
      [
        ("task_title", "Add task CRUD");
        ("task_priority", "1");
        ("task_goal_id", "g-1");
        ("task_description", "Wire modal to MCP");
      ]
      m_tc_open
  in
  let _, tc_cmds =
    Update.step ~now:t0 m_tc_filled (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "Task_create_form emits Post_task_create" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_task_create
                   {
                     title = "Add task CRUD";
                     priority = 1;
                     goal_id = Some "g-1";
                     description = Some "Wire modal to MCP";
                     expected_workspace = Some _;
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten tc_cmds));
  (* [c] opens Task_transition_form seeded with 'claim' for Todo; Right cycles to 'start' *)
  let m_tr_open, _ = Update.step ~now:t0 m_tasks (Msg.Key_event (char_key "c")) in
  (match m_tr_open.inline_modal with
  | Some ({ kind = Nav.Task_transition_form { task_id = "task-unlinked" }; _ } as st) ->
      Alcotest.(check string) "Todo task defaults to claim" "claim"
        (Model.modal_field_value ~key:"task_action" st)
  | _ -> Alcotest.fail "[c] on Work_tasks must open Task_transition_form");
  let m_tr_cycled, _ =
    Update.step ~now:t0 m_tr_open (Msg.Key_event (key Keymap.Input.Right))
  in
  let _, tr_cmds =
    Update.step ~now:t0 m_tr_cycled (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "Task_transition_form emits Post_task_transition(Task_start)" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_task_transition
                   {
                     task_id = "task-unlinked";
                     action = Wire_work.Task_start;
                     _;
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten tr_cmds));
  (* [g] on goalless task opens Task_link_goal and emits Post_task_link_goal *)
  let m_link_open, _ = Update.step ~now:t0 m_tasks (Msg.Key_event (char_key "g")) in
  (match m_link_open.nav.overlay with
  | Some (Nav.Inline_action (Nav.Task_link_goal { task_id = "task-unlinked" })) -> ()
  | _ -> Alcotest.fail "[g] on goalless task must open Task_link_goal");
  let m_link_filled = set_fields [ ("link_goal_id", "g-1") ] m_link_open in
  let _, link_cmds =
    Update.step ~now:t0 m_link_filled (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "Task_link_goal emits Post_task_link_goal" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_task_link_goal
                   { task_id = "task-unlinked"; goal_id = "g-1"; _ };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten link_cmds));
  (* [g] on already-linked task refuses locally (constitution goalless-only rule) *)
  let m_tasks_linked, _ =
    Update.step ~now:t0 m_tasks (Msg.Key_event (key Keymap.Input.Down))
  in
  let m_link_refused, link_refused_cmds =
    Update.step ~now:t0 m_tasks_linked (Msg.Key_event (char_key "g"))
  in
  Alcotest.(check bool) "[g] on already-linked task refuses without modal or POST" true
    (Option.is_none m_link_refused.nav.overlay && Cmd.flatten link_refused_cmds = []);
  (* 5. Goals tab: [n] Create Goal requiring measure+procedure, [e] Edit Goal *)
  let m_goals = { m_base with work = Work_store.set_tab Nav.Work_pipeline m_base.work } in
  let m_gc_open, _ = Update.step ~now:t0 m_goals (Msg.Key_event (char_key "n")) in
  let m_gc_no_proc =
    set_fields
      [
        ("goal_title", "New Goal");
        ("goal_measure_kind", "done_when");
        ("goal_measure_spec", "Tests pass");
        ("goal_procedure", "   ");
      ]
      m_gc_open
  in
  let _, gc_bad_cmds =
    Update.step ~now:t0 m_gc_no_proc (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check int) "blank procedure blocks Goal_upsert_form submit" 0
    (List.length (Cmd.flatten gc_bad_cmds));
  let m_gc_ok =
    set_fields
      [
        ("goal_title", "New Goal");
        ("goal_measure_kind", "count");
        ("goal_measure_spec", "3 PRs");
        ("goal_procedure", "Verify Stack C PRs");
        ("goal_priority", "1");
      ]
      m_gc_open
  in
  let _, gc_cmds =
    Update.step ~now:t0 m_gc_ok (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "Goal_upsert_form create emits Post_goal_upsert(id=None)" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_goal_upsert
                   {
                     id = None;
                     title = "New Goal";
                     measure = Some (Wire_work.Measure_count { noun = "PRs"; total = 3 });
                     procedure = "Verify Stack C PRs";
                     priority = Some 1;
                     _;
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten gc_cmds));
  let m_ge_open, _ = Update.step ~now:t0 m_goals (Msg.Key_event (char_key "e")) in
  (match m_ge_open.nav.overlay with
  | Some (Nav.Inline_action (Nav.Goal_upsert_form (Some "g-1"))) -> ()
  | _ -> Alcotest.fail "[e] on Work_pipeline must open Goal_upsert_form (Some id)");
  let _, ge_cmds =
    Update.step ~now:t0 m_ge_open (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool)
    "Goal_upsert_form edit without touching measure preserves stored measure (measure=None)"
    true
    (List.exists
       (function
         | Cmd.Http_post
             { req = Cmd.Post_goal_upsert { id = Some "g-1"; measure = None; _ }; _ } ->
             true
         | _ -> false)
       (Cmd.flatten ge_cmds));
  (* submit_for_verification requires non-empty task_notes *)
  let m_tr_open, _ = Update.step ~now:t0 m_tasks (Msg.Key_event (char_key "c")) in
  let m_tr_blank_verif =
    set_fields
      [ ("task_action", "submit_for_verification"); ("task_notes", "   ") ]
      m_tr_open
  in
  let _, tr_blank_cmds =
    Update.step ~now:t0 m_tr_blank_verif (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check int)
    "submit_for_verification with blank notes blocked locally (0 POSTs)" 0
    (List.length (Cmd.flatten tr_blank_cmds));
  let m_tr_ok_verif =
    set_fields
      [
        ("task_action", "submit_for_verification");
        ("task_notes", "CI green and evidence attached");
      ]
      m_tr_open
  in
  let _, tr_ok_cmds =
    Update.step ~now:t0 m_tr_ok_verif (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool)
    "submit_for_verification with notes emits Post_task_transition" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_task_transition
                   {
                     task_id = "task-unlinked";
                     action = Wire_work.Task_submit_for_verification;
                     notes = Some "CI green and evidence attached";
                     _;
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten tr_ok_cmds));
  (* 6. Board & Thread_dive: [R]/[a] Reply, [u] Upvote, [p] Pin toggle, [d] Delete + dive pop *)
  let sample_post : Wire_knowledge.board_post =
    {
      id = "post-42";
      title = "CRUD Audit";
      body = "Details";
      author = "alpha";
      hearth = Some "general";
      post_kind = Some Wire_knowledge.Human_post;
      visibility = Some Wire_knowledge.Vis_public;
      created_at_unix = 1_700_000_000.0;
      updated_at_unix = None;
      score = 3;
      comment_count = 0;
      author_karma = Observed.value ~observed_at:t0 10;
      succession_chain_root_id = None;
      chain_depth = None;
      is_signal = true;
      pinned = false;
    }
  in
  let m_board0 =
    {
      m0 with
      nav = { m0.nav with workspace = Nav.Knowledge; sidebar_focused = false };
      knowledge = Knowledge_store.set_tab Nav.Knowledge_board m0.knowledge;
    }
  in
  let m_board, _ =
    Update.step ~now:t0 m_board0
      (Msg.Http_reply
         {
           epoch = m_board0.epoch;
           reply =
             Msg.Reply_board_feed
               (Ok
                  {
                    Wire_knowledge.posts = [ sample_post ];
                    count = 1;
                    sort_by = "recent";
                    signal_only = true;
                  });
         })
  in
  let m_reply_r, _ =
    Update.step ~now:t0 m_board (Msg.Key_event (char_key ~shift:true "R"))
  in
  (match m_reply_r.nav.overlay with
  | Some (Nav.Inline_action (Nav.Board_comment { post_id = "post-42"; _ })) -> ()
  | _ -> Alcotest.fail "[R] on Knowledge_board must open Board_comment");
  let m_reply_a, _ = Update.step ~now:t0 m_board (Msg.Key_event (char_key "a")) in
  (match m_reply_a.nav.overlay with
  | Some (Nav.Inline_action (Nav.Board_comment { post_id = "post-42"; _ })) -> ()
  | _ -> Alcotest.fail "[a] on Knowledge_board must open Board_comment");
  let _, upvote_cmds = Update.step ~now:t0 m_board (Msg.Key_event (char_key "u")) in
  Alcotest.(check bool) "[u] on Knowledge_board emits Post_board_vote Up" true
    (List.exists
       (function
         | Cmd.Http_post
             { req = Cmd.Post_board_vote { post_id = "post-42"; direction = `Up }; _ } ->
             true
         | _ -> false)
       (Cmd.flatten upvote_cmds));
  let _, pin_cmds = Update.step ~now:t0 m_board (Msg.Key_event (char_key "p")) in
  Alcotest.(check bool) "[p] on unpinned post emits Post_board_pin(pinned=true)" true
    (List.exists
       (function
         | Cmd.Http_post
             { req = Cmd.Post_board_pin { post_id = "post-42"; pinned = true }; _ } ->
             true
         | _ -> false)
       (Cmd.flatten pin_cmds));
  let m_thread_dive =
    {
      m_board with
      nav =
        {
          m_board.nav with
          dive_stack = [ Nav.Dive_knowledge (Nav.Thread_dive "post-42") ];
        };
    }
  in
  let m_bdel_open, _ =
    Update.step ~now:t0 m_thread_dive (Msg.Key_event (char_key "d"))
  in
  (match m_bdel_open.nav.overlay with
  | Some (Nav.Inline_action (Nav.Board_delete_post { post_id = "post-42"; _ })) -> ()
  | _ -> Alcotest.fail "[d] in Thread_dive must open Board_delete_post");
  let m_bdel_wrong =
    set_fields [ ("confirm_post_delete", "nope") ] m_bdel_open
  in
  let _, bdel_wrong_cmds =
    Update.step ~now:t0 m_bdel_wrong (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check int) "wrong board delete confirmation emits no POST" 0
    (List.length (Cmd.flatten bdel_wrong_cmds));
  let m_bdel_ok =
    set_fields [ ("confirm_post_delete", "delete") ] m_bdel_open
  in
  let m_bdel_submitting, bdel_cmds =
    Update.step ~now:t0 m_bdel_ok (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "confirmed delete emits Post_board_delete" true
    (List.exists
       (function
         | Cmd.Http_post { req = Cmd.Post_board_delete { post_id = "post-42" }; _ } ->
             true
         | _ -> false)
       (Cmd.flatten bdel_cmds));
  let m_bdeleted, bdeleted_cmds =
    Update.step ~now:t1 m_bdel_submitting
      (Msg.Http_reply
         {
           epoch = m_bdel_submitting.epoch;
           reply = Msg.Reply_board_delete { post_id = "post-42"; result = Ok () };
         })
  in
  Alcotest.(check bool) "Reply_board_delete Ok closes modal and pops Thread_dive" true
    (Option.is_none m_bdeleted.inline_modal
    && Option.is_none m_bdeleted.nav.overlay
    && m_bdeleted.nav.dive_stack = []);
  Alcotest.(check bool) "Reply_board_delete Ok refreshes Get_board_feed" true
    (List.exists
       (function
         | Cmd.Http_get { req = Cmd.Get_board_feed _; _ } -> true
         | _ -> false)
       (Cmd.flatten bdeleted_cmds))

let test_keeper_lifecycle_and_addon_crud_requests () =
  (* 1. Exact wire paths and JSON bodies for Keeper Lifecycle & Lane-Addon CRUD *)
  let ws_pair = ("/repo", "/repo/.masc") in
  let boot_req =
    Cmd.Post_keeper_lifecycle
      {
        keeper = "alpha";
        op = Wire_fleet.Keeper_boot;
        expected_workspace = Some ws_pair;
        req_seq = 1;
        modal_submission_id = None;
      }
  in
  Alcotest.(check string) "keeper boot path" "/api/v1/keepers/alpha/boot"
    (Cmd.post_request_path boot_req);
  Alcotest.(check string) "keeper boot body" "{}"
    (Yojson.Safe.to_string (Cmd.post_request_body boot_req));
  let resume_req =
    Cmd.Post_keeper_lifecycle
      {
        keeper = "alpha";
        op = Wire_fleet.Keeper_resume { operator_operation_id = "op-42" };
        expected_workspace = Some ws_pair;
        req_seq = 2;
        modal_submission_id = None;
      }
  in
  Alcotest.(check string) "keeper directive path"
    "/api/v1/keepers/alpha/directive"
    (Cmd.post_request_path resume_req);
  Alcotest.(check string) "keeper resume JSON includes operator_operation_id & workspace"
    {|{"action":"resume","operator_operation_id":"op-42","expected_workspace":{"base_path":"/repo","masc_root":"/repo/.masc"}}|}
    (Yojson.Safe.to_string (Cmd.post_request_body resume_req));
  let purge_req =
    Cmd.Post_keeper_purge { keeper = "alpha"; expected_workspace = ws_pair }
  in
  Alcotest.(check string) "keeper purge path" "/api/v1/dashboard/agents/purge"
    (Cmd.post_request_path purge_req);
  Alcotest.(check string) "keeper purge JSON"
    {|{"agent_name":"alpha","expected_workspace":{"base_path":"/repo","masc_root":"/repo/.masc"}}|}
    (Yojson.Safe.to_string (Cmd.post_request_body purge_req));
  let attach_req =
    Cmd.Post_lane_addon_attach
      {
        manifest_path = "addons/browser/manifest.toml";
        run_id = "run-1";
        binding = `Assoc [ ("mode", `String "local") ];
        from_modal = true;
      }
  in
  Alcotest.(check string) "addon attach path" "/api/v1/lane-addons/attach"
    (Cmd.post_request_path attach_req);
  Alcotest.(check string) "addon attach JSON"
    {|{"manifest_path":"addons/browser/manifest.toml","run_id":"run-1","binding":{"mode":"local"}}|}
    (Yojson.Safe.to_string (Cmd.post_request_body attach_req));
  let detach_req = Cmd.Post_lane_addon_detach { instance_id = "inst-1" } in
  Alcotest.(check string) "addon detach path" "/api/v1/lane-addons/detach"
    (Cmd.post_request_path detach_req);
  Alcotest.(check string) "addon detach JSON" {|{"instance_id":"inst-1"}|}
    (Yojson.Safe.to_string (Cmd.post_request_body detach_req));
  let act_req =
    Cmd.Post_lane_addon_action
      {
        instance_id = "inst-1";
        expected_incarnation = "inst-1";
        request_id = "req-1";
        action = `Assoc [ ("action", `String "navigate") ];
      }
  in
  Alcotest.(check string) "addon action path" "/api/v1/lane-addons/actions"
    (Cmd.post_request_path act_req);
  Alcotest.(check string) "addon action JSON"
    {|{"instance_id":"inst-1","expected_incarnation":"inst-1","request_id":"req-1","action":{"action":"navigate"}}|}
    (Yojson.Safe.to_string (Cmd.post_request_body act_req));
  Alcotest.(check string) "addon asks GET path"
    "/api/v1/lane-addons/asks?include_resolved=false"
    (Cmd.get_request_path (Cmd.Get_lane_addon_asks { include_resolved = false }));
  let ask_ans_req =
    Cmd.Post_lane_addon_ask_answer
      {
        declaration_id = "decl-browser";
        ask_id = "ask-addon-1";
        answers = [ ("q1", Wire_work.Ask_chose [ "c1" ]) ];
      }
  in
  Alcotest.(check string) "addon ask-answer path" "/api/v1/lane-addons/ask-answer"
    (Cmd.post_request_path ask_ans_req);
  Alcotest.(check string) "addon ask-answer JSON"
    {|{"declaration_id":"decl-browser","ask_id":"ask-addon-1","answers":[{"question_id":"q1","response":{"kind":"chose","choice_ids":["c1"]}}]}|}
    (Yojson.Safe.to_string (Cmd.post_request_body ask_ans_req));
  let set_fields pairs (m : Model.t) =
    match m.inline_modal with
    | None -> Alcotest.fail "expected inline_modal open"
    | Some st ->
        let fields =
          List.map
            (fun (f : Model.modal_form_field) ->
              match List.assoc_opt f.key pairs with
              | Some v -> { f with value = v }
              | None -> f)
            st.fields
        in
        { m with inline_modal = Some { st with fields } }
  in
  (* 2. Keeper Lifecycle on 4 Keepers & Keeper_dive *)
  let ws_id : Wire_common.workspace_identity =
    {
      instance_id = Some "inst-2";
      base_path = "/repo";
      masc_root = "/repo/.masc";
      workspace_sha256 = Some "sha-ws";
    }
  in
  let m0 = Model.initial () in
  let k_paused = { (sample_keeper ~health:Wire_fleet.Keeper_paused "alpha") with paused = true } in
  let k_offline = { (sample_keeper ~health:Wire_fleet.Keeper_offline "beta") with paused = false } in
  let k_live = sample_keeper ~health:Wire_fleet.Keeper_healthy "gamma" in
  let m_keepers0 =
    {
      m0 with
      nav = { m0.nav with workspace = Nav.Keepers; sidebar_focused = false };
      server_identity = { m0.server_identity with workspace = Some ws_id };
    }
  in
  let m_keepers, _ =
    Update.step ~now:t0 m_keepers0
      (Msg.Http_reply
         {
           epoch = m_keepers0.epoch;
           reply = Msg.Reply_keepers_roster (Ok (roster_of [ k_paused; k_offline; k_live ]));
         })
  in
  (* [a] on paused keeper alpha emits Keeper_resume immediately *)
  let _, resume_cmds =
    Update.step ~now:t0 m_keepers (Msg.Key_event (char_key "a"))
  in
  Alcotest.(check bool) "[a] on paused keeper emits Keeper_resume" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_keeper_lifecycle
                   {
                     keeper = "alpha";
                     op = Wire_fleet.Keeper_resume { operator_operation_id };
                     _;
                   };
               _;
             }
           when not (String.equal operator_operation_id "") ->
             true
         | _ -> false)
       (Cmd.flatten resume_cmds));
  (* Move to offline keeper beta -> [a] emits Keeper_boot *)
  let m_beta, _ =
    Update.step ~now:t0 m_keepers (Msg.Key_event (key Keymap.Input.Down))
  in
  let _, boot_cmds = Update.step ~now:t0 m_beta (Msg.Key_event (char_key "a")) in
  Alcotest.(check bool) "[a] on offline keeper emits Keeper_boot" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_keeper_lifecycle
                   { keeper = "beta"; op = Wire_fleet.Keeper_boot; _ };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten boot_cmds));
  (* Move to live keeper gamma -> [x] opens Keeper_lifecycle_form seeded with pause; destructive shutdown requires confirm *)
  let m_gamma, _ =
    Update.step ~now:t0 m_beta (Msg.Key_event (key Keymap.Input.Down))
  in
  let m_lc_open, _ = Update.step ~now:t0 m_gamma (Msg.Key_event (char_key "x")) in
  (match m_lc_open.nav.overlay with
  | Some (Nav.Inline_action (Nav.Keeper_lifecycle_form { keeper = "gamma" })) -> ()
  | _ -> Alcotest.fail "[x] on Keepers must open Keeper_lifecycle_form");
  let m_lc_sd =
    set_fields [ ("lifecycle_action", "shutdown"); ("confirm_keeper", "") ] m_lc_open
  in
  let _, sd_blocked_cmds =
    Update.step ~now:t0 m_lc_sd (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check int) "shutdown without keeper confirmation emits no POST" 0
    (List.length (Cmd.flatten sd_blocked_cmds));
  let m_lc_sd_ok =
    set_fields [ ("lifecycle_action", "shutdown"); ("confirm_keeper", "gamma") ] m_lc_open
  in
  let _, sd_cmds =
    Update.step ~now:t0 m_lc_sd_ok (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "confirmed shutdown emits Post_keeper_lifecycle(Keeper_shutdown)" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_keeper_lifecycle
                   { keeper = "gamma"; op = Wire_fleet.Keeper_shutdown; _ };
               _;
             } ->
             true
         | _ -> false)
