  (match m_purge_open.nav.overlay with
  | Some (Nav.Inline_action (Nav.Keeper_purge_confirm { keeper = "gamma" })) -> ()
  | _ -> Alcotest.fail "[d] in Keeper_dive must open Keeper_purge_confirm");
