      observation_seq = 1;
      rows_count = 3;
      observation_pending = false;
      visibility_kind = Some "shared";
      visibility_keeper = None;
      host_cycles = Some 1;
      host_waiting_count = 0;
      host_issue_kind = None;
      action_names = [ "navigate"; "click" ];
