  in
  Alcotest.(check bool) "Addon_detach_confirm emits Post_lane_addon_detach" true
    (List.exists
       (function
         | Cmd.Http_post
             { req = Cmd.Post_lane_addon_detach { instance_id = "inst-browser-1" }; _ } ->
             true
         | _ -> false)
       (Cmd.flatten det_cmds));
  (* [c] opens Ask_answer modal for open lane-addon ask -> select choice & Enter -> Post_lane_addon_ask_answer *)
  let m_ask_open, _ = Update.step ~now:t0 m_addons (Msg.Key_event (char_key "c")) in
  (match m_ask_open.ask_modal with
  | Some { lane_addon_declaration_id = Some "decl-browser"; ask; _ }
    when String.equal ask.ask_id "ask-addon-1" ->
      ()
  | _ -> Alcotest.fail "[c] on Runtime_addons_browser must open Ask_answer modal for lane-addon ask");
  let m_ask_sel, _ =
    Update.step ~now:t0 m_ask_open (Msg.Key_event (char_key "a"))
  in
  let m_ask_sub, ask_cmds =
    Update.step ~now:t0 m_ask_sel (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "Ask_answer modal emits Post_lane_addon_ask_answer" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_lane_addon_ask_answer
                   {
                     declaration_id = "decl-browser";
                     ask_id = "ask-addon-1";
                     answers = [ ("q1", Wire_work.Ask_chose [ "default" ]) ];
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten ask_cmds));
  let m_other_ask, _ =
    Update.step ~now:t1 m_ask_sub
      (Msg.Http_reply
         {
           epoch = m_ask_sub.epoch;
           reply = Msg.Reply_lane_addon_ask_answer
             { declaration_id = "different-addon"; ask_id = "ask-addon-1"; result = Ok () };
         })
  in
  Alcotest.(check bool) "another declaration's receipt preserves the pending ask" true
    (Option.fold ~none:false ~some:(fun (modal : Model.ask_modal) -> modal.submitting)
       m_other_ask.ask_modal);
  let m_ask_done, ask_done_cmds =
    Update.step ~now:t1 m_ask_sub
      (Msg.Http_reply
         {
           epoch = m_ask_sub.epoch;
           reply =
             Msg.Reply_lane_addon_ask_answer
               { declaration_id = "decl-browser"; ask_id = "ask-addon-1"; result = Ok () };
         })
  in
  Alcotest.(check bool) "Reply_lane_addon_ask_answer Ok closes ask_modal and refreshes asks" true
    (Option.is_none m_ask_done.ask_modal
    && Option.is_none m_ask_done.nav.overlay
    && List.exists
         (function
           | Cmd.Http_get { req = Cmd.Get_lane_addon_asks _; _ } -> true
           | _ -> false)
         (Cmd.flatten ask_done_cmds))

let test_oauth_poll_lifecycle () =
  let now = Clock.Mono.of_ns 1_000_000_000L in
  let later = Clock.Mono.after_s now 2. in
  let keeper = "alpha" and provider = "linear" in
  let initial = Model.initial ~wall_unix:100. () in
  let reply ~at (m : Model.t) reply =
    Update.step ~now:at m (Msg.Http_reply { epoch = m.epoch; reply })
  in
  let start attempt_id m =
    fst (reply ~at:now m (Msg.Reply_oauth_login { keeper; result =
      Ok (Wire_keeper_context.Oauth_login_exchange { provider; provider_label = "Linear";
        authorize_url = "https://auth.example.org/approve"; attempt_id; expires_at = Some 105. }) }))
  in
  let poll ?(id = "one") ~at m result =
    reply ~at m (Msg.Reply_oauth_attempt_status { keeper; provider; attempt_id = id; result })
  in
  let status kind =
    match Wire_keeper_context.decode_oauth_attempt_status (`Assoc [ "kind", `String kind ]) with
    | Ok st -> Ok st
    | Error reason -> Alcotest.fail reason
  in
  let deadline (m : Model.t) =
    Keeper_context_store.next_oauth_poll_deadline_ns ~now_ns:(Clock.Mono.to_ns now) m.keeper_context
  in
  let pending = start "one" initial in
  let active, _ = poll ~at:now pending (status "awaiting_consent") in
  let quiet, _ = poll ~at:later active (status "awaiting_consent") in
  Alcotest.(check bool) "unchanged consent keeps the current toast deadline" true (active.toast = quiet.toast);
  let admitted, _ = poll ~at:later quiet (status "callback_admitted") in
  Alcotest.(check bool) "callback admission is a new observation" true (quiet.toast <> admitted.toast);
  List.iter (fun active ->
    let limit = Clock.Mono.after_s now 601. in
    let _, cmds = Update.step ~now:limit active (Msg.Tick { wall_unix = 701. }) in
    Alcotest.(check bool) "a healthy login still reads the server outcome after consent expiry" true
      (List.mem (Cmd.Http_get { epoch = active.epoch; req = Cmd.Get_oauth_attempt_status
          { keeper; provider; attempt_id = "one" } }) (Cmd.flatten cmds)))
    [ quiet; admitted ];
  List.iter (fun kind ->
    let stopped, cmds = poll ~at:later admitted (status kind) in
    Alcotest.(check (option int64)) kind None (deadline stopped);
    let expected =
      if String.equal kind "completed" then
        [ Cmd.Http_get { epoch = stopped.epoch; req = Cmd.Get_oauth_attached_tools { keeper } } ]
      else []
    in
    Alcotest.(check bool) "only published credentials refresh attached tools" true (Cmd.flatten cmds = expected);
    let late, cmds = poll ~at:later stopped (status "awaiting_consent") in
    Alcotest.(check bool) "settled attempt ignores a late reply" true
      (late.toast = stopped.toast && Cmd.flatten cmds = [] && deadline late = None))
    [ "unavailable"; "superseded"; "credential_publication_incomplete"; "failed"; "expired"; "completed" ];
  let outage = Error (Msg.Http_error { status = 503; body = "unavailable"; api_error = None }) in
  let first, _ = poll ~at:now pending outage in
  let repeated, _ = poll ~at:later first (Error (Msg.Transport Health.Stream_eof)) in
  Alcotest.(check bool) "retryable reads stay live inside the server login window" true (Option.is_some (deadline repeated));
  Alcotest.(check int) "one incident for the outage" 1 (Incidents.count repeated.incidents);
  Alcotest.(check bool) "repeated transport errors preserve other notifications" true (first.toast = repeated.toast);
  let recovered, _ = poll ~at:later repeated (status "awaiting_consent") in
  let failed_again, _ = poll ~at:later recovered outage in
  Alcotest.(check int) "a recovered read separates outages" 2 (Incidents.count failed_again.incidents);
  let expired, _ = Update.step ~now:(Clock.Mono.after_s now 5.) repeated
    (Msg.Tick { wall_unix = 105. }) in
  Alcotest.(check (option int64)) "the server-issued deadline halts automatic retry" None
    (Keeper_context_store.next_oauth_poll_deadline_ns ~now_ns:(Clock.Mono.to_ns now)
       ~wall_unix:105. expired.keeper_context);
  let invalid, _ = poll ~at:now pending (Error (Msg.Decode_error "unknown OAuth status")) in
  Alcotest.(check (option int64)) "a malformed status stops immediately" None (deadline invalid);
  let replacement = start "two" pending in
  let late, cmds = poll ~at:later replacement (status "completed") in
  Alcotest.(check bool) "a replaced attempt cannot complete the active login" true
    (late.toast = replacement.toast && Cmd.flatten cmds = [] && Option.is_some (deadline late));
  let reconnect, _ = Update.step ~now:later replacement (Msg.Server_start_result (Ok ())) in
  Alcotest.(check (option int64)) "a new server epoch drops process-owned attempts" None (deadline reconnect);
  let stale, cmds = Update.step ~now:later reconnect (Msg.Http_reply { epoch = initial.epoch;
    reply = Msg.Reply_oauth_attempt_status { keeper; provider; attempt_id = "two"; result = status "completed" } }) in
  Alcotest.(check bool) "the preceding epoch cannot refresh tools" true
    (stale.toast = reconnect.toast && Cmd.flatten cmds = [])

let test_oauth_auto_open_input_and_tick_poll () =
  let t0 = Clock.Mono.of_ns 10_000_000_000L in
  let t1 = Clock.Mono.after_s t0 1.0 in
  let t3 = Clock.Mono.after_s t0 2.5 in
  let t10 = Clock.Mono.after_s t0 10.0 in
  (* 1. Wire contracts: ANSI-safe URL/code extraction & exact 2-field login input *)
  Alcotest.(check (option string)) "extract_https_url strips ANSI and trailing punct"
    (Some "https://auth.openai.com/oauth/authorize?code_challenge=xyz")
    (Wire_runtime.extract_https_url
       "\027[1;34mOpen https://auth.openai.com/oauth/authorize?code_challenge=xyz).\027[0m");
  Alcotest.(check (option string)) "extract_device_code extracts hyphenated code"
    (Some "ABCD-1234")
    (Wire_runtime.extract_device_code "Enter one-time code: ABCD-1234 now");
  Alcotest.(check (option string)) "extract_device_code rejects pure digits date"
    None
    (Wire_runtime.extract_device_code "Enter code on 2026-1124");
  Alcotest.(check (option string)) "extract_device_code rejects unguarded HTTP-4000"
    None
    (Wire_runtime.extract_device_code "Status: HTTP-4000 OK");
  Alcotest.(check (option string)) "extract_device_code rejects colon label"
    None
    (Wire_runtime.extract_device_code "Enter AUTH-CODE: pending");
  Alcotest.(check string) "setup login start path opts into auth_hints=1"
    "/api/v1/setup/accounts/login?auth_hints=1"
    (Cmd.post_request_path
       (Cmd.Post_setup_login_start
          { integration_id = "codex_cli"; account_ref = None }));
  let txt_req =
    Cmd.Post_setup_login_input
      {
        login_id = "login-9";
        input = Wire_runtime.Setup_login_text "123456";
      }
  in
  Alcotest.(check string) "setup login input path"
    "/api/v1/setup/accounts/login/login-9/input"
    (Cmd.post_request_path txt_req);
  Alcotest.(check string) "setup login text JSON (exact 2 fields)"
    {|{"kind":"text","text":"123456"}|}
    (Yojson.Safe.to_string (Cmd.post_request_body txt_req));
  let key_req =
    Cmd.Post_setup_login_input
      {
        login_id = "login-9";
        input = Wire_runtime.Setup_login_key Wire_runtime.Login_key_enter;
      }
  in
  Alcotest.(check string) "setup login key JSON (exact 2 fields)"
    {|{"kind":"key","key":"enter"}|}
    (Yojson.Safe.to_string (Cmd.post_request_body key_req));
  (* 2. Setup_login_output auto-opens first https:// URL once & deduplicates subsequent URLs *)
  let m0 = Model.initial () in
  let m1, out1_cmds =
    Update.step ~now:t0 m0
      (Msg.Setup_login_output
         {
           epoch = m0.epoch;
           text = "Visit https://auth.example.com/device Code: WXYZ-4321";
           auth_url = Some "https://auth.example.com/device";
           device_code = Some "WXYZ-4321";
         })
  in
  Alcotest.(check (option string)) "setup_login_auth_url recorded"
    (Some "https://auth.example.com/device") m1.runtime.setup_login_auth_url;
  Alcotest.(check (option string)) "setup_login_device_code recorded"
    (Some "WXYZ-4321") m1.runtime.setup_login_device_code;
  Alcotest.(check bool) "first Setup_login_output emits Open_external_url" true
    (List.exists
       (function
         | Cmd.Open_external_url "https://auth.example.com/device" -> true
         | _ -> false)
       (Cmd.flatten out1_cmds));
  let _, out2_cmds =
    Update.step ~now:t1 m1
      (Msg.Setup_login_output
         {
           epoch = m1.epoch;
           text = "Repeated https://auth.example.com/other";
           auth_url = Some "https://auth.example.com/other";
           device_code = None;
         })
  in
  Alcotest.(check int) "subsequent Setup_login_output does not re-open browser" 0
    (List.length (Cmd.flatten out2_cmds));
  (* 3. Setup_login_input_ready is a post-write ack (no auto-open loop); [e] on Runtime > Quotas opens input modal; terminal 'interrupted'/'complete' closes modal *)
  let m_running, _ =
    Update.step ~now:t0
      {
        m1 with
        nav = { m1.nav with workspace = Nav.Runtime; sidebar_focused = false };
        runtime = Runtime_store.set_tab Nav.Runtime_quotas_credits m1.runtime;
      }
      (Msg.Http_reply
         {
           epoch = m1.epoch;
           reply =
             Msg.Reply_setup_login_receipt
               (Ok
                  {
                    login_id = "login-9";
                    integration_id = "codex_cli";
                    status = "running";
                    account = None;
                    account_ref = None;
                    authentication = None;
                  });
         })
  in
  let m_ack_ready, ack_ready_cmds =
    Update.step ~now:t0 m_running
      (Msg.Setup_login_input_ready
         { epoch = m_running.epoch; login_id = Some "login-9" })
  in
  Alcotest.(check bool) "setup_login_input_ready marked true without auto-opening modal"
    true
    (m_ack_ready.runtime.setup_login_input_ready
    && Option.is_none m_ack_ready.nav.overlay
    && Cmd.flatten ack_ready_cmds = []);
  let m_in_open, _ =
    Update.step ~now:t0 m_ack_ready (Msg.Key_event (char_key "e"))
  in
  (match m_in_open.nav.overlay with
  | Some (Nav.Inline_action (Nav.Setup_login_input_form { login_id = "login-9" })) ->
      ()
  | _ -> Alcotest.fail "[e] on Runtime > Quotas during active login must open Setup_login_input_form");
  let m_typed =
    match m_in_open.inline_modal with
    | None -> Alcotest.fail "expected inline_modal"
    | Some st ->
        let fields =
          List.map
            (fun (f : Model.modal_form_field) ->
              if String.equal f.key "setup_login_input" then
                { f with value = "987654" }
              else f)
            st.fields
        in
        { m_in_open with inline_modal = Some { st with fields } }
  in
  let m_sub, sub_cmds =
    Update.step ~now:t0 m_typed (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "submitting login input clears ready flag" false
    m_sub.runtime.setup_login_input_ready;
  Alcotest.(check bool) "submitting text emits Post_setup_login_input(Setup_login_text)"
    true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_setup_login_input
                   {
                     login_id = "login-9";
                     input = Wire_runtime.Setup_login_text "987654";
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten sub_cmds));
  let _, blank_cmds =
    Update.step ~now:t0 m_in_open (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "blank Enter emits Setup_login_key(Login_key_enter)" true
    (List.exists
       (function
         | Cmd.Http_post
             {
               req =
                 Cmd.Post_setup_login_input
                   {
                     login_id = "login-9";
                     input =
                       Wire_runtime.Setup_login_key Wire_runtime.Login_key_enter;
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten blank_cmds));
  let m_interrupted, _ =
    Update.step ~now:t1 m_in_open
      (Msg.Http_reply
         {
           epoch = m_in_open.epoch;
           reply =
             Msg.Reply_setup_login_receipt
               (Ok
                  {
                    login_id = "login-9";
                    integration_id = "codex_cli";
                    status = "interrupted";
                    account = None;
                    account_ref = None;
                    authentication = None;
                  });
         })
  in
  Alcotest.(check bool) "interrupted setup login receipt auto-closes modal with error toast"
    true
    (Option.is_none m_interrupted.inline_modal
    && Option.is_none m_interrupted.nav.overlay
    && match m_interrupted.toast with
       | Some { level = Model.Toast_error; _ } -> true
       | _ -> false);
  let m_term, _ =
    Update.step ~now:t1 m_in_open
      (Msg.Http_reply
         {
           epoch = m_in_open.epoch;
           reply =
             Msg.Reply_setup_login_receipt
               (Ok
                  {
                    login_id = "login-9";
                    integration_id = "codex_cli";
                    status = "complete";
                    account = Some "keyring_host";
                    account_ref = None;
                    authentication = Some "login_completed";
                  });
         })
  in
  Alcotest.(check bool) "terminal setup login receipt auto-closes open input modal"
    true
    (Option.is_none m_term.inline_modal && Option.is_none m_term.nav.overlay);
  (* 4. Keeper OAuth exchange auto-opens authorize_url & ticks poll every 2s until settled *)
  let _, idle_tick_cmds =
    Update.step ~now:t0 m0 (Msg.Tick { wall_unix = 100.0 })
  in
  Alcotest.(check int) "idle Tick emits zero HTTP polling commands" 0
    (List.length (Cmd.flatten idle_tick_cmds));
  let m_oauth, oauth_cmds =
    Update.step ~now:t0 m0
      (Msg.Http_reply
         {
           epoch = m0.epoch;
           reply =
             Msg.Reply_oauth_login
               {
                 keeper = "keeper-a";
                 result =
                   Ok
                     (Wire_keeper_context.Oauth_login_exchange
                        {
                          provider = "github";
                          provider_label = "GitHub";
                          authorize_url =
                            "https://github.com/login/oauth/authorize?state=s1";
                          attempt_id = "att-7";
                          expires_at = None;
                        });
               };
         })
  in
  Alcotest.(check bool) "Oauth_login_exchange immediately emits Open_external_url"
    true
    (List.exists
       (function
         | Cmd.Open_external_url
             "https://github.com/login/oauth/authorize?state=s1" ->
             true
         | _ -> false)
       (Cmd.flatten oauth_cmds));
  let m_poll1, poll1_cmds =
    Update.step ~now:t0 m_oauth (Msg.Tick { wall_unix = 101.0 })
  in
  Alcotest.(check bool) "first Tick emits Get_oauth_attempt_status" true
    (List.exists
       (function
         | Cmd.Http_get
             {
               req =
                 Cmd.Get_oauth_attempt_status
                   {
                     keeper = "keeper-a";
                     provider = "github";
                     attempt_id = "att-7";
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten poll1_cmds));
  let m_poll_cool, cool_cmds =
    Update.step ~now:t1 m_poll1 (Msg.Tick { wall_unix = 102.0 })
  in
  Alcotest.(check int) "Tick within 2s cooldown emits no duplicate poll" 0
    (List.length (Cmd.flatten cool_cmds));
  let m_poll2, poll2_cmds =
    Update.step ~now:t3 m_poll_cool (Msg.Tick { wall_unix = 104.0 })
  in
  Alcotest.(check bool) "Tick after 2s cooldown polls attempt status again" true
    (List.exists
       (function
         | Cmd.Http_get
             {
               req =
                 Cmd.Get_oauth_attempt_status
                   {
                     keeper = "keeper-a";
                     provider = "github";
                     attempt_id = "att-7";
                   };
               _;
             } ->
             true
         | _ -> false)
       (Cmd.flatten poll2_cmds));
  let m_settled, settled_cmds =
    Update.step ~now:t3 m_poll2
      (Msg.Http_reply
         {
           epoch = m_poll2.epoch;
           reply =
             Msg.Reply_oauth_attempt_status
               {
                 keeper = "keeper-a"; provider = "github"; attempt_id = "att-7";
                 result =
                   Ok
                     {
                       kind = "completed";
                       expires_at = None;
                       detail = None;
                     };
               };
         })
  in
  Alcotest.(check bool) "completed attempt refreshes attached tools" true
    (List.exists
       (function
         | Cmd.Http_get
             { req = Cmd.Get_oauth_attached_tools { keeper = "keeper-a" }; _ } ->
             true
         | _ -> false)
       (Cmd.flatten settled_cmds));
  let _, after_settled_cmds =
    Update.step ~now:t10 m_settled (Msg.Tick { wall_unix = 110.0 })
  in
  Alcotest.(check int) "settled attempt stops Tick auto-polling (0 Hz)" 0
    (List.length (Cmd.flatten after_settled_cmds));
  Alcotest.(check (option int64)) "settled attempt clears OAuth tick deadline" None
    (Keeper_context_store.next_oauth_poll_deadline_ns
       ~now_ns:(Clock.Mono.to_ns t10) m_settled.keeper_context);
  (* All server terminal kinds settle immediately (0 Hz) *)
  List.iter
    (fun kind ->
      Alcotest.(check bool) ("settled terminal kind: " ^ kind) true
        (Keeper_context_store.is_oauth_attempt_settled kind))
    [ "unavailable"; "superseded"; "credential_publication_incomplete" ];
  (* Wall-clock expires_at cap halts polling *)
  let m_exp, _ =
    Update.step ~now:t0 m0
      (Msg.Http_reply
         {
           epoch = m0.epoch;
           reply =
             Msg.Reply_oauth_login
               {
                 keeper = "keeper-a";
                 result =
                   Ok
                     (Wire_keeper_context.Oauth_login_exchange
                        {
                          provider = "github";
                          provider_label = "GitHub";
                          authorize_url = "https://github.com/login/oauth/authorize";
                          attempt_id = "att-exp";
                          expires_at = Some 500.0;
                        });
               };
         })
  in
  let _, exp_cmds =
    Update.step ~now:t10 m_exp (Msg.Tick { wall_unix = 501.0 })
  in
  Alcotest.(check int) "expired expires_at stops Tick polling" 0
    (List.length (Cmd.flatten exp_cmds));
  Alcotest.(check (option int64)) "expired expires_at clears deadline" None
    (Keeper_context_store.next_oauth_poll_deadline_ns
       ~now_ns:(Clock.Mono.to_ns t10) ~wall_unix:501.0 m_exp.keeper_context);
  (* 5 consecutive 5xx poll errors cap retries to preserve 0 Hz idle *)
  let m_5xx =
    let rec fail_n n m =
      if n <= 0 then m
      else
        let m', _ =
          Update.step ~now:t3 m
            (Msg.Http_reply
               {
                 epoch = m.epoch;
                 reply =
                   Msg.Reply_oauth_attempt_status
                     {
                       keeper = "keeper-a"; provider = "github"; attempt_id = "att-7";
                       result =
                         Error
                           (Msg.Http_error
                              { status = 502; body = "bad gateway"; api_error = None });
                     };
               })
        in
        fail_n (n - 1) m'
    in
    fail_n 5 m_poll2
  in
  let _, after_5xx_cmds =
    Update.step ~now:t10 m_5xx (Msg.Tick { wall_unix = 112.0 })
  in
  Alcotest.(check int) "5 consecutive 5xx errors halt Tick auto-polling" 0
    (List.length (Cmd.flatten after_5xx_cmds));
  Alcotest.(check (option int64)) "5 consecutive 5xx errors clear OAuth deadline" None
    (Keeper_context_store.next_oauth_poll_deadline_ns
       ~now_ns:(Clock.Mono.to_ns t10) m_5xx.keeper_context);
  (* 404 attempt status error also clears pending poll to avoid infinite retries *)
  let m_err404, _ =
    Update.step ~now:t3 m_poll2
      (Msg.Http_reply
         {
           epoch = m_poll2.epoch;
           reply =
             Msg.Reply_oauth_attempt_status
               {
                 keeper = "keeper-a"; provider = "github"; attempt_id = "att-7";
                 result =
                   Error
                     (Msg.Http_error
                        { status = 404; body = "not found"; api_error = None });
               };
         })
  in
  let _, after_404_cmds =
    Update.step ~now:t10 m_err404 (Msg.Tick { wall_unix = 111.0 })
  in
  Alcotest.(check int) "404 attempt error halts Tick auto-polling" 0
    (List.length (Cmd.flatten after_404_cmds));
  (* 5. Github_login_chunk auto-opens first device_url once *)
  let m_gh1, gh1_cmds =
    Update.step ~now:t0 m0
      (Msg.Github_login_chunk
         {
           epoch = m0.epoch;
           keeper = "keeper-a";
           text =
             "First copy your one-time code: ABCD-5678\nOpen https://github.com/login/device";
         })
  in
  Alcotest.(check bool) "first Github_login_chunk with device URL emits Open_external_url"
    true
    (List.exists
       (function
         | Cmd.Open_external_url "https://github.com/login/device" -> true
         | _ -> false)
       (Cmd.flatten gh1_cmds));
  let _, gh2_cmds =
    Update.step ~now:t1 m_gh1
      (Msg.Github_login_chunk
         {
           epoch = m_gh1.epoch;
           keeper = "keeper-a";
           text = "Still waiting on https://github.com/login/device";
         })
  in
  Alcotest.(check int) "subsequent Github_login_chunk does not re-open browser" 0
    (List.length (Cmd.flatten gh2_cmds))

let test_skill_mutation_reference () =
  let now = Clock.Mono.zero in
  let initial = Model.initial () in
  let reference_json name source revision =
    `Assoc [ "identity", `Assoc [ "source_id", `String source; "package_id", `String name; "name", `String name ];
             "content_revision", `String revision ]
  in
  let surface reference source : Wire_runtime.skill_surface_entry =
    { reference; reference_json = Some (reference_json reference source "rev");
      kind = "instruction"; summary = None; error = None }
  in
  let alpha = surface "compile-alpha" "workshop" and beta = surface "compile-beta" "team" in
  let catalog surfaces =
    let snap : Wire_runtime.skills_snapshot =
      { state = "ready"; snapshot_revision = Some "rev"; surfaces; shadows = []; rejections = [] } in
    { initial with runtime = Runtime_store.apply_skills ~observed_at:now snap initial.runtime }
  in
  let available = catalog [alpha; beta] in
  let beta_json = reference_json beta.reference "team" "rev" in
  let loaded reference_json access : Wire_runtime.skill_editor_loaded =
    { reference = beta.reference; reference_json;
      snapshot_revision = "rev"; source_text = "before"; access }
  in
  let cached ?(reference_json = beta_json) access =
    { available with runtime = Runtime_store.apply_skill_editor_loaded ~observed_at:now
        ~reference:"compile" (loaded reference_json access) available.runtime }
  in
  let submit m kind text =
    let opened, _ = Update_nav.open_inline_modal m kind in
    match opened.inline_modal with
    | None -> Alcotest.fail "skill form did not open"
    | Some form ->
        let typed = Model.modal_update_active_field (fun _ -> text) form in
        let _, cmds = Update_nav.submit_inline_modal ~now { opened with inline_modal = Some typed } in
        Cmd.flatten cmds
  in
  let mutations m reference =
    submit m (Nav.Skill_edit_form { reference }) "after",
    submit m (Nav.Skill_delete_confirm { reference }) "DELETE"
  in
  let expect_none m reference =
    Alcotest.(check bool) ("no save or delete for " ^ reference) true
      (mutations m reference = ([], []))
  in
  let exact =
    [Cmd.Http_post {epoch = initial.epoch; req = Cmd.Post_skill_editor_save
         { reference = beta.reference; reference_json = beta_json; source_text = "after" }}],
    [Cmd.Http_delete {epoch = initial.epoch; req = Cmd.Delete_skill_editor
         { reference = beta.reference; reference_json = beta_json; confirmed = true }}]
  in
  List.iter (fun m ->
    List.iter (expect_none m) [ "compile"; ""; "  "; "COMPILE-BETA"; " compile-beta " ];
    Alcotest.(check bool) "exact operations keep the selected structured reference" true
      (mutations m beta.reference = exact)) [available; cached Wire_runtime.Skill_read_write];
  let alias = cached Wire_runtime.Skill_read_write in
  let edit, _ = Update_actions.execute_slash ~now alias (Slash.Skill (Slash.Skill_edit "compile")) in
  Alcotest.(check bool) "previous read alias cannot open another skill's edit form" true
    (Option.is_none edit.inline_modal);
  expect_none (catalog [beta; surface beta.reference "other-source"]) beta.reference;
  expect_none (cached ~reference_json:(reference_json beta.reference "team" "earlier-revision")
                 Wire_runtime.Skill_read_write) beta.reference;
  expect_none (cached Wire_runtime.Skill_read_only) beta.reference

let test_preset_denial_refresh () =
  let now = Clock.Mono.zero in
  let initial = Model.initial () in
  let view, _ = Update_actions.execute_slash ~now initial (Slash.Preset Slash.Preset_list) in
  let deny (m : Model.t) = fst (Update.step ~now m
    (Msg.Http_reply {epoch = m.epoch; reply = Msg.Reply_presets
      (Error (Msg.Http_error {status = 403; body = ""; api_error = None}))})) in
  let get = Cmd.Http_get {epoch = view.epoch; req = Cmd.Get_presets} in
  let denied = deny view in
  Alcotest.(check bool) "denied presets suppress passive reads" true
    (denied.runtime.presets_auth_denied && not (List.mem get (View_fetches.fetches_for_current_view denied)));
  let refreshed, cmds = Update_actions.execute_action ~now denied Keymap.Refresh in
  Alcotest.(check bool) "refresh clears the denial and requests the current presets" true
    (not refreshed.runtime.presets_auth_denied && List.mem get (Cmd.flatten cmds));
  let denied_again = deny refreshed in
  Alcotest.(check bool) "a new denial suppresses subsequent passive reads" true
    (denied_again.runtime.presets_auth_denied &&
     not (List.mem get (View_fetches.fetches_for_current_view denied_again)))

let test_layer1_input_esc_focus_traps () =
  (* #1: Failed Reply_turn_interrupt must not trap Esc in Dive_keeper forever,
     while explicit Ctrl+X remains retryable on the same active operation. *)
  let keeper = "alpha" in
  let m_chat_run =
    let base = Model.initial () in
    let base =
      {
        base with
        nav =
          {
            base.nav with
            workspace = Nav.Keepers;
            dive_stack =
              [ Nav.Dive_keeper { name = keeper; tab = Nav.Keeper_chat } ];
          };
        drafts =
          base.drafts |> Drafts.set_active_keeper keeper
          |> Drafts.insert_text "hello" |> Drafts.set_focus false;
      }
    in
    let m_sub, _ = Update.execute_action ~now:t0 base Keymap.Submit_steer in
    let tx_s =
      match Drafts.active_tx_for_keeper ~keeper m_sub.drafts with
      | Some tx -> tx
      | None -> Alcotest.fail "missing submitted tx"
    in
    let m_acc, _ =
      Update.step ~now:t0 m_sub
        (Msg.Chat_stream_chunk
           {
             epoch = m_sub.epoch;
             keeper;
             request_id = tx_s.request_id;
             is_btw = false;
             chunk =
               Wire_fleet.Chunk_accepted
                 {
                   operation_id = tx_s.request_id;
                   queued_count = 0;
                   state = Keeper_chat_operation.State_name.Running;
                   interactive_outcome = None;
                   control_token = None;
                 };
           })
    in
    m_acc
  in
  let has_interrupt_post cmds =
    List.exists
      (function
        | Cmd.Http_post { req = Cmd.Post_keeper_turn_interrupt _; _ } -> true
        | _ -> false)
      (Cmd.flatten cmds)
  in
  let m_esc1, cmds_esc1 =
    Update.step ~now:t1 m_chat_run (Msg.Key_event (key Keymap.Input.Escape))
  in
  Alcotest.(check bool) "#1: first Esc sends Post_keeper_turn_interrupt" true
    (has_interrupt_post cmds_esc1);
  let target =
    match
      List.find_map
        (function
          | Cmd.Http_post
              { req = Cmd.Post_keeper_turn_interrupt { target; _ }; _ } ->
              Some target
          | _ -> None)
        (Cmd.flatten cmds_esc1)
    with
    | Some t -> t
    | None -> Alcotest.fail "expected interrupt target"
  in
  let m_int_err, _ =
    Update.step ~now:t2 m_esc1
      (Msg.Http_reply
         {
           epoch = m_esc1.epoch;
           reply =
             Msg.Reply_turn_interrupt
               {
                 keeper;
                 target;
                 result = Error (Msg.Transport (Health.Other_io "503"));
               };
         })
  in
  let _, cmds_ctrlx =
    Update.step ~now:t2 m_int_err (Msg.Key_event (char_key ~ctrl:true "x"))
  in
  Alcotest.(check bool)
    "#1: Ctrl+X stays retryable after failed interrupt" true
    (has_interrupt_post cmds_ctrlx);
  let m_esc2, cmds_esc2 =
    Update.step ~now:t2 m_int_err (Msg.Key_event (key Keymap.Input.Escape))
  in
  Alcotest.(check bool)
    "#1: second Esc exits Dive_keeper instead of looping after failed interrupt"
    true (Option.is_none (Model.active_dive m_esc2));
  Alcotest.(check bool) "#1: second Esc sends 0 duplicate interrupt POSTs" false
    (has_interrupt_post cmds_esc2);

  (* #3: Universal pane_index clamp on Update.step + Tab recovery from stale pane_index *)
  let m_tasks0 =
    let base = Model.initial ~cols:140 ~rows:40 () in
    {
      base with
      nav = { base.nav with workspace = Nav.Work; pane_index = 2 };
      work = Work_store.set_tab Nav.Work_tasks base.work;
    }
  in
  let m_tasks_clamped, _ =
    Update.step ~now:t0 m_tasks0 (Msg.Tick { wall_unix = 1_795_254_000.0 })
  in
  Alcotest.(check int)
    "#3: Update.step clamps stale pane_index=2 down to focusable_pane_count - 1 (1)"
    1 m_tasks_clamped.nav.pane_index;
  let m_stale_1pane =
    let base = Model.initial ~cols:100 ~rows:30 () in
    {
      base with
      nav =
        {
          base.nav with
          workspace = Nav.Work;
          sidebar_open = Some false;
          pane_index = 2;
        };
      work =
        Work_store.set_tab Nav.Work_inbox base.work
        |> Work_store.apply_asks ~observed_at:t0 [];
    }
    |> Model.rebuild_attention
  in
  let m_tab_rec, _ =
    Update.step ~now:t0 m_stale_1pane (Msg.Key_event (key Keymap.Input.Tab))
  in
  Alcotest.(check int) "#3: Tab recovers pane_index=0 from stale pane_index" 0
    m_tab_rec.nav.pane_index;

  (* #7: Board_recovery Esc cascade & sub-tab cleanup *)
  let m_br0 =
    let base = Model.initial ~cols:140 ~rows:40 () in
    {
      base with
      nav =
        {
          base.nav with
          workspace = Nav.Keepers;
          dive_stack =
            [ Nav.Dive_keeper { name = "alpha"; tab = Nav.Keeper_work_candle } ];
        };
      knowledge =
        {
          base.knowledge with
          board_recovery =
            Board_recovery.open_view ~keeper:"alpha"
              base.knowledge.board_recovery;
        };
    }
  in
  let m_br_esc1, _ =
    Update.step ~now:t0 m_br0 (Msg.Key_event (key Keymap.Input.Escape))
  in
  Alcotest.(check bool) "#7: first Esc closes Board_recovery" false
    (Board_recovery.shown ~keeper:"alpha" m_br_esc1.knowledge.board_recovery);
  Alcotest.(check bool) "#7: first Esc stays inside Dive_keeper" true
    (Option.is_some (Model.active_dive m_br_esc1));
  let m_br_esc2, _ =
    Update.step ~now:t0 m_br_esc1 (Msg.Key_event (key Keymap.Input.Escape))
  in
  Alcotest.(check bool) "#7: second Esc exits Dive_keeper" true
    (Option.is_none (Model.active_dive m_br_esc2));
  let m_br_tab, _ =
    Update.step ~now:t0 m_br0 (Msg.Key_event (char_key "]"))
  in
  Alcotest.(check bool) "#7: cycling keeper sub-tab closes Board_recovery" false
    (Board_recovery.shown ~keeper:"alpha" m_br_tab.knowledge.board_recovery);

  (* #8: Alt+] sub-tab switch clears filter_focused *)
  let m_flt =
    let base = Model.initial ~cols:140 ~rows:40 () in
    {
      base with
      nav = { base.nav with workspace = Nav.Work; filter_focused = true };
      work = Work_store.set_tab Nav.Work_inbox base.work;
    }
  in
  let m_flt_next, _ =
    Update.step ~now:t0 m_flt (Msg.Key_event (char_key ~alt:true "]"))
  in
  Alcotest.(check bool) "#8: Alt+] switches Work tab" true
    (not (Nav.equal_work_tab m_flt_next.work.active_tab Nav.Work_inbox));
  Alcotest.(check bool) "#8: Alt+] clears filter_focused" false
    m_flt_next.nav.filter_focused;

  (* #10: Async Voice_transcript appends text without hijacking overlay/filter/Micro focus *)
  let m_ov_voice =
    let base = Model.initial ~cols:140 ~rows:40 () in
    {
      base with
      nav =
        {
          base.nav with
          overlay = Some (Nav.Settings Nav.Settings_general_ui);
        };
    }
  in
  let m_ov_after, _ =
    Update.step ~now:t0 m_ov_voice
      (Msg.Voice_event (Msg.Voice_transcript "dictated text"))
  in
  Alcotest.(check string) "#10: voice transcript appended while overlay open"
    "dictated text" (Drafts.current_draft m_ov_after.drafts).text;
  Alcotest.(check bool) "#10: voice transcript does not steal composer focus over overlay"
    false (Drafts.is_focused m_ov_after.drafts);
  Alcotest.(check bool) "#10: Settings overlay stays open" true
    (Option.is_some m_ov_after.nav.overlay);
  let m_micro_voice = Model.initial ~cols:60 ~rows:20 () in
  let m_micro_after, _ =
    Update.step ~now:t0 m_micro_voice
      (Msg.Voice_event (Msg.Voice_transcript "micro voice"))
  in
  Alcotest.(check bool) "#10: voice transcript does not focus composer on Micro"
    false (Drafts.is_focused m_micro_after.drafts);

  (* #13a: Artifact_dive [N] searches previous match instead of Approval Strip Fast_deny_top *)
  let art : Wire_knowledge.artifact_entry =
    {
      id = "art-search-1";
      revision = 1;
      title = "Searchable Doc";
      summary = "";
      author = "alpha";
      created_at_unix = 1_795_254_000.0;
      body = { sha256 = "sha-search-1"; bytes = 64; mime = "text/markdown" };
    }
  in
  let detail : Wire_knowledge.published_artifact_detail =
    {
      artifact = art;
      content = "needle line 1\n\nfiller\n\nneedle line 2";
      revisions = [];
      shared = false;
      share_version = 1;
    }
  in
  let m_art_n =
    let base = Model.initial ~cols:140 ~rows:40 () in
    let knowledge =
      Knowledge_store.empty
      |> Knowledge_store.apply_artifacts ~observed_at:t0 [ art ]
      |> Knowledge_store.apply_artifact_detail ~observed_at:t0 detail
      |> Knowledge_store.set_artifact_search "needle"
    in
    let work =
      base.work
      |> Work_store.apply_tool_approvals ~observed_at:t0
           [ sample_tool_approval ~id:"ap-strip-1" ~keeper:"alpha" () ]
    in
    {
      base with
      work;
      knowledge;
      nav =
        {
          base.nav with
          workspace = Nav.Knowledge;
          dive_stack = [ Nav.Dive_knowledge (Nav.Artifact_dive art.id) ];
        };
    }
    |> Model.rebuild_attention
  in
  let m_art_after_n, cmds_art_n =
    Update.step ~now:t0 m_art_n (Msg.Key_event (char_key "N"))
  in
  Alcotest.(check bool) "#13a: [N] in Artifact_dive does not open deny modal"
    true (Option.is_none m_art_after_n.nav.overlay);
  Alcotest.(check int) "#13a: [N] in Artifact_dive emits 0 approval POSTs" 0
    (List.length (Cmd.flatten cmds_art_n));
  Alcotest.(check int) "#13a: [N] steps to previous search match (wraps to idx 1)"
    1 m_art_after_n.knowledge.artifact_search_match_idx;

  (* #13b & #19b & #19c: Settings edit/dirty Global guards, narrow resize Pane_inspector, Micro Settings / *)
  let schema_str_bool : Wire_config.config_schema =
    {
      target = Wire_config.Target_runtime;
      keeper = None;
      file_exists = true;
      file_sha256 = "sha-l1";
      sections =
        [
          {
            id = "providers";
            category = Wire_config.Cat_providers_models;
            title = "Providers";
            fields =
              [
                {
                  table = "providers";
                  key = "model";
                  full_key = "providers.model";
                  label = "Model";
                  env = None;
                  description = None;
                  kind = Wire_config.Field_string;
                  value = Wire_config.Val_string "gpt-5";
                  default_value = Some (Wire_config.Val_string "gpt-5");
                  provenance = Wire_config.Prov_default;
                  reload_scope = Wire_config.Hot_reload;
                  secret = false;
                  writable = true;
                };
              ];
          };
        ];
    }
  in
  let m_set_wide =
    let base = Model.initial ~cols:140 ~rows:40 () in
    let config =
      Config_store.empty
      |> Config_store.set_tab Nav.Settings_providers_models
      |> Config_store.apply_schema ~observed_at:t0 schema_str_bool
      |> Config_store.set_pane Config_store.Pane_inspector
    in
    {
      base with
      config;
      nav =
        {
          base.nav with
          overlay = Some (Nav.Settings Nav.Settings_providers_models);
        };
    }
  in
  (* Begin editing text field -> Ctrl+K must NOT abandon edit *)
  let m_set_edit, _ =
    Update.step ~now:t0 m_set_wide (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check bool) "#13b: Settings Enter begins editing text field" true
    (Config_store.is_editing_field m_set_edit.config);
  let m_set_edit_k, _ =
    Update.step ~now:t0 m_set_edit (Msg.Key_event (char_key ~ctrl:true "k"))
  in
  Alcotest.(check bool)
    "#13b: Ctrl+K while editing Settings field stays in Settings editing" true
    (Config_store.is_editing_field m_set_edit_k.config
    && Option.equal Nav.equal_overlay m_set_edit_k.nav.overlay
         (Some (Nav.Settings Nav.Settings_providers_models)));
  (* Commit a field edit. Only two consecutive Esc presses authorize discard. *)
  let m_set_typed, _ =
    Update.step ~now:t0 m_set_edit (Msg.Key_event (char_key "x"))
  in
  let m_set_dirty, _ =
    Update.step ~now:t0 m_set_typed (Msg.Key_event (key Keymap.Input.Enter))
  in
  Alcotest.(check int) "#13b: committed edit stages dirty=1" 1
    (Config_store.dirty_count m_set_dirty.config);
  let press m ev = Update.step ~now:t0 m (Msg.Key_event ev) in
  let open_settings m =
    Option.equal Nav.equal_overlay m.Model.nav.overlay
      (Some (Nav.Settings Nav.Settings_providers_models))
  in
  let check_blocked label m ev =
    let next, commands = press m ev in
    Alcotest.(check bool) label true
      (open_settings next && Config_store.dirty_count next.config = 1
       && not next.config.discard_confirm_armed && List.is_empty commands
       && match next.toast with
          | Some { level = Model.Toast_warning; _ } -> true
          | Some _ | None -> false);
    next
  in
  let palette_key = char_key ~ctrl:true "k" in
  let after_palette =
    check_blocked "dirty Ctrl+K retains the edit without arming discard"
      m_set_dirty palette_key
  in
  let after_repeat =
    check_blocked "repeated Ctrl+K leaves discard unarmed" after_palette palette_key
  in
  let after_help =
    check_blocked "Settings ? also protects the edit" after_repeat (char_key "?")
  in
  let after_first_esc, _ = press after_help (key Keymap.Input.Escape) in
  Alcotest.(check bool) "first Esc arms discard and keeps the edit" true
    (open_settings after_first_esc && after_first_esc.config.discard_confirm_armed
     && Config_store.dirty_count after_first_esc.config = 1);
  let after_close, _ = press after_first_esc (key Keymap.Input.Escape) in
  Alcotest.(check bool) "second Esc closes Settings and discards the edit" true
    (Option.is_none after_close.nav.overlay && Config_store.dirty_count after_close.config = 0
     && not after_close.config.discard_confirm_armed);
  let after_retry, _ = press after_close palette_key in
  Alcotest.(check bool) "Ctrl+K opens the palette after explicit discard" true
    (Option.equal Nav.equal_overlay after_retry.nav.overlay (Some Nav.Palette));
  let teleport_key = char_key ~alt:true "j" in
  let no_target, _ = press m_set_dirty teleport_key in
  Alcotest.(check bool) "Alt+J with no target preserves Settings and reports no item" true
    (open_settings no_target && not no_target.config.discard_confirm_armed
     && match no_target.toast with
        | Some { level = Model.Toast_info; _ } -> true
        | Some _ | None -> false);
  let attention =
    Attention.rebuild ~asks:[ sample_ask () ] ~tool_approvals:[]
      ~gate_pending:[] ~goals:[] Attention.empty
  in
  let with_target = { m_set_dirty with attention } in
  let blocked_jump =
    check_blocked "Alt+J protects dirty Settings when it would open an ask"
      with_target teleport_key
  in
  Alcotest.(check bool) "blocked jump leaves the ask unopened" true
    (Option.is_none blocked_jump.ask_modal);
  let clean_jump, _ = press { m_set_wide with attention } teleport_key in
  Alcotest.(check bool) "Alt+J opens that same ask from clean Settings" true
    (Option.equal Nav.equal_overlay clean_jump.nav.overlay (Some Nav.Ask_answer));
  (* Btw_query left via Ctrl+K clears drafts.btw *)
  let m_btw =
    let base = Model.initial ~cols:140 ~rows:40 () in
    {
      base with
      nav = { base.nav with overlay = Some (Nav.Inline_action Nav.Btw_query) };
      inline_modal = Some (Model.inline_modal_for Nav.Btw_query);
      drafts =
        {
          base.drafts with
          btw =
            Drafts.Btw_answered
              { keeper = "alpha"; prompt = "hi"; reply = "pong" };
        };
    }
  in
  let m_btw_k, _ =
    Update.step ~now:t0 m_btw (Msg.Key_event (char_key ~ctrl:true "k"))
  in
  Alcotest.(check bool) "#13b: leaving Btw_query via Ctrl+K clears drafts.btw"
    true
    (match m_btw_k.drafts.btw with Drafts.Btw_idle -> true | _ -> false);

  (* #19a: Ask_answer [?] opens Help and [Esc] restores Ask_answer with ask_modal intact *)
  let ask = sample_ask ~id:"ask-help-1" ~keeper:"alpha" () in
  let m_ask =
    let base = Model.initial ~cols:140 ~rows:40 () in
    {
      base with
      nav = { base.nav with overlay = Some Nav.Ask_answer };
      ask_modal = Some (Model.ask_modal_for ask);
    }
  in
  let m_ask_help, _ =
    Update.step ~now:t0 m_ask (Msg.Key_event (char_key "?"))
  in
  Alcotest.(check bool) "#19a: [?] in Ask_answer opens Help" true
    (Option.equal Nav.equal_overlay m_ask_help.nav.overlay (Some Nav.Help));
  Alcotest.(check bool) "#19a: Help preserves ask_modal for return" true
    (Option.is_some m_ask_help.ask_modal);
  let m_ask_back, _ =
    Update.step ~now:t0 m_ask_help (Msg.Key_event (key Keymap.Input.Escape))
  in
  Alcotest.(check bool) "#19a: Esc from Help returns to Ask_answer" true
    (Option.equal Nav.equal_overlay m_ask_back.nav.overlay (Some Nav.Ask_answer));
  Alcotest.(check bool) "#19a: ask_modal still intact after Help round-trip" true
    (Option.is_some m_ask_back.ask_modal);

  (* #19b: Narrow resize (< 74 cols) normalizes Settings pane to Pane_inspector *)
  let m_set_tree =
    {
      m_set_wide with
      config = Config_store.set_pane Config_store.Pane_tree m_set_wide.config;
    }
  in
  let m_set_narrow, _ =
    Update.step ~now:t0 m_set_tree (Msg.Resize { cols = 68; rows = 28 })
  in
  Alcotest.(check bool)
    "#19b: narrow Resize normalizes Settings pane to Pane_inspector" true
    (match m_set_narrow.config.settings_pane with
    | Config_store.Pane_inspector -> true
    | Config_store.Pane_tree -> false);

  (* #19c: Micro viewport allows [/] inside Settings while keeping bare Micro blocked *)
  let m_micro_set =
    let base = Model.initial ~cols:60 ~rows:20 () in
    {
      base with
      nav =
        {
          base.nav with
          overlay = Some (Nav.Settings Nav.Settings_general_ui);
        };
    }
  in
  let m_micro_set_flt, _ =
    Update.step ~now:t0 m_micro_set (Msg.Key_event (char_key "/"))
  in
  Alcotest.(check bool) "#19c: [/] focuses search in Settings on Micro viewport"
    true m_micro_set_flt.nav.filter_focused;
  let m_micro_bare_flt, _ =
    Update.step ~now:t0 (Model.initial ~cols:60 ~rows:20 ())
      (Msg.Key_event (char_key "/"))
  in
  Alcotest.(check bool) "#19c: [/] stays blocked on bare Micro viewport" false
    m_micro_bare_flt.nav.filter_focused

let test_layer2_pane_scroll_nav_wayfinding () =
  let step m msg = Update.step ~now:t0 m msg in
  let step_k m k = step m (Msg.Key_event k) in

  (* #4: Pulse pane_rects matches left-column [Attention; Companies; Goals] + right full World *)
  let m_pulse =
    let base = Model.initial ~cols:140 ~rows:40 () in
    let work =
      base.work
      |> Work_store.apply_asks ~observed_at:t0
           [ sample_ask ~id:"ask-p" ~keeper:"alpha" () ]
    in
    let fleet =
      Fleet_store.apply_roster ~observed_at:t0
        (roster_of [ sample_keeper "alpha" ])
        base.fleet
    in
    { base with work; fleet } |> Model.rebuild_attention
  in
  let p_rects = Model.pane_rects m_pulse in
  Alcotest.(check int) "#4: Wide Pulse with attention has 4 pane_rects" 4
    (List.length p_rects);
  (match p_rects with
  | [ r_attn; r_comp; r_goals; r_world ] ->
      Alcotest.(check bool) "#4: World sits in right column beside left stack"
        true (r_world.x > r_goals.x && r_world.x > r_comp.x && r_world.x > r_attn.x);
      Alcotest.(check bool) "#4: World spans full main height (taller than Goals)"
        true (r_world.h > r_goals.h);
      Alcotest.(check bool) "#4: Left column stacks Attention -> Companies -> Goals"
        true (r_attn.y < r_comp.y && r_comp.y < r_goals.y);
      let m_click_world, _ =
        step m_pulse
          (Msg.Mouse_event
             (Keymap.Input.Left_press
                { col = r_world.x + 2 + 1; row = r_world.y + 2 + 1 }))
      in
      Alcotest.(check int) "#4: Clicking right column focuses Pulse World (pane 3)"
        3 m_click_world.nav.pane_index;
      let m_click_goals, _ =
        step m_click_world
          (Msg.Mouse_event
             (Keymap.Input.Left_press
                { col = r_goals.x + 2 + 1; row = r_goals.y + 1 + 1 }))
      in
      Alcotest.(check int) "#4: Clicking bottom-left focuses Pulse Goals (pane 2)"
        2 m_click_goals.nav.pane_index
  | _ -> Alcotest.fail "expected 4 Pulse pane rects");

  (* #5a & #5b: Tools_usage_calls summary-only scroll + Tool_dive 2-pane series scroll *)
  let buckets =
    List.init 40 (fun i ->
        {
          Wire_runtime.start_unix = 1_795_200_000.0 +. float_of_int (i * 3600);
          activity =
            Wire_runtime.Series_active
              { calls = i + 1; failures = 0; deferred = 0; p95_ms = 12.0 };
        })
  in
  let summary : Wire_runtime.tool_series_summary =
    {
      tool_filter = None;
      total_calls = 820;
      total_failures = 0;
      total_deferred = 0;
      p50_ms = Some 5.0;
      p95_ms = Some 12.0;
      failure_classes =
        {
          dependency_unavailable = 0;
          policy_rejection = 0;
          runtime_failure = 0;
          workflow_rejection = 0;
          operator_cancelled = 0;
          unclassified = 0;
        };
      series =
        {
          generated_at_unix = 1_795_254_000.0;
          bucket_width = `Hour;
          utc_offset_min = 0;
          buckets;
        };
    }
  in
  let m_tools_usage =
    let base = Model.initial ~cols:140 ~rows:30 () in
    let runtime =
      base.runtime
      |> Runtime_store.set_tab Nav.Runtime_tools_usage
      |> Runtime_store.set_tools_subview Runtime_store.Tools_usage_calls
      |> Runtime_store.apply_tool_series_summary ~observed_at:t0 summary
    in
    { base with nav = { base.nav with workspace = Nav.Runtime }; runtime }
  in
  let m_tu_dn, _ = step_k m_tools_usage (key Keymap.Input.Down) in
  Alcotest.(check bool)
    "#5b: Tools_usage_calls scrolls using tool_series_summary even when tool_series is Unreported"
    true (m_tu_dn.runtime.scroll_offset > 0);
  let m_tu_clamped = Update_nav.clamp_for_pane m_tu_dn in
  Alcotest.(check int)
    "#5b: clamp_for_pane preserves Tools_usage_calls scroll_offset (no snap to 0)"
    m_tu_dn.runtime.scroll_offset m_tu_clamped.runtime.scroll_offset;

  let m_tool_dive =
    let base = Model.initial ~cols:140 ~rows:30 () in
    let runtime =
      base.runtime
      |> Runtime_store.apply_tool_detail_series ~observed_at:t0 ~tool:"bash"
           summary
    in
    {
      base with
      nav =
        {
          base.nav with
          workspace = Nav.Runtime;
          dive_stack = [ Nav.Dive_runtime (Nav.Tool_dive "bash") ];
          pane_index = 0;
        };
      runtime;
    }
  in
  Alcotest.(check int) "#5a: Tool_dive exposes 2 focusable panes" 2
    (Model.focusable_pane_count m_tool_dive);
  let m_td_tab, _ = step_k m_tool_dive (key Keymap.Input.Tab) in
  Alcotest.(check int) "#5a: Tab in Tool_dive focuses bucket series pane 1" 1
    m_td_tab.nav.pane_index;
  let m_td_dn, _ = step_k m_td_tab (key Keymap.Input.Down) in
  Alcotest.(check bool) "#5a: Down on Tool_dive pane 1 scrolls bucket table" true
    (m_td_dn.runtime.scroll_offset > 0);

  (* #6: Keepers zoomed & split preview reach right detail pane on Keeper_tool_calls *)
  let big_fields =
    List.init 40 (fun i -> (Printf.sprintf "k%02d" i, `String "val"))
  in
  let tc_page : Wire_keeper_context.keeper_tool_calls_page =
    {
      keeper = "alpha";
      count = 1;
      health = Some "healthy";
      stale_reason = None;
      coverage_gaps_count = 0;
      entries =
        [
          {
            ts_unix = 1_795_252_000.0;
            tool = "bash";
            execution_id = Some "exec-1";
            tool_use_id = None;
            turn_kind = Some "direct";
            duration_ms = Some 10.0;
            ok = Some true;
            disposition = Some "completed";
            failure_class = None;
            execution_mode = None;
            batch_index = None;
            batch_size = None;
            definition_source = Some "builtin";
            input = `Assoc big_fields;
            output = "{}";
            original_bytes = Some 512;
            truncated_to = None;
            raw = `Null;
          };
        ];
    }
  in
  let m_kp_tc_base =
    let base = Model.initial ~cols:140 ~rows:30 () in
    let fleet =
      base.fleet
      |> Fleet_store.apply_roster ~observed_at:t0
           (roster_of [ sample_keeper "alpha" ])
      |> Fleet_store.set_keeper_dive_tab Nav.Keeper_tool_calls
    in
    let keeper_context =
      Keeper_context_store.apply_tool_calls ~observed_at:t0 ~keeper:"alpha"
        tc_page base.keeper_context
    in
    {
      base with
      nav = { base.nav with workspace = Nav.Keepers; pane_index = 0 };
      fleet;
      keeper_context;
    }
  in
  Alcotest.(check int)
    "#6: Keepers split with Keeper_tool_calls exposes 3 panes (Fleet/Calls/Detail)"
    3 (Model.focusable_pane_count m_kp_tc_base);
  let m_kp_p1, _ = step_k m_kp_tc_base (key Keymap.Input.Tab) in
  let m_kp_p2, _ = step_k m_kp_p1 (key Keymap.Input.Tab) in
  Alcotest.(check int) "#6: 2nd Tab focuses right call detail pane (2)" 2
    m_kp_p2.nav.pane_index;
  let m_kp_p2_dn, _ = step_k m_kp_p2 (key Keymap.Input.Down) in
  Alcotest.(check bool)
    "#6: Down on Keepers split pane 2 scrolls tool call detail" true
    ((Keeper_context_store.get_keeper ~keeper:"alpha" m_kp_p2_dn.keeper_context)
       .call_detail_scroll_offset
    > 0);
  let m_kp_zoomed =
    {
      m_kp_tc_base with
      nav = { m_kp_tc_base.nav with zoomed = true; pane_index = 0 };
    }
  in
  Alcotest.(check int)
    "#6: Keepers zoomed Keeper_tool_calls exposes 2 inner panes" 2
    (Model.focusable_pane_count m_kp_zoomed);
  let m_kp_z_tab, _ = step_k m_kp_zoomed (key Keymap.Input.Tab) in
  let m_kp_z_dn, _ = step_k m_kp_z_tab (key Keymap.Input.Down) in
  Alcotest.(check bool)
    "#6: Down on Keepers zoomed pane 1 scrolls tool call detail" true
    ((Keeper_context_store.get_keeper ~keeper:"alpha" m_kp_z_dn.keeper_context)
       .call_detail_scroll_offset
    > 0);

  (* #12: Non-destructive sidebar browsing preserves active dive_stack until Enter *)
  let m_in_dive =
    let base = Model.initial ~cols:140 ~rows:36 () in
    {
      base with
      nav =
        {
          base.nav with
          workspace = Nav.Work;
          dive_stack = [ Nav.Dive_work (Nav.Goal_dive "g-keep") ];
        };
    }
  in
  let m_sb_open, _ = step_k m_in_dive (char_key "b") in
  let m_sb_dn, cmds_sb_dn = step_k m_sb_open (key Keymap.Input.Down) in
  Alcotest.(check bool) "#12: Sidebar Down preserves active dive_stack" true
    (Option.is_some (Model.active_dive m_sb_dn));
  Alcotest.(check int) "#12: Sidebar Down emits 0 premature fetches" 0
    (List.length cmds_sb_dn);
  let m_sb_esc, _ = step_k m_sb_dn (key Keymap.Input.Escape) in
  Alcotest.(check bool) "#12: Esc from sidebar returns to untouched Goal_dive"
    true
    (match Model.active_dive m_sb_esc with
    | Some (Nav.Dive_work (Nav.Goal_dive "g-keep")) -> true
    | _ -> false);

  (* #14a: Goal_dive Measure/Procedure scrolls via J/K *)
  let long_goal =
    let base_g = sample_goal ~id:"g-long" ~phase:Wire_work.Executing () in
    let long_txt =
      String.concat "\n\n"
        (List.init 25 (fun i -> Printf.sprintf "Criterion paragraph %02d" i))
    in
    { base_g with measure = long_txt; procedure = long_txt }
  in
  let m_gd =
    let base = Model.initial ~cols:140 ~rows:30 () in
    {
      base with
      nav =
        {
          base.nav with
          workspace = Nav.Work;
          dive_stack = [ Nav.Dive_work (Nav.Goal_dive "g-long") ];
        };
      work =
        Work_store.apply_planning ~observed_at:t0
          { goals = [ long_goal ]; tasks = [] }
          base.work;
    }
  in
  let m_gd_j, _ = step_k m_gd (char_key "J") in
  Alcotest.(check bool) "#14a: [J] in Goal_dive scrolls Measure/Procedure down"
    true (m_gd_j.nav.dive_scroll_offset > 0);
  let m_gd_k, _ = step_k m_gd_j (char_key "K") in
  Alcotest.(check int) "#14a: [K] in Goal_dive scrolls Measure/Procedure back to 0"
    0 m_gd_k.nav.dive_scroll_offset;

  (* #14b: Empty Work > Inbox scrolls Recent Decisions Audit (24h) *)
  let decisions =
    List.init 30 (fun i ->
        {
          Work_store.at_unix = 1_795_254_000.0 -. float_of_int (i * 60);
          kind = Work_store.Decision_tool_approved;
          target_id = Printf.sprintf "dec-%02d" i;
          keeper = Some "alpha";
          summary = Printf.sprintf "Approved %02d" i;
        })
  in
  let m_inb_empty =
    let base = Model.initial ~cols:140 ~rows:26 () in
    {
      base with
      nav = { base.nav with workspace = Nav.Work };
      work =
        {
          (Work_store.set_tab Nav.Work_inbox base.work) with
          recent_decisions_24h = decisions;
        };
    }
    |> Model.rebuild_attention
  in
  let m_inb_dn, _ = step_k m_inb_empty (key Keymap.Input.Down) in
  Alcotest.(check bool)
    "#14b: Down on empty Work_inbox scrolls Recent Decisions Audit table" true
    (m_inb_dn.work.detail_scroll_offset > 0);

  (* #14c: Body mouse wheel hit-tests hovered pane without stealing keyboard focus *)
  let td_rects = Model.pane_rects m_tool_dive in
  (match td_rects with
  | [ _; r_series ] ->
      let m_whl, _ =
        step m_tool_dive
          (Msg.Mouse_event
             (Keymap.Input.Wheel
                {
                  dir = Keymap.Input.Wheel_down;
                  col = r_series.x + 2 + 1;
                  row = r_series.y + 2 + 1;
                }))
      in
      Alcotest.(check bool)
        "#14c: Wheel over Tool_dive pane 1 scrolls series table while pane 0 is focused"
        true (m_whl.runtime.scroll_offset > 0);
      Alcotest.(check int)
        "#14c: Wheel over hovered pane preserves keyboard focus on pane 0" 0
        m_whl.nav.pane_index
  | _ -> Alcotest.fail "expected 2 Tool_dive rects");

  (* #15c: Overlay -> Dive return path restores Incidents and Ask_answer *)
  let inc_store, inc =
    Incidents.push ~occurred_at_unix:1_795_254_000.0
      ~source:Health.Source_client_http
      ~summary:(Say.literal "Timeout") ~detail:"GET /health timed out"
      ~status:Health.Resolved Incidents.empty
  in
  let m_inc =
    let base = Model.initial ~cols:140 ~rows:30 () in
    {
      base with
      nav = { base.nav with overlay = Some Nav.Incidents };
      incidents = inc_store;
    }
  in
  let m_inc_dive, _ = step_k m_inc (key Keymap.Input.Enter) in
  Alcotest.(check bool) "#15c: Enter in Incidents pushes Incident_dive" true
    (match Model.active_dive m_inc_dive with
    | Some (Nav.Dive_infra (Nav.Incident_dive id)) -> Int.equal id inc.id
    | _ -> false);
  let m_inc_back, _ = step_k m_inc_dive (key Keymap.Input.Escape) in
  Alcotest.(check bool) "#15c: Esc from Incident_dive restores Incidents overlay"
    true (Option.equal Nav.equal_overlay m_inc_back.nav.overlay (Some Nav.Incidents));

  let ask = sample_ask ~id:"ask-ret-1" ~keeper:"alpha" () in
  let m_ask_ov =
    let base = Model.initial ~cols:140 ~rows:30 () in
    {
      base with
      nav = { base.nav with overlay = Some Nav.Ask_answer };
