      infra =
        base.infra
        |> Infra_store.set_tab Nav.Infra_code
        |> Infra_store.set_code_right_mode Infra_store.Code_git_status;
    }
  in
  let m_code_esc, _ = step_k m_code_git (key Keymap.Input.Escape) in
