                         {
                           req =
                             Cmd.Post_gate_mode
                               {
                                 external_lane = false;
                                 mode = Wire_work.Gate_manual;
                               };
                           _;
                         } ->
                         true
                     | _ -> false)
                   cmds_mode);
              let _, cmds_del = run_slash m1 "/gate del-rule rule-1" in
              Alcotest.(check bool) "/gate del-rule emits Post_gate_rule_delete"
                true
                (List.exists
                   (function
                     | Cmd.Http_post
                         { req = Cmd.Post_gate_rule_delete { id = "rule-1" }; _ }
                       ->
