              let _, cmds_retry = run_slash m1 "/gate retry appr-1" in
              Alcotest.(check bool) "/gate retry emits Post_gate_retry" true
                (List.exists
                   (function
                     | Cmd.Http_post
                         { req = Cmd.Post_gate_retry { meta; _ }; _ }
                       when String.equal meta.id "appr-1" ->
