              let _, cmds_km = run_slash m1 "/gate keeper-mode alpha yolo" in
              Alcotest.(check bool)
                "/gate keeper-mode emits Post_keeper_tool_approval_mode" true
                (List.exists
                   (function
                     | Cmd.Http_post
