              Alcotest.(check bool) "tui.hints_visible emits 0 Post_tui_preference"
                false (is_pref_post (fun _ -> true) cmds_hints);
              (* Board [S] cycle matches Settings valid_board_sort_values 1:1 *)
              let m_board0 =
