                "Fallback mode Right steps CLI Lang_en -> Lang_ko" true
                (Say.equal_lang m_fb_lang1.lang Say.Lang_ko);
              let cfg_hyphen =
                Config_store.apply_preferences ~observed_at:t0
                  {
