                |> Knowledge_store.set_tab Nav.Knowledge_artifacts
                |> Knowledge_store.apply_artifacts ~observed_at:t0 [ art_entry ]
                |> Knowledge_store.apply_artifact_detail ~observed_at:t0
                     art_detail
